// @system @ref LLP 0210 — Contract hydration manifest schema + corpus helpers.

import { NodeKind, type ElementNode, type RootNode, type TextNode } from '@exact/renderer/host-ops';

export type JsonValue =
  | null
  | boolean
  | number
  | string
  | JsonValue[]
  | { [key: string]: JsonValue };

export interface ContractHydrationComponentState {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName: string;
  state: Record<string, JsonValue>;
}

export interface ContractHydrationStateSnapshotRef {
  ref?: string;
  componentState: ContractHydrationComponentState[];
}

export interface ContractHydrationResourceSnapshot {
  nodeId: string;
  key: string;
  generation: number;
  status: 'ready' | 'error' | 'loading';
  value?: JsonValue;
  error?: { message: string; code?: string };
}

export interface ContractHydrationQuerySnapshot {
  nodeId: string;
  key: string;
  generation: number;
  status: 'ready' | 'error' | 'loading';
  value?: JsonValue;
  error?: { message: string; code?: string };
}

export interface ContractHydrationNodeAnchor {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  domPath: number[];
  kind: 'element' | 'text' | 'component' | 'resource' | 'async' | 'boundary';
  tag?: string;
  textGuard?: string;
}

// `scrollend`/`refresh` are deliberately absent: the spellings are reserved
// in the grammar but have no host lowering, and the analyzer rejects them on
// built-in elements at compile time (ENG-23128).
export type ContractHydrationEvent =
  | 'press'
  | 'change'
  | 'submit'
  | 'longpress'
  | 'focus'
  | 'blur';

export interface ContractHydrationHandlerSlot {
  nodeId: string;
  structuralId?: string;
  event: ContractHydrationEvent;
  actionId: string;
}

export interface ContractHydrationCapabilityBag {
  nowMs: number;
  randomSeed?: string;
  locale?: string;
  timeZone?: string;
  /** Prerender viewport replayed by the `viewport` capability (ENG-22563). */
  viewport?: { width: number; height: number };
  resourceGenerations?: Record<string, number>;
  scroll?: Array<{ nodeId: string; x: number; y: number }>;
  focus?: { nodeId: string };
}

export interface ContractHydrationVerification {
  adoptedNodeCount: number;
  recreatedNodeCount: number;
  hydrationMismatchCount: number;
  adoptionFallbacks: string[];
  serverHtmlHash?: string;
  firstPaintHtmlHash?: string;
  firstPaintByteIdentical?: boolean;
  deferredMountTasks: number;
  tasksReleasedBeforeAdoption: boolean;
}

export interface ContractHydrationManifest {
  version: 1;
  rootId: number;
  routeId: string;
  buildId: string;
  sourceVersion: string;
  state: ContractHydrationStateSnapshotRef;
  resources: ContractHydrationResourceSnapshot[];
  queries: ContractHydrationQuerySnapshot[];
  nodes: ContractHydrationNodeAnchor[];
  handlers: ContractHydrationHandlerSlot[];
  capabilities: ContractHydrationCapabilityBag;
  verification?: ContractHydrationVerification;
}

export interface ContractHydrationRuntimeOptions {
  capabilities?: Partial<ContractHydrationCapabilityBag>;
  capture?: ContractHydrationCapture;
  deferMountTasks?: boolean;
}

interface CapturedNode {
  hostId: number;
  nodeId: string;
  structuralId: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  kind: 'element' | 'text';
  tag?: string;
}

export interface ContractHydrationNodeInput {
  host: ElementNode | TextNode;
  nodeId: string;
  structuralId: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName?: string;
  kind: 'element' | 'text';
  tag?: string;
}

export interface ContractHydrationComponentStateInput {
  nodeId: string;
  structuralId?: string;
  sourcePath?: string;
  sourceVersion?: string;
  componentName: string;
  state: Record<string, unknown>;
}

export interface ContractHydrationCaptureOptions {
  nowMs?: number;
  locale?: string;
  timeZone?: string;
  randomSeed?: string;
  /**
   * The prerender window's viewport (ENG-22563). Recorded into the
   * capability bag so the client's first hydration render replays the size
   * the SSG baked into viewport-bound styles, then flips to the live window
   * when adoption releases.
   */
  viewport?: { width: number; height: number };
}

export class ContractHydrationCapture {
  readonly capabilities: ContractHydrationCapabilityBag;
  private readonly nodesByHostId = new Map<number, CapturedNode>();
  private readonly componentState = new Map<string, ContractHydrationComponentState>();
  private readonly handlers: ContractHydrationHandlerSlot[] = [];
  private deferredMountTasks = 0;
  private tasksReleasedBeforeAdoption = false;

  constructor(options: ContractHydrationCaptureOptions = {}) {
    this.capabilities = {
      nowMs: options.nowMs ?? Date.now(),
      ...(options.randomSeed ? { randomSeed: options.randomSeed } : {}),
      ...(options.locale ? { locale: options.locale } : {}),
      ...(options.timeZone ? { timeZone: options.timeZone } : {}),
      ...(options.viewport ? { viewport: { ...options.viewport } } : {}),
    };
  }

  recordNode(input: ContractHydrationNodeInput): void {
    this.nodesByHostId.set(input.host.id, {
      hostId: input.host.id,
      nodeId: input.nodeId,
      structuralId: input.structuralId,
      sourcePath: input.sourcePath,
      sourceVersion: input.sourceVersion,
      componentName: input.componentName,
      kind: input.kind,
      tag: input.tag,
    });
  }

  recordComponentState(input: ContractHydrationComponentStateInput): void {
    const state = jsonRecord(input.state);
    this.componentState.set(input.nodeId, {
      nodeId: input.nodeId,
      ...(input.structuralId ? { structuralId: input.structuralId } : {}),
      ...(input.sourcePath ? { sourcePath: input.sourcePath } : {}),
      ...(input.sourceVersion ? { sourceVersion: input.sourceVersion } : {}),
      componentName: input.componentName,
      state,
    });
  }

  recordHandler(slot: ContractHydrationHandlerSlot): void {
    if (this.handlers.some((candidate) =>
      candidate.nodeId === slot.nodeId &&
      candidate.event === slot.event &&
      candidate.actionId === slot.actionId
    )) {
      return;
    }
    this.handlers.push(slot);
  }

  noteDeferredMountTasks(count: number): void {
    this.deferredMountTasks = Math.max(this.deferredMountTasks, count);
  }

  noteMountTasksReleasedBeforeAdoption(): void {
    this.tasksReleasedBeforeAdoption = true;
  }

  snapshot(): {
    nodesByHostId: ReadonlyMap<number, CapturedNode>;
    componentState: ContractHydrationComponentState[];
    handlers: ContractHydrationHandlerSlot[];
    deferredMountTasks: number;
    tasksReleasedBeforeAdoption: boolean;
  } {
    return {
      nodesByHostId: this.nodesByHostId,
      componentState: [...this.componentState.values()],
      handlers: [...this.handlers],
      deferredMountTasks: this.deferredMountTasks,
      tasksReleasedBeforeAdoption: this.tasksReleasedBeforeAdoption,
    };
  }
}

export function createContractHydrationCapture(
  options: ContractHydrationCaptureOptions = {},
): ContractHydrationCapture {
  return new ContractHydrationCapture(options);
}

export function contractHydrationNodeId(input: {
  prefix: string;
  structuralId: string;
  keyChain: string;
}): string {
  return `${input.prefix}${input.structuralId}${input.keyChain}`;
}

export function attachContractHydrationTextId(text: TextNode, nodeId: string): void {
  (text as TextNode & { __exactHydrationId?: string }).__exactHydrationId = nodeId;
}

export function getContractHydrationIdForHostNode(
  node: ElementNode | TextNode,
): string | undefined {
  if (node.kind === NodeKind.Text) {
    return (node as TextNode & { __exactHydrationId?: string }).__exactHydrationId;
  }
  const value = (node.originalProps as Record<string, unknown>)['data-exact-hydration-id'];
  return typeof value === 'string' ? value : undefined;
}

export function buildContractHydrationManifest(input: {
  capture: ContractHydrationCapture;
  root: RootNode;
  domRoot?: ParentNode;
  rootId: number;
  routeId: string;
  buildId: string;
  sourceVersion: string;
  serverHtml?: string;
  firstPaintHtml?: string;
}): ContractHydrationManifest {
  const snapshot = input.capture.snapshot();
  const anchors: ContractHydrationNodeAnchor[] = [];
  const mismatches: string[] = [];
  const seenHostIds = new Set<number>();

  walkHostTree(input.root, input.domRoot, [], (host, domPath, domNode) => {
    const captured = snapshot.nodesByHostId.get(host.id);
    if (!captured) {
      return;
    }
    seenHostIds.add(host.id);
    const anchor: ContractHydrationNodeAnchor = {
      nodeId: captured.nodeId,
      structuralId: captured.structuralId,
      ...(captured.sourcePath ? { sourcePath: captured.sourcePath } : {}),
      ...(captured.sourceVersion ? { sourceVersion: captured.sourceVersion } : {}),
      ...(captured.componentName ? { componentName: captured.componentName } : {}),
      domPath,
      kind: captured.kind,
      ...(captured.tag ? { tag: captured.tag } : {}),
    };
    if (host.kind === NodeKind.Text) {
      anchor.textGuard = host.text;
    } else if (domNode?.nodeType === 1) {
      anchor.tag = (domNode as Element).localName;
    }
    if (domNode) {
      const mismatch = domMismatchFor(anchor, domNode);
      if (mismatch) {
        mismatches.push(mismatch);
      }
    }
    anchors.push(anchor);
  });

  for (const captured of snapshot.nodesByHostId.values()) {
    if (!seenHostIds.has(captured.hostId)) {
      mismatches.push(`host node ${captured.hostId} (${captured.nodeId}) was not reachable from the root`);
    }
  }

  const serverHash = input.serverHtml ? sha256(input.serverHtml) : undefined;
  const firstPaintHash = input.firstPaintHtml ? sha256(input.firstPaintHtml) : undefined;

  return {
    version: 1,
    rootId: input.rootId,
    routeId: input.routeId,
    buildId: input.buildId,
    sourceVersion: input.sourceVersion,
    state: {
      componentState: snapshot.componentState,
    },
    resources: [],
    queries: [],
    nodes: anchors,
    handlers: snapshot.handlers,
    capabilities: input.capture.capabilities,
    verification: {
      adoptedNodeCount: anchors.length - mismatches.length,
      recreatedNodeCount: mismatches.length,
      hydrationMismatchCount: mismatches.length,
      adoptionFallbacks: mismatches,
      ...(serverHash ? { serverHtmlHash: serverHash } : {}),
      ...(firstPaintHash ? { firstPaintHtmlHash: firstPaintHash } : {}),
      ...(serverHash && firstPaintHash ? { firstPaintByteIdentical: serverHash === firstPaintHash } : {}),
      deferredMountTasks: snapshot.deferredMountTasks,
      tasksReleasedBeforeAdoption: snapshot.tasksReleasedBeforeAdoption,
    },
  };
}

export function validateContractHydrationManifest(
  manifest: unknown,
): { ok: true; manifest: ContractHydrationManifest } | { ok: false; errors: string[] } {
  const errors: string[] = [];
  if (!manifest || typeof manifest !== 'object') {
    return { ok: false, errors: ['manifest must be an object'] };
  }
  const candidate = manifest as Partial<ContractHydrationManifest>;
  if (candidate.version !== 1) errors.push('version must be 1');
  if (typeof candidate.rootId !== 'number' || !Number.isInteger(candidate.rootId)) {
    errors.push('rootId must be an integer');
  }
  for (const field of ['routeId', 'buildId', 'sourceVersion'] as const) {
    if (typeof candidate[field] !== 'string' || candidate[field]!.length === 0) {
      errors.push(`${field} must be a non-empty string`);
    }
  }
  if (!candidate.capabilities || typeof candidate.capabilities.nowMs !== 'number') {
    errors.push('capabilities.nowMs must be a number');
  }
  if (!candidate.state || !Array.isArray(candidate.state.componentState)) {
    errors.push('state.componentState must be an array');
  }
  if (!Array.isArray(candidate.resources)) errors.push('resources must be an array');
  if (!Array.isArray(candidate.queries)) errors.push('queries must be an array');
  if (!Array.isArray(candidate.nodes)) {
    errors.push('nodes must be an array');
  } else {
    const nodeIds = new Set<string>();
    for (const [index, node] of candidate.nodes.entries()) {
      if (!node || typeof node !== 'object') {
        errors.push(`nodes[${index}] must be an object`);
        continue;
      }
      const anchor = node as Partial<ContractHydrationNodeAnchor>;
      if (typeof anchor.nodeId !== 'string' || anchor.nodeId.length === 0) {
        errors.push(`nodes[${index}].nodeId must be a non-empty string`);
      } else if (nodeIds.has(anchor.nodeId)) {
        errors.push(`duplicate nodeId ${anchor.nodeId}`);
      } else {
        nodeIds.add(anchor.nodeId);
      }
      if (!Array.isArray(anchor.domPath) || anchor.domPath.some((part) => !Number.isInteger(part) || part < 0)) {
        errors.push(`nodes[${index}].domPath must be a non-negative integer array`);
      }
      if (anchor.kind !== 'element' && anchor.kind !== 'text' && anchor.kind !== 'component' &&
        anchor.kind !== 'resource' && anchor.kind !== 'async' && anchor.kind !== 'boundary') {
        errors.push(`nodes[${index}].kind is invalid`);
      }
    }
  }
  if (!Array.isArray(candidate.handlers)) {
    errors.push('handlers must be an array');
  }
  return errors.length === 0
    ? { ok: true, manifest: candidate as ContractHydrationManifest }
    : { ok: false, errors };
}

export function simulateContractHydrationAdoption(
  manifest: ContractHydrationManifest,
  domRoot: ParentNode,
): ContractHydrationVerification {
  const mismatches: string[] = [];
  let adopted = 0;
  for (const anchor of manifest.nodes) {
    const domNode = resolveDomPath(domRoot, anchor.domPath);
    if (!domNode) {
      mismatches.push(`${anchor.nodeId}: domPath ${anchor.domPath.join('.')} did not resolve`);
      continue;
    }
    const mismatch = domMismatchFor(anchor, domNode);
    if (mismatch) {
      mismatches.push(mismatch);
      continue;
    }
    adopted += 1;
  }
  return {
    adoptedNodeCount: adopted,
    recreatedNodeCount: mismatches.length,
    hydrationMismatchCount: mismatches.length,
    adoptionFallbacks: mismatches,
    deferredMountTasks: manifest.verification?.deferredMountTasks ?? 0,
    tasksReleasedBeforeAdoption: manifest.verification?.tasksReleasedBeforeAdoption ?? false,
  };
}

function walkHostTree(
  root: RootNode,
  domRoot: ParentNode | undefined,
  path: number[],
  visit: (node: ElementNode | TextNode, domPath: number[], domNode: Node | null) => void,
): void {
  const walkChildren = (
    children: Array<ElementNode | TextNode>,
    domParent: ParentNode | undefined,
    parentPath: number[],
  ): void => {
    children.forEach((child, index) => {
      const domPath = [...parentPath, index];
      const domNode = domParent?.childNodes.item(index) ?? null;
      visit(child, domPath, domNode);
      if (child.kind === NodeKind.Element) {
        const nextDomParent = domNode && 'childNodes' in domNode
          ? (domNode as unknown as ParentNode)
          : undefined;
        walkChildren(child.children as Array<ElementNode | TextNode>, nextDomParent, domPath);
      }
    });
  };
  walkChildren(root.children as Array<ElementNode | TextNode>, domRoot, path);
}

function resolveDomPath(root: ParentNode, domPath: readonly number[]): Node | null {
  let current: ParentNode | Node = root;
  for (const index of domPath) {
    if (!('childNodes' in current)) {
      return null;
    }
    const next = current.childNodes.item(index);
    if (!next) {
      return null;
    }
    current = next;
  }
  return current as Node;
}

function domMismatchFor(anchor: ContractHydrationNodeAnchor, domNode: Node): string | null {
  if (anchor.kind === 'element') {
    if (domNode.nodeType !== 1) {
      return `${anchor.nodeId}: expected element, got nodeType ${domNode.nodeType}`;
    }
    const element = domNode as Element;
    if (anchor.tag && element.localName !== anchor.tag) {
      return `${anchor.nodeId}: expected <${anchor.tag}>, got <${element.localName}>`;
    }
    const hydrationId = element.getAttribute('data-exact-hydration-id');
    if (hydrationId !== anchor.nodeId) {
      return `${anchor.nodeId}: data-exact-hydration-id mismatch (${hydrationId ?? 'missing'})`;
    }
  }
  if (anchor.kind === 'text') {
    if (domNode.nodeType !== 3) {
      return `${anchor.nodeId}: expected text, got nodeType ${domNode.nodeType}`;
    }
    if (anchor.textGuard !== undefined && domNode.nodeValue !== anchor.textGuard) {
      return `${anchor.nodeId}: textGuard mismatch`;
    }
  }
  return null;
}

function jsonRecord(input: Record<string, unknown>): Record<string, JsonValue> {
  const out: Record<string, JsonValue> = {};
  for (const [key, value] of Object.entries(input)) {
    const json = toJsonValue(value);
    if (json !== undefined) {
      out[key] = json;
    }
  }
  return out;
}

function toJsonValue(value: unknown): JsonValue | undefined {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return value as JsonValue;
  }
  if (typeof value === 'number') {
    return Number.isFinite(value) ? value : null;
  }
  if (Array.isArray(value)) {
    return value.map((item) => toJsonValue(item) ?? null);
  }
  if (typeof value === 'object' && value !== null) {
    const out: Record<string, JsonValue> = {};
    for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
      const json = toJsonValue(nested);
      if (json !== undefined) {
        out[key] = json;
      }
    }
    return out;
  }
  return undefined;
}

function sha256(value: string): string {
  // Browser-safe stable hash. The verifier compares equality, not
  // cryptographic strength, and @exact/contract/runtime is client-loaded.
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a32:${(hash >>> 0).toString(16).padStart(8, '0')}`;
}
