// @system @ref LLP 0183 S0 — descriptor normalization shared by the compiler
// and the runtime descriptor surface (`@exact/contract/exports`).
//
// CLIENT-GRAPH LEAF (ENG-22537): this module is reachable from the browser
// bundle through `@exact/contract/channels` / `@exact/contract/exports` and
// the app-side `.contract-meta.ts` sidecars. It must stay dependency-free of
// the compiler proper — no `typescript`, no `node:*` builtins, no value
// imports beyond type-erased `./ir.js` types. The guard test in
// `src/__tests__/import-boundaries.test.ts` ("channels client graph") fails
// the build if this leaf (or anything else on those entries) regrows a
// compiler-side value edge.

import type {
  ContractImportConfidence,
  ContractImportDescriptor,
  ContractImportKind,
  ContractImportProvenance,
  PublishBudgetDescriptor,
  ShapeFieldDescriptor,
  ShapeImportDescriptor,
  StyleRecipeOutputDescriptor,
} from './ir.js';

export type ContractImportDescriptorInput =
  | Omit<ContractImportDescriptor, 'confidence' | 'provenance'>
  | ContractImportDescriptor;

export type ContractImportDescriptorMap = Record<string, ContractImportDescriptorInput>;

const IMPORT_KINDS = new Set<ContractImportKind>([
  'component',
  'pure',
  'shape',
  'styleRecipe',
  'store',
  'capability',
  'query',
  'mutation',
  'ephemeral',
  'publish',
  'opaque',
]);

function declaredProvenance(): ContractImportProvenance {
  return { source: 'module-export' };
}

export function staticProvenance(file?: string): ContractImportProvenance {
  return file ? { source: 'contract-ir', file } : { source: 'contract-ir' };
}

export function opaqueDescriptor(): ContractImportDescriptor {
  return { kind: 'opaque', confidence: 'opaque', provenance: { source: 'opaque' } };
}

// LLP 0284 §2.4 liveness facts on query/ephemeral sidecar descriptors
// (ENG-22526): parsed defensively — a malformed fact degrades to absence,
// never to an error (the field names match §2.4 exactly).
const IMPORT_LIVENESS_MODES = new Set(['snapshot', 'live', 'poll', 'reconcile-on-mutate']);
const IMPORT_LIVENESS_TRANSPORTS = new Set(['push', 'poll', 'reconcile-on-mutate']);

function livenessFacts(value: Record<string, unknown>): {
  mode?: 'snapshot' | 'live' | 'poll' | 'reconcile-on-mutate';
  livePush?: boolean;
  initialSnapshot?: boolean;
  pollCadenceMs?: number;
  transport?: 'push' | 'poll' | 'reconcile-on-mutate';
  ephemeral?: boolean;
} {
  return {
    mode:
      typeof value.mode === 'string' && IMPORT_LIVENESS_MODES.has(value.mode)
        ? (value.mode as 'snapshot' | 'live' | 'poll' | 'reconcile-on-mutate')
        : undefined,
    livePush: typeof value.livePush === 'boolean' ? value.livePush : undefined,
    initialSnapshot: typeof value.initialSnapshot === 'boolean' ? value.initialSnapshot : undefined,
    pollCadenceMs:
      typeof value.pollCadenceMs === 'number' && Number.isFinite(value.pollCadenceMs)
        ? value.pollCadenceMs
        : undefined,
    transport:
      typeof value.transport === 'string' && IMPORT_LIVENESS_TRANSPORTS.has(value.transport)
        ? (value.transport as 'push' | 'poll' | 'reconcile-on-mutate')
        : undefined,
    ephemeral: typeof value.ephemeral === 'boolean' ? value.ephemeral : undefined,
  };
}

function hasOwn<K extends string>(
  object: Record<string, unknown>,
  key: K,
): object is Record<K, unknown> {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function stringArray(value: unknown): string[] | null {
  if (!Array.isArray(value)) {
    return null;
  }
  return value.every((entry) => typeof entry === 'string') ? value : null;
}

function normalizePublishBudget(value: unknown): PublishBudgetDescriptor | undefined {
  if (value === undefined || value === null) {
    return undefined;
  }
  if (typeof value !== 'object' || Array.isArray(value)) {
    // Declared but malformed (e.g. budget: "20Hz"): keep an EMPTY budget
    // rather than undefined, so the analyzer can distinguish "the
    // generator declared facts, none usable" (warned — the rate gate
    // would silently skip otherwise) from "no budget declared"
    // (documented degradation, no diagnostic).
    return {};
  }
  const record = value as Record<string, unknown>;
  const budget: PublishBudgetDescriptor = {};
  for (const field of ['sustainedHz', 'burst', 'maxValueBytes'] as const) {
    const candidate = record[field];
    if (typeof candidate === 'number' && Number.isFinite(candidate)) {
      budget[field] = candidate;
    }
  }
  return budget;
}

function normalizeShapeFieldDescriptor(value: unknown): ShapeFieldDescriptor {
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
    const record = value as Record<string, unknown>;
    if (typeof record.type !== 'string') {
      throw new Error(`shape field descriptors require type="..."`);
    }
    return {
      type: record.type,
      optional: record.optional === true,
    };
  }
  throw new Error(`shape field descriptors must be a type string or { type, optional }`);
}

function normalizeShapeFields(value: unknown): Record<string, ShapeFieldDescriptor> | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new Error(`shape descriptor fields must be an object`);
  }
  const fields: Record<string, ShapeFieldDescriptor> = {};
  for (const [name, descriptor] of Object.entries(value as Record<string, unknown>)) {
    fields[name] = normalizeShapeFieldDescriptor(descriptor);
  }
  return fields;
}

function normalizeShapeVariants(value: unknown): Record<string, { fields: Record<string, ShapeFieldDescriptor> }> | undefined {
  if (value === undefined) {
    return undefined;
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new Error(`shape descriptor variants must be an object`);
  }
  const variants: Record<string, { fields: Record<string, ShapeFieldDescriptor> }> = {};
  for (const [tag, variant] of Object.entries(value as Record<string, unknown>)) {
    if (typeof variant !== 'object' || variant === null || Array.isArray(variant)) {
      throw new Error(`shape variant "${tag}" must be an object`);
    }
    const record = variant as Record<string, unknown>;
    const fields = normalizeShapeFields(record.fields ?? record);
    variants[tag] = { fields: fields ?? {} };
  }
  return variants;
}

export function normalizeContractImportDescriptor(
  input: ContractImportDescriptorInput,
  options?: { provenance?: ContractImportProvenance; confidence?: ContractImportConfidence },
): ContractImportDescriptor {
  const value = input as Record<string, unknown>;
  const rawKind = value.kind;
  if (typeof rawKind !== 'string' || !IMPORT_KINDS.has(rawKind as ContractImportKind)) {
    throw new Error(`contract import descriptor must declare a valid kind`);
  }
  const kind = rawKind as ContractImportKind;

  const confidence =
    typeof value.confidence === 'string'
      ? (value.confidence as ContractImportConfidence)
      : options?.confidence ?? (kind === 'component' ? 'static' : 'declared');
  const provenance =
    typeof value.provenance === 'object' && value.provenance !== null
      ? (value.provenance as ContractImportProvenance)
      : options?.provenance ?? (kind === 'component' ? staticProvenance() : declaredProvenance());

  switch (kind) {
    case 'component':
      return { kind, confidence, provenance };
    case 'pure': {
      const depends = value.depends;
      if (depends !== 'args' && stringArray(depends) === null) {
        throw new Error(`pure descriptor requires depends="args" or depends=[...]`);
      }
      return {
        kind,
        confidence,
        provenance,
        params: stringArray(value.params) ?? undefined,
        result: typeof value.result === 'string' ? value.result : undefined,
        depends: depends === 'args' ? 'args' : stringArray(depends)!,
      };
    }
    case 'shape': {
      const fields = normalizeShapeFields(value.fields);
      const variants = normalizeShapeVariants(value.variants);
      return {
        kind,
        confidence,
        provenance,
        fields,
        discriminant: typeof value.discriminant === 'string' ? value.discriminant : undefined,
        variants,
      } satisfies ShapeImportDescriptor;
    }
    case 'styleRecipe': {
      const reads = stringArray(value.reads);
      if (!reads) {
        throw new Error(`styleRecipe descriptor requires reads=[...]`);
      }
      if (typeof value.outputs !== 'object' || value.outputs === null || Array.isArray(value.outputs)) {
        throw new Error(`styleRecipe descriptor requires outputs={...}`);
      }
      return {
        kind,
        confidence,
        provenance,
        component: typeof value.component === 'string' ? value.component : undefined,
        params: stringArray(value.params) ?? undefined,
        reads,
        outputs: value.outputs as Record<string, StyleRecipeOutputDescriptor>,
      };
    }
    case 'store':
      return {
        kind,
        confidence,
        provenance,
        reads: stringArray(value.reads) ?? undefined,
        effects: stringArray(value.effects) ?? undefined,
        snapshotReadable: value.snapshotReadable === true,
      };
    case 'capability': {
      const effects = stringArray(value.effects);
      if (!effects) {
        throw new Error(`capability descriptor requires effects=[...]`);
      }
      return {
        kind,
        confidence,
        provenance,
        params: hasOwn(value, 'params') && typeof value.params === 'object' && value.params !== null
          ? (value.params as Record<string, unknown>)
          : undefined,
        effects,
        // LLP 0281 stage 0: value-channel capability marker (e.g. 'pointer').
        channel: typeof value.channel === 'string' ? value.channel : undefined,
      };
    }
    case 'query':
      return {
        kind,
        confidence,
        provenance,
        reads: stringArray(value.reads) ?? undefined,
        invalidates: stringArray(value.invalidates) ?? undefined,
        readMode: value.readMode === 'sync' || value.readMode === 'async' ? value.readMode : undefined,
        cacheKey: typeof value.cacheKey === 'string' ? value.cacheKey : undefined,
        result: typeof value.result === 'string' ? value.result : undefined,
        ...livenessFacts(value),
      };
    // LLP 0284 §2.5: generated `*.ephemeral.ts` read descriptors.
    case 'ephemeral':
      return {
        kind,
        confidence,
        provenance,
        reads: stringArray(value.reads) ?? undefined,
        result: typeof value.result === 'string' ? value.result : undefined,
        ...livenessFacts(value),
      };
    // LLP 0281 §3.1 (ENG-22525): generated `*.publish.ts` ephemeral publish
    // descriptors — the rated `publish` line's target kind.
    case 'publish': {
      const effects = stringArray(value.effects);
      if (!effects) {
        throw new Error(`publish descriptor requires effects=[...]`);
      }
      return {
        kind,
        confidence,
        provenance,
        params: hasOwn(value, 'params') && typeof value.params === 'object' && value.params !== null
          ? (value.params as Record<string, unknown>)
          : undefined,
        effects,
        budget: normalizePublishBudget(value.budget),
      };
    }
    case 'mutation': {
      const effects = stringArray(value.effects);
      if (!effects) {
        throw new Error(`mutation descriptor requires effects=[...]`);
      }
      return {
        kind,
        confidence,
        provenance,
        params: hasOwn(value, 'params') && typeof value.params === 'object' && value.params !== null
          ? (value.params as Record<string, unknown>)
          : undefined,
        effects,
        invalidates: stringArray(value.invalidates) ?? undefined,
        // LLP 0281 stage 0: publish budget facts on mutation-shaped
        // ephemeral publish descriptors (rate checked by the analyzer).
        publishBudget: normalizePublishBudget(value.publishBudget),
      };
    }
    case 'opaque':
      return opaqueDescriptor();
  }
}
