// @system @ref LLP 0166 §4.7 — versioned structural identity (runtime side).
//
// Live host nodes register under their structural id at mount and leave at
// dispose. `runtimeNodeKey` = structuralId + the `each`-key chain — the
// identity of one live node among many keyed instances. Dev-only (the same
// gate as provenance); production mounts skip registration entirely.
//
// Each entry carries the patch hooks the S4 hot-patch pipeline drives:
// closures created inside the mount path so a patched value lands in the
// SAME objects future effect runs rebuild from (no revert on the next
// reactive flush).

export interface LiveNodePatchElement {
  kind: 'element';
  /**
   * Applies static prop/style mutations through the element's own
   * lastProps chain (updateInstanceProps semantics preserved).
   */
  applyStatic(mutation: {
    props?: Record<string, unknown>;
    style?: Record<string, unknown>;
  }): void;
  /** Authored attr name -> lowered host target. */
  attrTargets: Record<string, { target: 'prop' | 'style'; name: string }>;
}

export interface LiveNodePatchText {
  kind: 'text';
  setText(value: string): void;
}

export type LiveNodePatch = LiveNodePatchElement | LiveNodePatchText;

export interface LiveNodeEntry {
  structuralId: string;
  sourcePath?: string;
  sourceVersion?: string;
  /** `each`-key chain ('' outside keyed regions; '#k1#k2' nested). */
  keyChain: string;
  host: object;
  patch: LiveNodePatch;
}

const byStructuralId = new Map<string, Set<LiveNodeEntry>>();
const byHost = new WeakMap<object, LiveNodeEntry>();
const interactionByHost = new WeakMap<object, { force?: (state: Record<string, boolean>) => void }>();
let handleInstalled = false;

function ensureGlobalHandle(): void {
  if (handleInstalled) {
    return;
  }
  handleInstalled = true;
  (globalThis as Record<string, unknown>).__exactContractIdentity = {
    lookup: lookupLiveNode,
  };
  // Interaction-state forcing (LLP 0163 E1d): pin hover/pressed/focus on a
  // live node from the panel, using the behavior instance attached at mount.
  (globalThis as Record<string, unknown>).__exactContractInteraction = {
    force: forceInteractionState,
    has: hasInteraction,
  };
}

/** Registered at mount for elements carrying an interaction= behavior. */
export function registerInteractionTarget(
  host: object,
  behavior: { force?: (state: Record<string, boolean>) => void },
): void {
  ensureGlobalHandle();
  interactionByHost.set(host, behavior);
}

export function hasInteraction(host: object): boolean {
  return typeof interactionByHost.get(host)?.force === 'function';
}

export function forceInteractionState(host: object, state: Record<string, boolean>): boolean {
  const behavior = interactionByHost.get(host);
  if (!behavior || typeof behavior.force !== 'function') {
    return false;
  }
  behavior.force(state);
  return true;
}

/** Registers a live node; returns the cleanup the mount owner must run. */
export function registerLiveNode(entry: LiveNodeEntry): () => void {
  ensureGlobalHandle();
  byHost.set(entry.host, entry);
  let set = byStructuralId.get(entry.structuralId);
  if (!set) {
    set = new Set();
    byStructuralId.set(entry.structuralId, set);
  }
  set.add(entry);
  return () => {
    set!.delete(entry);
    if (set!.size === 0) {
      byStructuralId.delete(entry.structuralId);
    }
    byHost.delete(entry.host);
  };
}

/** Every live instance of a structural id (one per each-key instance). */
export function getLiveNodes(structuralId: string): LiveNodeEntry[] {
  const set = byStructuralId.get(structuralId);
  return set ? [...set] : [];
}

/** Identity of one live host (the panel's selection rebinding reads this). */
export function lookupLiveNode(host: object): {
  structuralId: string;
  sourceVersion?: string;
  sourcePath?: string;
  runtimeNodeKey: string;
} | undefined {
  const entry = byHost.get(host);
  if (!entry) {
    return undefined;
  }
  return {
    structuralId: entry.structuralId,
    sourceVersion: entry.sourceVersion,
    sourcePath: entry.sourcePath,
    runtimeNodeKey: `${entry.structuralId}${entry.keyChain}`,
  };
}
