// @system @ref LLP 0208 A0 - Design Mode axis-aware edit scope ladder.
//
// Axis scope is metadata around an existing edit op target. The edit authority
// and op shape do not change; only the design-override key changes.

import type { ContractScenarioMatrixCellInput } from './scenario-matrix.js';

export const CONTRACT_AXIS_SCOPE_SCHEMA_VERSION = 1;

export type ContractAxisScopeRung = 'all' | 'axis-value' | 'axis-slice' | 'cell';
export type ContractAxisPromotion = 'row' | 'column' | 'all';

export interface ContractAxisScopedBaseOp {
  op: string;
  value?: unknown;
  [key: string]: unknown;
}

export type ContractAxisScopedAuthority =
  | 'contract-source'
  | 'theme-overrides'
  | 'facet-overrides';

export interface ContractAxisScope {
  rung: ContractAxisScopeRung;
  axisValues: Record<string, string>;
  key: string;
}

export interface ContractAxisScopedEdit {
  schemaVersion: typeof CONTRACT_AXIS_SCOPE_SCHEMA_VERSION;
  authority: ContractAxisScopedAuthority;
  op: ContractAxisScopedBaseOp;
  opTargetKey: string;
  scope: ContractAxisScope;
  storage: 'unconditional-attr' | 'axis-keyed-design-override';
}

export interface ContractAxisScopedOverrideStore {
  edits: ContractAxisScopedEdit[];
}

function stableEntries(record: Record<string, string>): Array<[string, string]> {
  return Object.entries(record).sort(([left], [right]) => left.localeCompare(right));
}

function axisKey(axisValues: Record<string, string>): string {
  return stableEntries(axisValues)
    .map(([axis, value]) => `${axis}=${value}`)
    .join('&');
}

function cloneAxisValues(axisValues: Record<string, string>): Record<string, string> {
  return Object.fromEntries(stableEntries(axisValues));
}

export function createContractAxisScope(axisValues: Record<string, string> = {}): ContractAxisScope {
  const cloned = cloneAxisValues(axisValues);
  const entries = stableEntries(cloned);
  if (entries.length === 0) {
    return { rung: 'all', axisValues: {}, key: 'all' };
  }
  if (entries.length === 1) {
    return { rung: 'axis-value', axisValues: cloned, key: axisKey(cloned) };
  }
  return { rung: 'axis-slice', axisValues: cloned, key: axisKey(cloned) };
}

export function createContractCellAxisScope(cell: ContractScenarioMatrixCellInput): ContractAxisScope {
  const axisValues = cloneAxisValues(cell.axisValues);
  return {
    rung: 'cell',
    axisValues,
    key: `cell:${axisKey(axisValues)}`,
  };
}

function stringifyTarget(op: ContractAxisScopedBaseOp): string {
  const target: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(op)) {
    if (key === 'value') continue;
    if (value === undefined) continue;
    target[key] = value;
  }
  return JSON.stringify(
    Object.fromEntries(Object.entries(target).sort(([left], [right]) => left.localeCompare(right))),
  );
}

export function contractAxisScopedOpTargetKey(op: ContractAxisScopedBaseOp): string {
  switch (op.op) {
    case 'set_instance_attr':
      return [
        op.op,
        String(op.file ?? ''),
        String(op.line ?? ''),
        String(op.attr ?? ''),
      ].join(':');
    case 'set_facet':
      return [
        op.op,
        String(op.component ?? ''),
        String(op.variant ?? 'base'),
        String(op.param ?? ''),
      ].join(':');
    case 'set_token':
      return [op.op, String(op.tokenPath ?? '')].join(':');
    case 'bind_token':
      return [
        op.op,
        String(op.file ?? ''),
        String(op.line ?? ''),
        String(op.attr ?? ''),
        String(op.tokenPath ?? ''),
      ].join(':');
    default:
      return stringifyTarget(op);
  }
}

export function createContractAxisScopedEdit(input: {
  authority: ContractAxisScopedAuthority;
  op: ContractAxisScopedBaseOp;
  scope?: ContractAxisScope;
}): ContractAxisScopedEdit {
  const scope = input.scope ?? createContractAxisScope();
  return {
    schemaVersion: CONTRACT_AXIS_SCOPE_SCHEMA_VERSION,
    authority: input.authority,
    op: { ...input.op },
    opTargetKey: contractAxisScopedOpTargetKey(input.op),
    scope,
    storage: scope.rung === 'all' ? 'unconditional-attr' : 'axis-keyed-design-override',
  };
}

export function createContractAxisScopedOverrideStore(
  edits: readonly ContractAxisScopedEdit[] = [],
): ContractAxisScopedOverrideStore {
  return {
    edits: edits.map(cloneAxisScopedEdit),
  };
}

function cloneAxisScopedEdit(edit: ContractAxisScopedEdit): ContractAxisScopedEdit {
  return {
    ...edit,
    op: { ...edit.op },
    scope: {
      ...edit.scope,
      axisValues: { ...edit.scope.axisValues },
    },
  };
}

export function writeContractAxisScopedOverride(
  store: ContractAxisScopedOverrideStore,
  edit: ContractAxisScopedEdit,
): ContractAxisScopedOverrideStore {
  return {
    edits: [...store.edits, cloneAxisScopedEdit(edit)],
  };
}

function scopeMatches(scope: ContractAxisScope, axisValues: Record<string, string>): boolean {
  if (scope.rung === 'all') return true;
  for (const [axis, value] of Object.entries(scope.axisValues)) {
    if (axisValues[axis] !== value) return false;
  }
  return true;
}

function scopeSpecificity(scope: ContractAxisScope): number {
  if (scope.rung === 'cell') return 10_000 + Object.keys(scope.axisValues).length;
  if (scope.rung === 'all') return 0;
  return Object.keys(scope.axisValues).length;
}

export function resolveContractAxisScopedOverride(
  store: ContractAxisScopedOverrideStore,
  op: ContractAxisScopedBaseOp,
  axisValues: Record<string, string>,
): ContractAxisScopedEdit | null {
  const targetKey = contractAxisScopedOpTargetKey(op);
  let best: { edit: ContractAxisScopedEdit; specificity: number; order: number } | null = null;
  for (const [order, edit] of store.edits.entries()) {
    if (edit.opTargetKey !== targetKey) continue;
    if (!scopeMatches(edit.scope, axisValues)) continue;
    const specificity = scopeSpecificity(edit.scope);
    if (!best || specificity > best.specificity || (specificity === best.specificity && order > best.order)) {
      best = { edit, specificity, order };
    }
  }
  return best?.edit ?? null;
}

export function promoteContractCellAxisScope(
  cell: ContractScenarioMatrixCellInput,
  promotion: ContractAxisPromotion,
  selectedAxes: readonly string[],
): ContractAxisScope {
  if (promotion === 'all') {
    return createContractAxisScope();
  }
  const axisIndex = promotion === 'row' ? 0 : 1;
  const axis = selectedAxes[axisIndex];
  if (!axis || cell.axisValues[axis] === undefined) {
    throw new Error(`Cannot promote ${promotion}; selected axis ${axisIndex} is unavailable`);
  }
  return createContractAxisScope({ [axis]: cell.axisValues[axis] });
}
