// @system @ref LLP 0166 §4.7 — versioned structural identity (static side).
//
// `structuralId` is the deterministic path through one component's view
// tree within ONE source version: stable across literal edits and reloads,
// NOT stable across insertions, branch reshapes, or extraction. It pairs
// with `sourceVersion` (the LLP 0158 staleness content hash) everywhere —
// edit targeting and hot-patch diffing never use an id without the version
// it came from. Path grammar (shared with the slot catalog): root is `v`;
// child i appends `i`; `when` branches mark `t{i}`/`e{i}`; `each` bodies
// mark `b{i}`; `match size` cases mark `m:<value>{i}` and else marks
// `me{i}`; resource/async slots mark `s:<kind>{i}`; boundary fallback/body mark
// `f{i}`/`bd{i}`; snippet bodies root at `snippet:<name>/r{i}`; segments
// after the root join with `.`.

import type { ComponentIR, ContractFileIR, Expr, ViewNodeIR } from './ir.js';

export function childPath(parent: string, segment: string): string {
  return parent === 'v' ? `v${segment}` : `${parent}.${segment}`;
}

/** Depth-first walk pairing every view node with its structural path. */
export function walkStructuralPaths(
  component: ComponentIR,
  visit: (node: ViewNodeIR, path: string) => void,
): void {
  const walk = (node: ViewNodeIR, path: string): void => {
    visit(node, path);
    switch (node.kind) {
      case 'element':
      case 'component':
        node.children.forEach((child, index) => {
          walk(child, childPath(path, String(index)));
        });
        return;
      case 'when':
        node.then.forEach((child, index) => {
          walk(child, childPath(path, `t${index}`));
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `e${index}`));
        });
        return;
      case 'match':
        node.cases.forEach((arm, armIndex) => {
          arm.body.forEach((child, index) => {
            walk(child, childPath(path, `c${armIndex}b${index}`));
          });
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `ce${index}`));
        });
        return;
      case 'match-size':
        node.cases.forEach((arm) => {
          arm.body.forEach((child, index) => {
            walk(child, childPath(path, `m:${arm.value}${index}`));
          });
        });
        (node.else ?? []).forEach((child, index) => {
          walk(child, childPath(path, `me${index}`));
        });
        return;
      case 'nothing':
      case 'hole':
        return;
      case 'each':
        node.body.forEach((child, index) => {
          walk(child, childPath(path, `b${index}`));
        });
        return;
      case 'resource':
      case 'async':
        node.slots.forEach((slot) => {
          slot.body.forEach((child, index) => {
            walk(child, childPath(path, `s:${slot.kind}${index}`));
          });
        });
        return;
      case 'boundary':
        node.fallback.body.forEach((child, index) => {
          walk(child, childPath(path, `f${index}`));
        });
        node.body.forEach((child, index) => {
          walk(child, childPath(path, `bd${index}`));
        });
        return;
      case 'text':
      case 'children':
      case 'snippet-call':
      // publish (LLP 0281 §3.1) is a childless effect line; it gets a
      // structural id (the visit above) like every other view node.
      case 'publish':
        return;
    }
  };
  walk(component.view, 'v');
  component.snippets.forEach((snippet) => {
    snippet.body.forEach((node, index) => {
      walk(node, `snippet:${snippet.name}/r${index}`);
    });
  });
}

/**
 * Structural ids for every view node in a component, keyed by node object
 * identity — a pure function of the IR (S4's differ and the runtime
 * registry share this exact derivation; S3's runtime registry is not a
 * prerequisite for it).
 */
export function assignStructuralIds(component: ComponentIR): Map<ViewNodeIR, string> {
  const ids = new Map<ViewNodeIR, string>();
  walkStructuralPaths(component, (node, path) => {
    ids.set(node, `${component.name}/${path}`);
  });
  return ids;
}

// ---------------------------------------------------------------------------
// The rebind contract
// ---------------------------------------------------------------------------

export type RebindResult =
  | { kind: 'matched'; structuralId: string }
  | { kind: 'ambiguous'; candidates: string[] }
  | { kind: 'gone' };

interface NodeFingerprint {
  /** Tag for elements, component name for calls, the kind otherwise. */
  shape: string;
  /** Authored identity when present (`testId` literal) — the authorKey. */
  testId?: string;
}

function fingerprintOf(node: ViewNodeIR): NodeFingerprint {
  const shape =
    node.kind === 'element' ? node.tag : node.kind === 'component' ? node.name : node.kind;
  let testId: string | undefined;
  if (node.kind === 'element' || node.kind === 'component') {
    const expr: Expr | undefined = node.props.testId;
    if (expr?.kind === 'string') {
      testId = expr.value;
    }
  }
  return { shape, testId };
}

function nodesByPath(component: ComponentIR): Map<string, ViewNodeIR> {
  const out = new Map<string, ViewNodeIR>();
  walkStructuralPaths(component, (node, path) => {
    out.set(path, node);
  });
  return out;
}

/**
 * Rebinds a selection `(structuralId, oldFile)` against a new IR. Exactly
 * one of `matched` / `ambiguous` / `gone` — consumers must never guess on
 * `ambiguous` (the actor that MADE a structural edit owns its own
 * remapping; everyone else gets the honest tri-state).
 */
export function rebindStructuralId(
  structuralId: string,
  oldFile: ContractFileIR,
  newFile: ContractFileIR,
): RebindResult {
  const slash = structuralId.indexOf('/');
  if (slash === -1) {
    return { kind: 'gone' };
  }
  const componentName = structuralId.slice(0, slash);
  const path = structuralId.slice(slash + 1);

  const oldComponent = oldFile.components.find((c) => c.name === componentName);
  const newComponent = newFile.components.find((c) => c.name === componentName);
  if (!oldComponent || !newComponent) {
    return { kind: 'gone' };
  }
  const oldNode = nodesByPath(oldComponent).get(path);
  if (!oldNode) {
    return { kind: 'gone' };
  }
  const oldFingerprint = fingerprintOf(oldNode);

  const newPaths = nodesByPath(newComponent);
  const samePath = newPaths.get(path);
  if (samePath) {
    const candidate = fingerprintOf(samePath);
    if (
      candidate.shape === oldFingerprint.shape &&
      (oldFingerprint.testId === undefined || candidate.testId === oldFingerprint.testId)
    ) {
      return { kind: 'matched', structuralId };
    }
  }

  // The path moved or reshaped. Search by the authored key when there is
  // one; without an authorKey a missing path is honestly `gone`.
  if (oldFingerprint.testId === undefined) {
    return { kind: 'gone' };
  }
  const candidates: string[] = [];
  newPaths.forEach((node, candidatePath) => {
    const fp = fingerprintOf(node);
    if (fp.shape === oldFingerprint.shape && fp.testId === oldFingerprint.testId) {
      candidates.push(`${componentName}/${candidatePath}`);
    }
  });
  if (candidates.length === 1) {
    return { kind: 'matched', structuralId: candidates[0] };
  }
  if (candidates.length > 1) {
    return { kind: 'ambiguous', candidates };
  }
  return { kind: 'gone' };
}
