// @system @ref LLP 0093, LLP 0157 §4-5 — capability and behavior protocols.
//
// Until 0093's general capability plane lands, Contract ships a minimal
// concrete protocol: a capability is an imported value that the runtime
// instantiates once per root (theme is the first); a behavior is a factory
// components instantiate per-instance (`use hover = interaction()`), whose
// result can attach interaction handler props to a view node via
// `interaction=`.

import type { ContractHydrationRuntimeOptions } from './hydration.js';
import type { Owner } from './signals.js';

export const CAPABILITY_KIND = 'capability' as const;
export const BEHAVIOR_INSTANCE_KIND = 'behavior-instance' as const;

export interface CapabilityContext {
  /** Stable per-root identity for capability instance caching. */
  rootKey: object;
  owner: Owner;
  /**
   * The root's hydration options when this is a hydration/prerender mount
   * (ENG-22563): capabilities that read live host inputs can replay the
   * captured value from `hydration.capabilities` so the first render matches
   * the prerendered HTML.
   */
  hydration?: ContractHydrationRuntimeOptions;
  /**
   * Registers a release hook run when hydration adoption completes (before
   * deferred mount tasks) — the moment to flip a replayed capability value
   * back to the live host input. Absent outside hydration mounts.
   */
  onHydrationRelease?: (release: () => void) => void;
}

export interface ContractCapability<T = unknown> {
  __contractKind: typeof CAPABILITY_KIND;
  /** Human-readable identity for diagnostics. */
  id: string;
  /** Effect summary (LLP 0087 capability signatures). */
  effects?: readonly string[];
  instantiate(context: CapabilityContext): T;
}

export function defineCapability<T>(definition: {
  id: string;
  effects?: readonly string[];
  instantiate(context: CapabilityContext): T;
}): ContractCapability<T> {
  return { __contractKind: CAPABILITY_KIND, ...definition };
}

export function isCapability(value: unknown): value is ContractCapability {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { __contractKind?: unknown }).__contractKind === CAPABILITY_KIND
  );
}

export interface BehaviorInstance {
  __contractKind: typeof BEHAVIOR_INSTANCE_KIND;
  /** Handler props merged onto a view node bound with `interaction=`. */
  attachProps?(): Record<string, unknown>;
  [key: string]: unknown;
}

export function isBehaviorInstance(value: unknown): value is BehaviorInstance {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { __contractKind?: unknown }).__contractKind === BEHAVIOR_INSTANCE_KIND
  );
}

// ---------------------------------------------------------------------------
// LLP 0281 stage 0 — value-channel protocol
// ---------------------------------------------------------------------------
//
// The channel capability's PROTOCOL lives here (kind markers, structural
// interfaces, guards, and the `sample(...)` crossing) because the
// always-loaded runtime — instance wiring, view event lowering, the
// dataflow inspector — only needs to recognize and sample channels. The
// IMPLEMENTATION (`ValueChannel`, `pointerChannel`, the rated publisher in
// ./channels.ts) loads only when an app imports `@exact/contract/channels`,
// keeping channel machinery off the startup module budget (the LLP 0128
// ratchet) for apps that never use it.

export const VALUE_CHANNEL_KIND = 'value-channel' as const;
export const VALUE_CHANNEL_SET_KIND = 'value-channel-set' as const;

/** The pinned pointer payload (LLP 0275 A1 / LLP 0281 §3.1), element-local. */
export interface PointerSample {
  x: number;
  y: number;
  pointerId: number;
  pointerType: string;
  buttons: number;
  pressure?: number;
}

/** Element box metadata riding the host envelope (publish normalization). */
export interface ChannelElementBox {
  width: number;
  height: number;
}

/** What a host event wiring delivers into a channel write. */
export interface ChannelHostEnvelope {
  sample: PointerSample;
  element?: ChannelElementBox;
  /** Authored event name (`pointermove`, `pointerup`, ...) for inspection. */
  phase?: string;
  timeStampMs?: number;
}

/** Provider publish budget facts (Snapback LLP 0034 §4 emits them). */
export interface ChannelPublishBudget {
  sustainedHz?: number;
  burst?: number;
  maxValueBytes?: number;
}

/**
 * Plain-JS/test seam extras on the mechanism path (a `publish` function in
 * the factory options): descriptor naming, budget facts, payload evaluator.
 * The Contract-authored path no longer cooks these — the rated `publish`
 * view line attaches its config through `__attachPublisher` (ENG-22525
 * retired the instantiation-options publish spelling).
 */
export interface ChannelFactoryCookedOptions {
  __payloadEvaluator?: (bindings: {
    sample: Readonly<PointerSample>;
    element: ChannelElementBox;
  }) => unknown;
  __publishDescriptorName?: string;
  __publishBudget?: ChannelPublishBudget;
}

/**
 * LLP 0281 §3.1 (ENG-22525) — what a `publish <channel> -> <descriptor>
 * rate=<Hz>` view line hands the channel set at mount. Protocol-level so
 * the always-loaded view runtime can wire publishers without importing the
 * channel implementation (LLP 0128 startup discipline).
 */
export interface ChannelPublishConfig {
  /** The publish descriptor callable (mutation-shaped or publish-kind). */
  publish: (args: unknown) => unknown;
  /** Declared rate in Hz (a compile-time IR fact). */
  rateHz: number;
  /**
   * Declared idle keepalive in Hz (LLP 0281 §3.1, ENG-22539): when the
   * publisher has emitted at least once and then sits idle for
   * 1000/heartbeatHz ms, it re-emits — re-sealing the channel and
   * re-evaluating the payload — so ephemeral presence outlives pointer
   * silence. Always ≤ rateHz (analyzer-enforced).
   */
  heartbeatHz?: number;
  /** Descriptor import name (receipts + inspection). */
  descriptor: string;
  /** Provider budget facts from the resolved import descriptor. */
  budget?: ChannelPublishBudget;
  /**
   * Authored payload mapping, cooked to an evaluator that binds
   * `sample`/`element` per publish tick in the channel lane. Absent, the
   * sealed sample publishes as-is.
   */
  payloadEvaluator?: (bindings: {
    sample: Readonly<PointerSample>;
    element: ChannelElementBox;
  }) => unknown;
}

/**
 * The host-owned frame-coalesced value cell, as consumers see it. NOT a
 * signal: reads are never tracked, writes never touch the reactive graph
 * or the transactional flush (LLP 0281 §3.1).
 */
export interface ContractValueChannel {
  readonly __contractKind: typeof VALUE_CHANNEL_KIND;
  readonly id: string;
  /** Advances once per applied (coalesced or immediate) value. */
  readonly generation: number;
  /** Raw host writes observed (pre-coalescing). */
  readonly writes: number;
  /** Writes dropped in favor of a newer same-frame value. */
  readonly coalesced: number;
  /** Non-pointer-shaped writes rejected at intake (ENG-22539 guard). */
  readonly rejectedWrites: number;
  readonly hasSample: boolean;
  current(): PointerSample | undefined;
  elementBox(): ChannelElementBox | undefined;
  /** §3.4 atomic sampling: an immutable copy at the current generation. */
  seal(): Readonly<PointerSample> | undefined;
  writeFromHost(envelope: ChannelHostEnvelope, options?: { immediate?: boolean }): void;
  /** Frame-coalesced observation; runs outside any tracking context. */
  subscribe(subscriber: (value: PointerSample) => void): () => void;
  dispose(): void;
}

/** The handle a channel capability instantiation returns (`use x = pointerChannel(...)`). */
export interface ContractValueChannelSet {
  readonly __contractKind: typeof VALUE_CHANNEL_SET_KIND;
  readonly channelClass: string;
  /** The local pointer's value channel (multi-pointer is LLP 0281 OQ4). */
  readonly self: ContractValueChannel;
  /** Runtime hook: instance.ts names the binding after evaluation. */
  __attachBinding(name: string): void;
  /**
   * LLP 0281 §3.1 (ENG-22525): a mounted `publish` line attaches its rated
   * publisher here. Returns a dispose function (idempotent; the set's own
   * dispose also reaches attached publishers). One publisher per set in
   * stage 0 — the analyzer enforces it, the runtime warns and ignores.
   */
  __attachPublisher?(config: ChannelPublishConfig): () => void;
  /**
   * LLP 0281 §3.1 (ENG-22539): the programmatic emission hook behind the
   * `publish(<channel>)` action/task builtin. Requests ONE emission through
   * the channel's declared rated publisher — deferred to a microtask (so an
   * action's writes commit before the payload mapping reads state) and
   * paced under the declared rate like any write-driven sample. The caller
   * never supplies a value: what leaves is always the declared descriptor's
   * payload over the sealed sample, which is why this path preserves the
   * compile-time sink invariants.
   */
  __requestPublish?(): void;
  /** Live-observable facts for the dataflow inspector (LLP 0281 §3.5). */
  __inspect(): Record<string, unknown>;
  dispose(): void;
}

export function isValueChannel(value: unknown): value is ContractValueChannel {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { __contractKind?: unknown }).__contractKind === VALUE_CHANNEL_KIND
  );
}

export function isValueChannelSet(value: unknown): value is ContractValueChannelSet {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { __contractKind?: unknown }).__contractKind === VALUE_CHANNEL_SET_KIND
  );
}

/**
 * `sample(<channel>)` — the §3.4 explicit lane crossing. Legal only as an
 * edge-event action argument (analyzer-enforced); returns the sealed
 * immutable sample so the action receives an ordinary, trace-visible value.
 */
export function sampleChannel(target: unknown): Readonly<PointerSample> | undefined {
  const channel = isValueChannelSet(target) ? target.self : target;
  if (isValueChannel(channel)) {
    return channel.seal();
  }
  console.warn('[contract] sample() expects a value channel');
  return undefined;
}

/**
 * `publish(<channel>)` — the programmatic emission crossing (LLP 0281
 * §3.1, ENG-22539). Legal only as a statement in action/task bodies
 * (analyzer-enforced), targeting a component-local channel binding that
 * declares a rated `publish` view line. Confinement-preserving by
 * construction: it takes no value argument — the emission re-evaluates the
 * DECLARED payload mapping over the sealed sample, deferred past the
 * action's commit and paced under the declared rate. Returns nothing (it
 * is a request, not a value expression).
 */
export function publishChannel(target: unknown): void {
  if (!isValueChannelSet(target)) {
    console.warn(
      '[contract] publish() expects a value-channel binding (`publish(<binding>)`) — it requests an emission through the channel’s declared rated publish line (LLP 0281 §3.1)',
    );
    return;
  }
  if (typeof target.__requestPublish !== 'function') {
    console.warn(
      '[contract] publish(): this channel implementation does not support programmatic emission (LLP 0281 §3.1)',
    );
    return;
  }
  target.__requestPublish();
}
