// @system @ref LLP 0293 Entry 6 ledger rows 1, 2, 7 — framework-owned host
// input capabilities. The slides build proved any non-tap-driven app ends up
// hand-rolling a document key listener (wrapped in batch/allowStateWrites,
// with no disposal channel) and a viewport probe (window.innerHeight at
// mount, no reactivity). These capabilities are the paved path: per-root
// instantiation, owner-tracked disposal, action calls wrapped exactly like
// the runtime's own `every()`.

import { OpCode } from '@exact/core/protocol/opcodes';

import { defineCapability } from './capabilities.js';
import { allowStateWrites } from './instance.js';
import { batch, signal, type Signal } from './signals.js';

// ---------------------------------------------------------------------------
// keyboard — app-level key bindings.
//
//   use keyboard from "@exact/contract/runtime"
//   ...
//   task keys mount
//     keyboard("ArrowRight", next)
//     keyboard("Escape", close)
//
// The capability value is callable so task bodies stay in the bare-call
// statement grammar. Bindings are per-root; the single document listener is
// installed lazily and removed by the root owner on unmount/reset. Modifier
// chords are skipped (they belong to the host/browser), as are events
// targeted at editable elements.
//
// Two backings share the binder surface (ENG-22579):
// - web: a `document` keydown listener (native defines a window shim, so
//   `document` is the honest gate);
// - native: the host keyboard module (`com.exact.host.keyboard`) — JS syncs
//   the union of bound keys over the module-action channel, the host's key
//   monitor consumes exactly those plain (unmodified) keydowns and emits
//   them back as module events with web `KeyboardEvent.key` names. Hosts
//   without the module (a prerender process, an older native build) leave
//   the binder a silent no-op, same as before.
// ---------------------------------------------------------------------------

export type ContractKeyBinder = (key: string, action: () => void) => void;

const EDITABLE_TAGS = new Set(['INPUT', 'TEXTAREA', 'SELECT']);

const NATIVE_KEYBOARD_MODULE = 'com.exact.host.keyboard';
/** Action id 0 = setKeys — pinned in HostKeyboardModule (Swift). */
const NATIVE_KEYBOARD_SET_KEYS_ACTION_ID = 0;
// @ref LLP 0150 idea 1 — module opcodes come from the generated OpCode table
// (authority: tests/protocol/protocol-inventory.json), never re-literaled.
const MODULE_ACTION_OPCODE: number = OpCode.ModuleAction;

interface NativeRuntimeBridge {
  getModuleMetadata?: (name: string) => { moduleId?: number } | null | undefined;
  dispatchModule?: (bytes: Uint8Array) => void;
}

type ModuleEventHandler = (event: string, payload: unknown) => void;

interface ModuleEventGlobals {
  exact?: NativeRuntimeBridge;
  __exactModuleEvent?: (module: string, event: string, ...rest: unknown[]) => void;
  __exactModuleEventHandlers?: Map<string, ModuleEventHandler>;
}

const moduleEventGlobals = globalThis as ModuleEventGlobals;

type KeyBindings = Map<string, () => void>;

const nativeKeyboardRoots = new Set<KeyBindings>();
let nativeKeyboardHandlerInstalled = false;
let nativeKeyboardDispatcherInstalled = false;
let nativeKeyboardCorrelationId = 1;
let nativeSyncedKeys: string | null = null;

function lookupKeyBinding(bindings: KeyBindings, key: string): (() => void) | undefined {
  // "Space" is accepted as an author-friendly alias for the space bar.
  return bindings.get(key) ?? (key === ' ' ? bindings.get('Space') : undefined);
}

function encodeNativeModuleAction(moduleId: number, actionId: number, payload: Uint8Array): Uint8Array {
  const bytes = new Uint8Array(13 + payload.length);
  const view = new DataView(bytes.buffer);
  view.setUint8(0, MODULE_ACTION_OPCODE);
  view.setUint16(1, moduleId, true);
  view.setUint16(3, actionId, true);
  view.setUint32(5, nativeKeyboardCorrelationId++, true);
  view.setUint32(9, payload.length, true);
  bytes.set(payload, 13);
  return bytes;
}

function syncNativeKeyBindings(): void {
  const bridge = moduleEventGlobals.exact;
  if (!bridge?.dispatchModule || typeof bridge.getModuleMetadata !== 'function') {
    return;
  }
  const keys = new Set<string>();
  for (const bindings of nativeKeyboardRoots) {
    for (const key of bindings.keys()) {
      keys.add(key);
    }
  }
  const list = [...keys].sort();
  const serialized = JSON.stringify(list);
  if (serialized === nativeSyncedKeys) {
    return;
  }
  const moduleId = bridge.getModuleMetadata(NATIVE_KEYBOARD_MODULE)?.moduleId;
  if (!moduleId) {
    // Module not present on this host (prerender, an older native build) —
    // stay a no-op. macOS and iOS both ship it (ENG-22579 / ENG-22596).
    return;
  }
  bridge.dispatchModule(
    encodeNativeModuleAction(
      moduleId,
      NATIVE_KEYBOARD_SET_KEYS_ACTION_ID,
      new TextEncoder().encode(JSON.stringify({ keys: list })),
    ),
  );
  nativeSyncedKeys = serialized;
}

function decodeNativeKeyEvent(payload: unknown): string | null {
  let text: string | null = null;
  if (typeof payload === 'string') {
    text = payload;
  } else if (payload instanceof Uint8Array) {
    text = new TextDecoder().decode(payload);
  } else if (payload instanceof ArrayBuffer) {
    text = new TextDecoder().decode(new Uint8Array(payload));
  } else if (payload !== null && typeof payload === 'object') {
    const key = (payload as { key?: unknown }).key;
    return typeof key === 'string' ? key : null;
  }
  if (text === null) {
    return null;
  }
  try {
    const parsed = JSON.parse(text) as { key?: unknown };
    return typeof parsed.key === 'string' ? parsed.key : null;
  } catch {
    return null;
  }
}

function ensureNativeKeyboardHandlerInstalled(): void {
  if (nativeKeyboardHandlerInstalled) {
    return;
  }
  if (typeof moduleEventGlobals.__exactModuleEventHandlers === 'undefined') {
    moduleEventGlobals.__exactModuleEventHandlers = new Map();
  }
  if (!nativeKeyboardDispatcherInstalled) {
    const baseDispatcher = moduleEventGlobals.__exactModuleEvent;
    moduleEventGlobals.__exactModuleEvent = (module: string, event: string, ...rest: unknown[]) => {
      const payload = rest.length > 1 ? rest[rest.length - 1] : rest[0];
      const handler = moduleEventGlobals.__exactModuleEventHandlers?.get(module);
      if (handler) {
        handler(event, payload);
        return;
      }
      if (baseDispatcher) {
        if (rest.length > 1 && baseDispatcher.length >= 4) {
          baseDispatcher(module, event, rest[0], payload);
          return;
        }
        baseDispatcher(module, event, payload);
        return;
      }
    };
    nativeKeyboardDispatcherInstalled = true;
  }
  moduleEventGlobals.__exactModuleEventHandlers.set(NATIVE_KEYBOARD_MODULE, (event, payload) => {
    if (event !== 'keydown') {
      return;
    }
    const key = decodeNativeKeyEvent(payload);
    if (key === null) {
      return;
    }
    for (const bindings of [...nativeKeyboardRoots]) {
      const bound = lookupKeyBinding(bindings, key);
      if (bound) {
        batch(() => allowStateWrites(() => bound()));
      }
    }
  });
  nativeKeyboardHandlerInstalled = true;
}

function assertKeyBindingArgs(key: string, action: () => void): void {
  if (typeof key !== 'string' || key.length === 0) {
    throw new Error('[contract] keyboard(key, action) requires a key name');
  }
  if (typeof action !== 'function') {
    throw new Error('[contract] keyboard(key, action) requires an action');
  }
}

export const keyboard = defineCapability<ContractKeyBinder>({
  id: 'contract.keyboard',
  effects: ['host:keyboard'],
  instantiate({ owner }) {
    if (typeof document === 'undefined') {
      const bindings: KeyBindings = new Map();
      let attached = false;
      const attach = () => {
        if (attached) {
          return;
        }
        attached = true;
        ensureNativeKeyboardHandlerInstalled();
        nativeKeyboardRoots.add(bindings);
        owner.register(() => {
          nativeKeyboardRoots.delete(bindings);
          bindings.clear();
          syncNativeKeyBindings();
        });
      };
      return (key: string, action: () => void) => {
        assertKeyBindingArgs(key, action);
        attach();
        bindings.set(key, action);
        syncNativeKeyBindings();
      };
    }
    const bindings = new Map<string, () => void>();
    let listener: ((event: KeyboardEvent) => void) | null = null;
    const ensureListener = () => {
      if (listener) {
        return;
      }
      listener = (event: KeyboardEvent) => {
        if (event.metaKey || event.ctrlKey || event.altKey) {
          return;
        }
        const target = event.target as HTMLElement | null;
        if (target && (EDITABLE_TAGS.has(target.tagName) || target.isContentEditable)) {
          return;
        }
        const bound = lookupKeyBinding(bindings, event.key);
        if (!bound) {
          return;
        }
        event.preventDefault();
        batch(() => allowStateWrites(() => bound()));
      };
      document.addEventListener('keydown', listener);
      owner.register(() => {
        if (listener) {
          document.removeEventListener('keydown', listener);
          listener = null;
        }
        bindings.clear();
      });
    };
    return (key: string, action: () => void) => {
      assertKeyBindingArgs(key, action);
      ensureListener();
      bindings.set(key, action);
    };
  },
});

// ---------------------------------------------------------------------------
// Shared viewport host input (ENG-22563).
//
// ONE window resize listener feeds every consumer: the `viewport` capability
// below and the facet theme store's size-class width (facet-contract
// `installHostInputs`) both subscribe here instead of maintaining parallel
// listeners. The window listener installs lazily with the first subscriber
// and uninstalls with the last. `document` is part of the gate because
// native defines a window shim (see the keyboard capability note above).
// ---------------------------------------------------------------------------

export interface ContractViewportSize {
  width: number;
  height: number;
}

function hasViewportDom(): boolean {
  return typeof document !== 'undefined' && typeof window !== 'undefined';
}

/** Current viewport size; `{0, 0}` without a DOM-backed viewport. */
export function readViewportHostSize(): ContractViewportSize {
  if (!hasViewportDom()) {
    return { width: 0, height: 0 };
  }
  return {
    width: typeof window.innerWidth === 'number' ? window.innerWidth : 0,
    height: typeof window.innerHeight === 'number' ? window.innerHeight : 0,
  };
}

type ViewportHostInputListener = (size: ContractViewportSize) => void;

const viewportHostInputListeners = new Set<ViewportHostInputListener>();
let removeViewportWindowListener: (() => void) | null = null;

/**
 * Subscribes to viewport size changes through the single shared window
 * listener. Returns an unsubscribe; a no-op without a DOM-backed viewport
 * (no resize events will ever fire there).
 */
export function subscribeViewportHostInput(listener: ViewportHostInputListener): () => void {
  if (!hasViewportDom() || typeof window.addEventListener !== 'function') {
    return () => {};
  }
  viewportHostInputListeners.add(listener);
  if (!removeViewportWindowListener) {
    const onResize = (): void => {
      const size = readViewportHostSize();
      viewportHostInputListeners.forEach((subscriber) => subscriber(size));
    };
    window.addEventListener('resize', onResize);
    removeViewportWindowListener = () => window.removeEventListener('resize', onResize);
  }
  return () => {
    viewportHostInputListeners.delete(listener);
    if (viewportHostInputListeners.size === 0 && removeViewportWindowListener) {
      removeViewportWindowListener();
      removeViewportWindowListener = null;
    }
  };
}

// ---------------------------------------------------------------------------
// viewport — reactive viewport dimensions.
//
//   use viewport from "@exact/contract/runtime"
//   ...
//   view
//     column height=viewport.height overflow="hidden"
//
// Width/height are signal-backed, so attr bindings re-evaluate on resize —
// the reactivity the '100vh'-shaped hacks never had. Without a document the
// signals hold 0 and never change (native hosts size roots through the
// kernel; a kernel-fed viewport is the follow-on, tracked in LLP 0293).
//
// Hydration (ENG-22563): when the capability bag carries the prerender's
// viewport, the first client render replays it — so adoption compares
// against exactly what the SSG baked — and the hydration-release hook flips
// the signals to the live window size as a fine-grained update instead of
// an adoption mismatch.
// ---------------------------------------------------------------------------

export interface ContractViewport {
  readonly width: number;
  readonly height: number;
}

export const viewport = defineCapability<ContractViewport>({
  id: 'contract.viewport',
  effects: ['host:viewport'],
  instantiate({ owner, hydration, onHydrationRelease }) {
    const hasDom = hasViewportDom();
    if (!hasDom) {
      // Degrade loudly, not blankly (graceful-degradation principle): a
      // viewport-sized surface bound to 0 renders invisible. Native wiring
      // is the tracked follow-on (LLP 0292); until then authors need a
      // fallback (e.g. `height=stageHeight(viewport)` mapping 0 -> "100%").
      console.warn('[contract] viewport capability has no DOM backing on this host; width/height stay 0 — bind a fallback for native surfaces');
    }
    const captured = hydration?.capabilities?.viewport;
    const initial = captured ?? readViewportHostSize();
    const width: Signal<number> = signal(initial.width);
    const height: Signal<number> = signal(initial.height);
    const applySize = (size: ContractViewportSize): void => {
      batch(() => {
        allowStateWrites(() => {
          width.set(size.width);
          height.set(size.height);
        });
      });
    };
    if (hasDom) {
      owner.register(subscribeViewportHostInput(applySize));
      if (captured) {
        onHydrationRelease?.(() => applySize(readViewportHostSize()));
      }
    }
    return {
      get width() {
        return width.get();
      },
      get height() {
        return height.get();
      },
    };
  },
});
