// @system @ref LLP 0163 §5.3a — the DesignControl metadata contract.
//
// The grammar (`params` + `design` sections) is presentation; the stable
// artifact every consumer sees is the DesignControl record: the compiler's
// declarations lowered to one shape, with the inference floor filled in
// (LLP 0163 §5.2 — zero declarations still yields a usable controls
// section; declaration changes emphasis, never capability). Query-time
// fields (currentValue, valueSource, commitTier) are resolved per selection
// by the panel layer against provenance and the overrides authorities; this
// module owns the static resolution.
//
// Dev-mode registry: compiled components register their design metadata by
// component name so the Design Mode panel (which deliberately has no hard
// dependency on @exact/contract) reads it through the
// `globalThis.__exactContractDesignMeta` handle, mirroring
// `__exactContractProvenance`.

import type {
  ComponentIR,
  DesignControlBindingIR,
  DesignControlConstraintsIR,
  DesignControlKind,
  ParamIR,
  Span,
} from '../compiler/ir.js';
import { isContractDevMode } from './provenance.js';

export interface DesignControlRecord {
  /** Stable within the owning component. */
  id: string;
  owner: { component: string; sourcePath?: string };
  binding: DesignControlBindingIR;
  kind: DesignControlKind;
  constraints: DesignControlConstraintsIR;
  label: string;
  group?: string;
  order: number;
  sourceSpan?: Span;
  /** True for inference-floor records (no declaration backs them). */
  inferred: boolean;
}

export interface ComponentDesignMeta {
  component: string;
  sourcePath?: string;
  params: Array<{ name: string; kind?: ParamIR['kind'] }>;
  controls: DesignControlRecord[];
}

function bindingKey(binding: DesignControlBindingIR): string {
  switch (binding.kind) {
    case 'prop':
      return `prop:${binding.name}`;
    case 'facet':
      return `facet:${binding.param}`;
    case 'token':
      return `token:${binding.path}`;
  }
}

function titleCase(name: string): string {
  const spaced = name.replace(/([a-z0-9])([A-Z])/g, '$1 $2').toLowerCase();
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

function inferPropControlKind(component: ComponentIR, propName: string): {
  kind: DesignControlKind;
  options?: string[];
} | null {
  const prop = component.props.find((candidate) => candidate.name === propName);
  const ir = prop?.parsedType?.ir;
  if (!ir) {
    return null;
  }
  switch (ir.kind) {
    case 'primitive':
      if (ir.name === 'boolean') {
        return { kind: 'toggle' };
      }
      if (ir.name === 'number') {
        return { kind: 'number' };
      }
      return { kind: 'text' };
    case 'literal-union':
      // The union drives a select — declared once, on the type (LLP 0166 §4.5).
      return { kind: 'select', options: ir.values };
    case 'value-kind':
      if (ir.name === 'color') {
        return { kind: 'color' };
      }
      return { kind: 'slider' };
    default:
      return null;
  }
}

function inferParamControlKind(param: ParamIR): DesignControlKind {
  switch (param.kind) {
    case 'color':
      return 'color';
    case 'duration':
      return 'number';
    case 'dimension':
    default:
      // Dimension-kind sliders snap to the token scale by default in the
      // panel (LLP 0163 §5.3); the record just names the kind.
      return 'slider';
  }
}

/**
 * Lowers a component's declarations to DesignControl records and fills the
 * inference floor beneath them: declared controls lead (document order);
 * inferred records cover every remaining prop/param with an inferable kind.
 */
export function collectDesignControls(
  component: ComponentIR,
  options?: { sourcePath?: string },
): DesignControlRecord[] {
  const records: DesignControlRecord[] = [];
  const covered = new Set<string>();
  const owner = { component: component.name, sourcePath: options?.sourcePath };

  (component.controls ?? []).forEach((control) => {
    const key = bindingKey(control.binding);
    covered.add(key);
    let kind = control.controlKind;
    let options_: string[] | undefined = control.constraints.options;
    if (control.binding.kind === 'prop') {
      const inferred = inferPropControlKind(component, control.binding.name);
      kind ??= inferred?.kind ?? 'text';
      options_ ??= inferred?.options;
    } else if (control.binding.kind === 'facet') {
      const param = (component.params ?? []).find(
        (candidate) => control.binding.kind === 'facet' && candidate.name === control.binding.param,
      );
      kind ??= param ? inferParamControlKind(param) : 'number';
    } else {
      kind ??= control.binding.path.startsWith('colors.') ? 'color' : 'number';
    }
    const name =
      control.binding.kind === 'prop'
        ? control.binding.name
        : control.binding.kind === 'facet'
          ? control.binding.param
          : control.binding.name;
    records.push({
      id: `${component.name}:control:${key}`,
      owner,
      binding: control.binding,
      kind,
      constraints: options_ ? { ...control.constraints, options: options_ } : control.constraints,
      label: control.label ?? titleCase(name),
      group: control.group,
      order: records.length,
      sourceSpan: control.span,
      inferred: false,
    });
  });

  // Inference floor: every prop with an inferable kind, every param.
  component.props.forEach((prop) => {
    const key = `prop:${prop.name}`;
    if (covered.has(key)) {
      return;
    }
    const inferred = inferPropControlKind(component, prop.name);
    if (!inferred || prop.parsedType?.ir.kind === 'function') {
      return;
    }
    covered.add(key);
    records.push({
      id: `${component.name}:control:${key}`,
      owner,
      binding: { kind: 'prop', name: prop.name },
      kind: inferred.kind,
      constraints: inferred.options ? { options: inferred.options } : {},
      label: titleCase(prop.name),
      order: records.length,
      sourceSpan: prop.span,
      inferred: true,
    });
  });
  (component.params ?? []).forEach((param) => {
    const key = `facet:${param.name}`;
    if (covered.has(key)) {
      return;
    }
    covered.add(key);
    records.push({
      id: `${component.name}:control:${key}`,
      owner,
      binding: { kind: 'facet', param: param.name },
      kind: inferParamControlKind(param),
      constraints: {},
      label: titleCase(param.name),
      order: records.length,
      sourceSpan: param.span,
      inferred: true,
    });
  });

  return records;
}

// ---------------------------------------------------------------------------
// Dev-mode registry (the panel's read path)
// ---------------------------------------------------------------------------

const metaByComponent = new Map<string, ComponentDesignMeta>();
let handleInstalled = false;

function ensureGlobalHandle(): void {
  if (handleInstalled) {
    return;
  }
  handleInstalled = true;
  (globalThis as Record<string, unknown>).__exactContractDesignMeta = {
    get: getComponentDesignMeta,
  };
}

export function getComponentDesignMeta(componentName: string): ComponentDesignMeta | undefined {
  return metaByComponent.get(componentName);
}

/** Called per compiled component (dev only); last registration wins (HMR). */
export function registerComponentDesignMeta(
  component: ComponentIR,
  sourcePath: string | undefined,
): void {
  if (!isContractDevMode()) {
    return;
  }
  ensureGlobalHandle();
  metaByComponent.set(component.name, {
    component: component.name,
    sourcePath,
    params: (component.params ?? []).map((param) => ({ name: param.name, kind: param.kind })),
    controls: collectDesignControls(component, { sourcePath }),
  });
}
