// @system @ref LLP 0158 — Design Mode D0: StyleProvenance for Contract nodes.
//
// Dev-only. Classifies view-node attribute expressions from the IR
// (literal / token reference / computed) at mount time and parks the result
// in a WeakMap keyed by the rendered host node. Nothing here feeds
// rendering; production builds skip attachment entirely (isContractDevMode
// gate). The Design Mode overlay reads through the
// `globalThis.__exactContractProvenance` handle so apps without Contract
// never import this module.

import type { Expr } from '../compiler/ir.js';
import { isExprSpread } from '../compiler/ir.js';
import { evalExpr, Scope } from './interpreter.js';
import { untrack } from './signals.js';

const VIEW_EVAL = { identFallbackToString: true } as const;

export type AttrOriginKind = 'literal' | 'token' | 'relation' | 'computed';

/**
 * LLP 0158 §4.1 confidence ladder. Contract classification emits `exact`
 * (literals, token references) and `computed`; `inferred`/`unknown` exist
 * for non-Contract surfaces and unattributed properties at the panel layer.
 */
export type OriginConfidence = 'exact' | 'computed' | 'inferred' | 'unknown';

export interface AttrOrigin {
  kind: AttrOriginKind;
  confidence: OriginConfidence;
  /** Attribute name as written in the .contract source (pre-lowering). */
  sourceAttr?: string;
  /** Literal value for kind === 'literal'. */
  value?: unknown;
  /**
   * Exact source text of a single-token literal value (LLP 0158 D2) — the
   * anchored replacement target for instance edits. Absent = not editable.
   */
  rawSource?: string;
  /** Dot path into the theme for kind === 'token' (e.g. "colors.accent"). */
  tokenPath?: string;
  /** Root identifier of a token reference (usually "theme"). */
  tokenRoot?: string;
  /** Compact source-expression summary for computed origins. */
  expr?: string;
  /** Layout relationship metadata for kind === 'relation'. */
  relation?: { op: string; args: string[] };
  /** Callee name when the expression is a call — recipe tracing hook. */
  recipeCall?: { name: string };
  /**
   * Dev-only closure: evaluates callee + args in the node's scope so the
   * panel can re-run a recipe under the tracing theme (LLP 0158 §4.1).
   */
  evalRecipe?: () => { fn: unknown; args: unknown[] } | null;
}

export interface ComponentBoundaryProvenance {
  componentName: string;
  callSourcePath?: string;
  callLine?: number;
  definitionSourcePath?: string;
  /** Call-site prop origins, keyed by prop name. */
  props: Record<string, AttrOrigin>;
}

export interface ContractNodeProvenance {
  componentName: string;
  sourcePath?: string;
  line?: number;
  /** Contract-source tag (column/row/text/button/…); absent on text nodes. */
  tag?: string;
  /** Per host-prop origins, keyed by the lowered host/style prop name. */
  attrs: Record<string, AttrOrigin>;
  /** Origin of a dynamic `style=` attr (recipe call or expression). */
  styleSource?: AttrOrigin;
  /** Text content origin for text nodes. */
  text?: AttrOrigin;
  /** Present when this host node is the root of a component call. */
  boundary?: ComponentBoundaryProvenance;
}

// ---------------------------------------------------------------------------
// Dev gate (same convention as @exact/facet-core isFacetDevMode)
// ---------------------------------------------------------------------------

export function isContractDevMode(): boolean {
  const runtime = globalThis as typeof globalThis & {
    __DEV__?: boolean;
    process?: { env?: { NODE_ENV?: string } };
  };
  if (typeof runtime.__DEV__ === 'boolean') {
    return runtime.__DEV__;
  }
  return runtime.process?.env?.NODE_ENV !== 'production';
}

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

const registry = new WeakMap<object, ContractNodeProvenance>();
let handleInstalled = false;

function ensureGlobalHandle(): void {
  if (handleInstalled) {
    return;
  }
  handleInstalled = true;
  (globalThis as Record<string, unknown>).__exactContractProvenance = {
    get: getNodeProvenance,
  };
}

export function getNodeProvenance(host: object): ContractNodeProvenance | undefined {
  return registry.get(host);
}

function setNodeProvenance(host: object, provenance: ContractNodeProvenance): void {
  ensureGlobalHandle();
  registry.set(host, provenance);
}

// ---------------------------------------------------------------------------
// Expression classification
// ---------------------------------------------------------------------------

function isLiteralExpr(expr: Expr): boolean {
  return (
    expr.kind === 'string' ||
    expr.kind === 'number' ||
    expr.kind === 'boolean' ||
    expr.kind === 'null'
  );
}

function isThemeLike(value: unknown): boolean {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  try {
    const candidate = value as Record<string, unknown>;
    return 'colors' in candidate && 'scheme' in candidate && 'space' in candidate;
  } catch {
    return false;
  }
}

/** Compact one-line expression printer for panel display. */
export function printExpr(expr: Expr): string {
  const print = (e: Expr): string => {
    switch (e.kind) {
      case 'token':
        return `$${e.path}`;
      case 'string':
        return JSON.stringify(e.value);
      case 'number':
        return String(e.value);
      case 'boolean':
        return String(e.value);
      case 'null':
        return 'null';
      case 'ident':
        return e.name;
      case 'member':
        return `${print(e.object)}.${e.property}`;
      case 'index':
        return `${print(e.object)}[${print(e.index)}]`;
      case 'call':
        return `${print(e.callee)}(${e.args.map(print).join(', ')})`;
      case 'relation':
        return `${e.op}(${e.args.map(print).join(', ')})`;
      case 'binary':
        return `${print(e.left)} ${e.op} ${print(e.right)}`;
      case 'ternary':
        return `${print(e.test)} ? ${print(e.consequent)} : ${print(e.alternate)}`;
      case 'template':
        return '`…`';
      case 'array':
        return '[…]';
      case 'object':
        return '{…}';
      case 'arrow':
        return `(${e.params.join(', ')}) => …`;
      default:
        return (e as { kind: string }).kind;
    }
  };
  const text = print(expr);
  return text.length > 72 ? `${text.slice(0, 69)}…` : text;
}

function calleeName(expr: Expr): string | null {
  if (expr.kind === 'ident') {
    return expr.name;
  }
  if (expr.kind === 'member') {
    return expr.property;
  }
  return null;
}

/**
 * Classifies one attribute expression. Literals and theme-rooted member
 * chains are `exact`; everything else is `computed` (the literal-editing
 * rule's boundary, LLP 0158 §4.3).
 */
export function classifyExpr(expr: Expr, scope: Scope, sourceAttr?: string): AttrOrigin {
  try {
    // First-class token reference (LLP 0166 §4.4): token-ness is a
    // parse-time fact — classified statically, no scope evaluation, so this
    // works in unmounted/static contexts where the runtime heuristic below
    // cannot run at all.
    if (expr.kind === 'token') {
      return {
        kind: 'token',
        confidence: 'exact',
        sourceAttr,
        tokenPath: expr.path,
        tokenRoot: '$',
      };
    }
    if (expr.kind === 'relation') {
      return {
        kind: 'relation',
        confidence: 'exact',
        sourceAttr,
        expr: printExpr(expr),
        relation: {
          op: expr.op,
          args: expr.args.map(printExpr),
        },
      };
    }
    if (isLiteralExpr(expr)) {
      return {
        kind: 'literal',
        confidence: 'exact',
        sourceAttr,
        value: untrack(() => evalExpr(expr, scope, VIEW_EVAL)),
      };
    }

    if (expr.kind === 'member') {
      const path: string[] = [];
      let cursor: Expr = expr;
      while (cursor.kind === 'member') {
        path.unshift(cursor.property);
        cursor = cursor.object;
      }
      if (cursor.kind === 'ident') {
        const rootName = cursor.name;
        const rootValue = untrack(() => {
          try {
            return evalExpr({ kind: 'ident', name: rootName }, scope, VIEW_EVAL);
          } catch {
            return undefined;
          }
        });
        if (isThemeLike(rootValue)) {
          return {
            kind: 'token',
            confidence: 'exact',
            sourceAttr,
            tokenPath: path.join('.'),
            tokenRoot: rootName,
          };
        }
      }
      return { kind: 'computed', confidence: 'computed', sourceAttr, expr: printExpr(expr) };
    }

    if (expr.kind === 'call') {
      const name = calleeName(expr.callee);
      const callee = expr.callee;
      const args = expr.args;
      const origin: AttrOrigin = {
        kind: 'computed',
        confidence: 'computed',
        sourceAttr,
        expr: printExpr(expr),
      };
      if (name) {
        origin.recipeCall = { name };
        origin.evalRecipe = () => {
          try {
            return untrack(() => ({
              fn: evalExpr(callee, scope, VIEW_EVAL),
              args: args.map((arg) => evalExpr(arg, scope, VIEW_EVAL)),
            }));
          } catch {
            return null;
          }
        };
      }
      return origin;
    }

    return { kind: 'computed', confidence: 'computed', sourceAttr, expr: printExpr(expr) };
  } catch {
    return { kind: 'computed', confidence: 'computed', sourceAttr };
  }
}

/** Per-entry origins for a literal `style={…}` object attr. */
export function classifyStyleObject(
  expr: Expr,
  scope: Scope,
): Record<string, AttrOrigin> | null {
  if (expr.kind !== 'object') {
    return null;
  }
  const origins: Record<string, AttrOrigin> = {};
  for (const entry of expr.entries) {
    if (isExprSpread(entry)) {
      continue; // Spread style entries have no per-key provenance.
    }
    origins[entry.key] = classifyExpr(entry.value, scope, 'style');
  }
  return origins;
}

// ---------------------------------------------------------------------------
// Recorder used by view.ts (single call site per mount path)
// ---------------------------------------------------------------------------

export interface ElementProvenanceRecorder {
  record(finalProp: string, sourceAttr: string, expr: Expr): void;
  recordStyleObject(expr: Expr): void;
  recordStyleSource(expr: Expr): void;
  finish(host: object): void;
}

interface ElementNodeLike {
  tag: string;
  span: { line: number };
  propSources?: Record<string, string>;
}

interface MountEnvLike {
  scope: Scope;
  component: { name: string; file: { sourcePath?: string } };
}

export function beginElementProvenance(
  node: ElementNodeLike,
  env: MountEnvLike,
): ElementProvenanceRecorder | null {
  if (!isContractDevMode()) {
    return null;
  }
  const attrs: Record<string, AttrOrigin> = {};
  let styleSource: AttrOrigin | undefined;
  return {
    record(finalProp, sourceAttr, expr) {
      const origin = classifyExpr(expr, env.scope, sourceAttr);
      const rawSource = node.propSources?.[sourceAttr];
      if (origin.kind === 'literal' && typeof rawSource === 'string') {
        origin.rawSource = rawSource;
      }
      attrs[finalProp] = origin;
    },
    recordStyleObject(expr) {
      const entries = classifyStyleObject(expr, env.scope);
      if (entries) {
        Object.assign(attrs, entries);
      }
    },
    recordStyleSource(expr) {
      styleSource = classifyExpr(expr, env.scope, 'style');
    },
    finish(host) {
      setNodeProvenance(host, {
        componentName: env.component.name,
        sourcePath: env.component.file.sourcePath,
        line: node.span.line,
        tag: node.tag,
        attrs,
        styleSource,
      });
    },
  };
}

export function attachTextProvenance(
  host: object,
  expr: Expr,
  scope: Scope,
  env: MountEnvLike,
  line: number | undefined,
): void {
  if (!isContractDevMode()) {
    return;
  }
  setNodeProvenance(host, {
    componentName: env.component.name,
    sourcePath: env.component.file.sourcePath,
    line,
    attrs: {},
    text: classifyExpr(expr, scope, 'text'),
  });
}

export function attachComponentBoundary(
  host: object,
  boundary: ComponentBoundaryProvenance,
): void {
  if (!isContractDevMode()) {
    return;
  }
  const existing = registry.get(host);
  if (existing) {
    existing.boundary = boundary;
    return;
  }
  setNodeProvenance(host, {
    componentName: boundary.componentName,
    sourcePath: boundary.definitionSourcePath,
    attrs: {},
    boundary,
  });
}
