type HostNode = ElementNode | TextNode;
type HostParent = ElementNode | RootNode;

const VIEW_EVAL = { identFallbackToString: true } as const;

function isCompiledComponentValue(value: unknown): value is CompiledComponent {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { kind?: unknown }).kind === 'contract-component'
  );
}

// ---------------------------------------------------------------------------
// Tag + prop lowering (LLP 0084 host mapping)
// ---------------------------------------------------------------------------

const TAG_LOWERING: Record<string, ContractTagLowering> = CONTRACT_TAG_LOWERING;
const STYLE_PROP_MAP: Record<string, string> = CONTRACT_STYLE_PROP_MAP;
const TEXT_STYLE_PROP_MAP: Record<string, string> = CONTRACT_TEXT_STYLE_PROP_MAP;
const PROP_RENAMES: Record<string, string> = CONTRACT_PROP_RENAMES;

interface OverlayPropLowering {
  hostProp: string;
  map?: (value: unknown) => unknown;
}

function lowerOverlayProp(name: string): OverlayPropLowering | undefined {
  const hostProp = (CONTRACT_OVERLAY_PROP_MAP as Record<string, string>)[name];
  if (!hostProp) {
    return undefined;
  }
  return {
    hostProp,
    map: name === 'focusTrap' ? mapFocusTrapValue : undefined,
  };
}

function mapFocusTrapValue(value: unknown): unknown {
  return value === true ? 'trapped' : undefined;
}

function mapHeadingLevelValue(value: unknown): unknown {
  return typeof value === 'number' && Number.isInteger(value) && value >= 1 && value <= 6
    ? value
    : undefined;
}

function actionNameFromExpr(expr: Expr): string | undefined {
  if (expr.kind === 'ident') {
    return expr.name;
  }
  if (expr.kind === 'call' && expr.callee.kind === 'ident') {
    return expr.callee.name;
  }
  return undefined;
}

// `submit`, `keydown`, and `dismiss` all lower to onKeyDown, so onKeyDown
// consumers compose instead of clobbering (authoring order preserved).
// Module-scope: mountElement runs per element and must not re-allocate it.
function chainEventHandler(existing: unknown, next: (payload: unknown) => void) {
  if (typeof existing !== 'function') {
    return next;
  }
  return (payload: unknown) => {
    (existing as (p: unknown) => void)(payload);
    next(payload);
  };
}

function lowerEventName(event: string, tag: string): string | null {
  switch (event) {
    case 'press':
      return 'onPress';
    case 'longpress':
      return 'onLongPress';
    case 'keydown':
      return 'onKeyDown';
    case 'change':
      if (tag === 'input') {
        return 'onChangeText';
      }
      if (tag === 'toggle') {
        return 'onValueChange';
      }
      return 'onChange';
    case 'focus':
      return 'onFocus';
    case 'blur':
      return 'onBlur';
    case 'submit':
      return 'onKeyDown';
    // LLP 0281 stage 0 pointer vocabulary (LLP 0275 A1). The web host
    // (dom-mirror) delivers element-local envelopes; native delivery
    // arrives with LLP 0099's intake substrate.
    case 'pointerdown':
      return 'onPointerDown';
    case 'pointermove':
      return 'onPointerMove';
    case 'pointerup':
      return 'onPointerUp';
    case 'pointercancel':
      return 'onPointerCancel';
    case 'pointerenter':
      return 'onPointerEnter';
    case 'pointerleave':
      return 'onPointerLeave';
    default:
      return null;
  }
}

// ---------------------------------------------------------------------------
// LLP 0281 stage 0 — channel event targets and the §3.4 sampled crossing
// ---------------------------------------------------------------------------

/** Resolve a channel handle (or a channel-set's `.self`) to its channel. */
function toValueChannel(value: unknown): ContractValueChannel | null {
  if (isValueChannel(value)) {
    return value;
  }
  if (isValueChannelSet(value)) {
    return value.self;
  }
  return null;
}

/**
 * A pointer event attr whose expression is an ident/member chain resolving
 * to a value channel binds as a channel write (the §3.1 rule: the
 * affordable path is the only path). Resolution happens once, untracked —
 * channel handles are stable per component instance.
 */
function resolveChannelEventTarget(handlerExpr: Expr, scope: Scope): ContractValueChannel | null {
  if (handlerExpr.kind !== 'ident' && handlerExpr.kind !== 'member') {
    return null;
  }
  const value = untrack(() => {
    try {
      return evalRuntimeExpr(handlerExpr, scope);
    } catch {
      return null;
    }
  });
  return toValueChannel(value);
}

/** Channels named by `sample(<channel>)` arguments of an edge action call. */
function sampledChannelsInCall(handlerExpr: Expr, scope: Scope): ContractValueChannel[] {
  if (handlerExpr.kind !== 'call') {
    return [];
  }
  const channels: ContractValueChannel[] = [];
  const visit = (expr: Expr): void => {
    if (expr.kind === 'call' && expr.callee.kind === 'ident' && expr.callee.name === 'sample') {
      const target = expr.args[0];
      if (target) {
        const channel = resolveChannelEventTarget(target, scope);
        if (channel) {
          channels.push(channel);
        }
      }
      return;
    }
    switch (expr.kind) {
      case 'call':
        visit(expr.callee);
        expr.args.forEach(visit);
        break;
      case 'member':
        visit(expr.object);
        break;
      case 'ternary':
        visit(expr.test);
        visit(expr.consequent);
        visit(expr.alternate);
        break;
      case 'binary':
        visit(expr.left);
        visit(expr.right);
        break;
      case 'unary':
        visit(expr.operand);
        break;
      default:
        break;
    }
  };
  handlerExpr.args.forEach(visit);
  return channels;
}

/**
 * Find the value channel a sink expression reads (LLP 0281 §3.3). Runs
 * once at element mount, untracked: channel handles are stable bindings
 * (behavior slots or pass-through props), so resolution never needs to be
 * reactive. Returns the first channel found — the analyzer restricts sink
 * expressions to one channel plus literals.
 */
function findChannelReadInExpr(expr: Expr, scope: Scope): ContractValueChannel | null {
  let found: ContractValueChannel | null = null;
  const lookupChannel = (name: string): ContractValueChannel | null => {
    const binding = scope.lookup(name);
    if (!binding) {
      return null;
    }
    const value =
      binding.kind === 'value' || binding.kind === 'local'
        ? binding.value
        : untrack(() => {
            try {
              return binding.get();
            } catch {
              return null;
            }
          });
    return toValueChannel(value);
  };
  const visit = (node: Expr): void => {
    if (found) {
      return;
    }
    switch (node.kind) {
      case 'ident':
        found = lookupChannel(node.name);
        return;
      case 'member':
        visit(node.object);
        return;
      case 'index':
        visit(node.object);
        visit(node.index);
        return;
      case 'call':
        visit(node.callee);
        node.args.forEach(visit);
        return;
      case 'unary':
        visit(node.operand);
        return;
      case 'binary':
        visit(node.left);
        visit(node.right);
        return;
      case 'ternary':
        visit(node.test);
        visit(node.consequent);
        visit(node.alternate);
        return;
      case 'template':
        node.parts.forEach((part) => {
          if (part.kind === 'expr') {
            visit(part.expr);
          }
        });
        return;
      case 'array':
        node.items.forEach((item) => visit(isExprSpread(item) ? item.value : item));
        return;
      case 'object':
        node.entries.forEach((entry) => visit(isExprSpread(entry) ? entry.value : entry.value));
        return;
      default:
        return;
    }
  };
  visit(expr);
  return found;
}

/**
 * Wire channel style sinks for one element: per coalesced channel frame,
 * evaluate the sink expression (channel getters + literals — cheap by
 * analyzer rule) and write it through the host channel-apply seam. When no
 * host applier exists (native pre-0099, bare tests), fall back to an
 * ordinary coalesced host-ops prop update — correct semantics, slower
 * path, still at most once per frame.
 */
function wireChannelStyleSinks(
  sinks: Array<{ styleProp: string; expr: Expr; channel: ContractValueChannel }>,
  element: ElementNode,
  scope: Scope,
  locus: ContractErrorLocus | null,
  applyFallbackStyle: (styleProp: string, value: unknown) => void,
): void {
  const owner = getOwner();
  sinks.forEach((sink) => {
    const applySink = (): void => {
      const value = untrack(() =>
        locus
          ? runWithContractErrorLocus(locus, () => evalRuntimeExpr(sink.expr, scope, VIEW_EVAL))
          : evalRuntimeExpr(sink.expr, scope, VIEW_EVAL),
      );
      if (!applyHostChannelStyle(element, sink.styleProp, value)) {
        applyFallbackStyle(sink.styleProp, value);
      }
    };
    const unsubscribe = sink.channel.subscribe(() => applySink());
    owner?.register(unsubscribe);
    if (sink.channel.hasSample) {
      applySink();
    }
  });
}

/** Normalize whatever the host delivered into a channel envelope. */
function toChannelEnvelope(payload: unknown, phase: string): ChannelHostEnvelope | null {
  if (payload && typeof payload === 'object') {
    const record = payload as Record<string, unknown>;
    if (record.sample && typeof record.sample === 'object') {
      return record as unknown as ChannelHostEnvelope;
    }
    // Degraded delivery (a synthetic caller passing bare coordinates).
    if (typeof record.x === 'number' && typeof record.y === 'number') {
      return {
        sample: {
          x: record.x,
          y: record.y,
          pointerId: typeof record.pointerId === 'number' ? record.pointerId : -1,
          pointerType: typeof record.pointerType === 'string' ? record.pointerType : 'synthetic',
          buttons: typeof record.buttons === 'number' ? record.buttons : 0,
          pressure: typeof record.pressure === 'number' ? record.pressure : 0,
        },
        phase,
      };
    }
  }
  return null;
}

/**
 * Wire one pointer event attr. Channel targets write into the channel
 * (frame-coalesced for continuous events, immediate for edges — §3.4);
 * edge action calls carrying `sample(...)` first apply the edge payload to
 * the sampled channels non-coalesced, then invoke the action, so the seal
 * observes the final sample (§3.4 atomic sampling).
 */
function makePointerEventHandler(
  event: string,
  handlerExpr: Expr,
  scope: Scope,
  locus: ContractErrorLocus | null,
): ((payload?: unknown) => void) | null {
  const channel = resolveChannelEventTarget(handlerExpr, scope);
  if (channel) {
    const immediate = CONTRACT_POINTER_EDGE_EVENTS.has(event);
    return (payload?: unknown) => {
      const envelope = toChannelEnvelope(payload, event);
      if (envelope) {
        channel.writeFromHost(envelope, { immediate });
      }
    };
  }
  if (CONTRACT_POINTER_CONTINUOUS_EVENTS.has(event)) {
    // Continuous events bind only to channels (analyzer-enforced; runtime
    // degrades to a no-op with a warning rather than running an action at
    // input cadence).
    console.warn(
      `[contract] ${event}= must bind a value channel; transactional handlers are not run at pointer cadence (LLP 0281 §3.1)`,
    );
    return () => {};
  }
  const sampled = sampledChannelsInCall(handlerExpr, scope);
  const invoke = makeHandler(handlerExpr, scope, locus ?? undefined);
  if (sampled.length === 0) {
    return invoke;
  }
  return (payload?: unknown) => {
    const envelope = toChannelEnvelope(payload, event);
    if (envelope) {
      for (const sampledChannel of sampled) {
        sampledChannel.writeFromHost(envelope, { immediate: true });
      }
    }
    invoke(payload);
  };
}

/**
 * LLP 0281 §3.1 (ENG-22525) — mount a rated publish line:
 * `publish <channel> -> <descriptor> rate=<Hz> [payload={...}]`.
 *
 * Renders nothing. Resolves the channel-set handle from the line's channel
 * expression root (the analyzer restricts the shape to `cursors` /
 * `cursors.self`), the descriptor callable from scope, and the provider
 * budget facts from the resolved import descriptor, then attaches a rated
 * publisher through the set's protocol hook (`__attachPublisher` — the
 * implementation lives behind `@exact/contract/channels`; a set without
 * the hook degrades to a warning). The publisher is disposed by the owner
 * (unmount / reset-based HMR) and by the set's own dispose — both paths
 * are idempotent.
 */
function mountPublish(
  node: Extract<ViewNodeIR, { kind: 'publish' }>,
  env: MountEnv,
): Mounted {
  const warn = (reason: string): Mounted => {
    console.warn(`[contract] publish -> ${node.descriptor}: ${reason} (LLP 0281 §3.1)`);
    return emptyMounted();
  };

  // Channel-set handle: evaluate the chain ROOT (`cursors`), not the chain
  // itself — the publisher needs the set, and stage 0 has one channel per
  // set (`.self`).
  let rootExpr: Expr = node.channel;
  while (rootExpr.kind === 'member') {
    rootExpr = rootExpr.object;
  }
  const handle = untrack(() => evalRuntimeExpr(rootExpr, env.scope, VIEW_EVAL));
  const set = isValueChannelSet(handle) ? handle : null;
  if (!set) {
    return warn('the publish target is not a value channel');
  }
  if (typeof set.__attachPublisher !== 'function') {
    return warn('this channel implementation does not support rated publish');
  }

  const descriptorValue = untrack(() => evalRuntimeExpr({ kind: 'ident', name: node.descriptor }, env.scope, VIEW_EVAL));
  if (typeof descriptorValue !== 'function') {
    return warn('the publish descriptor did not resolve to a callable');
  }

  if (typeof node.rate !== 'number' || !(node.rate > 0)) {
    return warn('publish requires a positive literal rate');
  }

  // Provider budget facts ride the resolved import descriptor
  // (publish-kind `budget`, or transitional mutation-shaped `publishBudget`).
  const imported = env.component.file.imports?.[node.descriptor]?.descriptor;
  const budget: ChannelPublishBudget | undefined =
    imported?.kind === 'publish'
      ? imported.budget
      : imported?.kind === 'mutation'
        ? imported.publishBudget
        : undefined;

  // The authored payload mapping evaluates per publish tick in the CHANNEL
  // lane with `sample` (sealed) and `element` (box) bound in a child scope —
  // committed component state reads are untracked §3.4 parameters.
  const payloadExpr = node.payload;
  const payloadEvaluator = payloadExpr
    ? (bindings: { sample: Readonly<PointerSample>; element: ChannelElementBox }): unknown => {
        const lane = env.scope.child();
        lane.defineValue('sample', bindings.sample);
        lane.defineValue('element', bindings.element);
        return untrack(() => evalRuntimeExpr(payloadExpr, lane));
      }
    : undefined;

  // Heartbeat (ENG-22539): the declared idle keepalive floor. The analyzer
  // pins it as a positive literal ≤ rate; a malformed value degrades to no
  // heartbeat rather than an unpaced publisher.
  const heartbeatHz =
    typeof node.heartbeat === 'number' && node.heartbeat > 0 ? node.heartbeat : undefined;

  const disposePublisher = set.__attachPublisher({
    publish: descriptorValue as (args: unknown) => unknown,
    rateHz: node.rate,
    heartbeatHz,
    descriptor: node.descriptor,
    budget,
    payloadEvaluator,
  });
  getOwner()?.register(disposePublisher);

  return emptyMounted();
}

function keyFromPayload(payload: unknown): string | undefined {
  if (!payload || typeof payload !== 'object') {
    return undefined;
  }
  const record = payload as { key?: unknown; nativeEvent?: { key?: unknown } };
  if (typeof record.key === 'string') {
    return record.key;
  }
  return typeof record.nativeEvent?.key === 'string' ? record.nativeEvent.key : undefined;
}

// @ref LLP 0292 §Per-node keydown on native — the element-scoped keydown attr
// is only reliably delivered by the web dom-mirror (focus-scoped DOM listener
// + granted tabindex="-1"). Native hosts have no per-node focus model: the
// presenters capture hardware keys app-wide and heuristically dispatch to the
// deepest mounted node with a keydown handler, only while the presenter's own
// capture view is first responder (other responders routinely preempt it),
// and native text inputs forward only Enter. Warn once (ENG-22597) so a
// keydown= consumer that appears dead on native is a diagnosis, not a
// mystery. `submit`/`dismiss` also lower to onKeyDown but have working native
// paths, so only the explicit keydown attr warns.
let warnedNativeKeydownAttr = false;
function warnNativeKeydownAttrOnce(tag: string): void {
  if (warnedNativeKeydownAttr || typeof document !== 'undefined') {
    return;
  }
  warnedNativeKeydownAttr = true;
  console.warn(
    `[contract] keydown= (here on <${tag}>) has no reliable per-node backing on native hosts: ` +
      'there is no native focus model yet, so hardware keys are captured app-wide and ' +
      'heuristically delivered to the deepest mounted keydown consumer, and native text ' +
      'inputs deliver only Enter. For app-level keys, bind through the keyboard capability ' +
      '(use keyboard from "@exact/contract/runtime"), which has native macOS/iOS backing. ' +
      'See LLP 0292 (ENG-22597).',
  );
}

function makeLinkPressHandler(
  hrefExpr: Expr | undefined,
  scope: Scope,
): ((payload?: unknown) => void) | undefined {
  if (!hrefExpr) {
    return undefined;
  }
  const nativeLinkHandlerAtRender = (globalThis as typeof globalThis & {
    __exactHandleLinkHref?: (href: string) => void | Promise<void>;
  }).__exactHandleLinkHref;
  const initialValue = evalRuntimeExpr(hrefExpr, scope, VIEW_EVAL);
  const initialHref = typeof initialValue === 'string'
    ? initialValue
    : initialValue == null
      ? ''
      : String(initialValue);
  if (initialHref.startsWith('#') && typeof nativeLinkHandlerAtRender !== 'function') {
    return undefined;
  }

  return () => {
    const value = evalRuntimeExpr(hrefExpr, scope, VIEW_EVAL);
    const href = typeof value === 'string' ? value : value == null ? '' : String(value);
    if (href.length === 0) {
      return;
    }

    const nativeLinkHandler = (globalThis as typeof globalThis & {
      __exactHandleLinkHref?: (href: string) => void | Promise<void>;
    }).__exactHandleLinkHref;

    if (href.startsWith('#') && typeof nativeLinkHandler !== 'function') {
      return;
    }

    if (typeof nativeLinkHandler === 'function') {
      Promise.resolve(nativeLinkHandler(href)).catch((error: unknown) => {
        console.error('[contract] link press failed', error);
      });
    }
  };
}

// ---------------------------------------------------------------------------
// Mounted units
// ---------------------------------------------------------------------------

export interface Mounted {
  /** Current top-level host nodes, in document order. */
  hostNodes(): HostNode[];
  /** Disposes effects and removes host nodes from the tree. */
  dispose(): void;
}

type AnchorFn = () => HostNode | null;

/**
 * Renders the caller's children template into the host position where the
 * child component's view places its `children` slot.
 */
type ChildrenSlot = (parent: HostParent, anchor: AnchorFn | null) => Mounted;

interface MountEnv {
  scope: Scope;
  component: CompiledComponent;
  ctx: RuntimeContext;
  childrenSlot: ChildrenSlot | null;
  /** True only while mounting the component root view node. */
  isRootView: boolean;
  /** Structural ids for this component's view nodes (LLP 0166 §4.7). */
  ids: Map<ViewNodeIR, string>;
  /** `each`-key chain for runtimeNodeKey derivation ('' outside regions). */
  keyChain: string;
  /** Component-call prefix for unique W3 hydration node identities. */
  hydrationPrefix: string;
  /** Keyed-region chain used only for W3 hydration identities. */
  hydrationKeyChain: string;
}

/**
 * Authored locus for a view node (ENG-22443): every view-node span is
 * required IR, so mount- and update-time errors report the authored line of
 * the node whose binding failed.
 */
function viewNodeLocus(env: MountEnv, node: ViewNodeIR, region?: string): ContractErrorLocus {
  return {
    component: env.component.name,
    sourcePath: env.component.file.sourcePath,
    region:
      region ??
      `view <${node.kind === 'element' ? node.tag : node.kind === 'component' ? node.name : node.kind}>`,
    span: node.span,
  };
}

const structuralIdCache = new WeakMap<ComponentIR, Map<ViewNodeIR, string>>();

/** Cached per-IR structural-id assignment (the IR is shared per module). */
export function structuralIdsFor(ir: ComponentIR): Map<ViewNodeIR, string> {
  let ids = structuralIdCache.get(ir);
  if (!ids) {
    ids = assignStructuralIds(ir);
    structuralIdCache.set(ir, ids);
  }
  return ids;
}

function hydrationNodeIdFor(env: MountEnv, structuralId: string): string {
  return contractHydrationNodeId({
    prefix: env.hydrationPrefix,
    structuralId,
    keyChain: env.hydrationKeyChain,
  });
}

function applyHydrationElementProps(
  env: MountEnv,
  structuralId: string | undefined,
  props: Record<string, unknown>,
): string | undefined {
  if (!env.ctx.hydration?.capture || !structuralId) {
    return undefined;
  }
  const nodeId = hydrationNodeIdFor(env, structuralId);
  props['data-exact-hydration-id'] = nodeId;
  props['data-exact-structural-id'] = structuralId;
  if (env.component.file.sourceVersion) {
    props['data-exact-source-version'] = env.component.file.sourceVersion;
  }
  return nodeId;
}

function recordHydrationElement(
  env: MountEnv,
  element: ElementNode,
  structuralId: string | undefined,
  nodeId: string | undefined,
): void {
  if (!env.ctx.hydration?.capture || !structuralId || !nodeId) {
    return;
  }
  env.ctx.hydration.capture.recordNode({
    host: element,
    nodeId,
    structuralId,
    sourcePath: env.component.file.sourcePath,
    sourceVersion: env.component.file.sourceVersion,
    componentName: env.component.name,
    kind: 'element',
  });
}

function recordHydrationHandlers(
  env: MountEnv,
  events: Record<string, Expr>,
  structuralId: string | undefined,
  nodeId: string | undefined,
): void {
  const capture = env.ctx.hydration?.capture;
  if (!capture || !structuralId || !nodeId) {
    return;
  }
  Object.entries(events).forEach(([event, handlerExpr]) => {
    const actionId = actionNameFromExpr(handlerExpr);
    if (!actionId) {
      return;
    }
    capture.recordHandler({
      nodeId,
      structuralId,
      event: event as ContractHydrationEvent,
      actionId,
    });
  });
}

function insertNode(parent: HostParent, node: HostNode, anchor: HostNode | null): void {
  if (anchor) {
    insertBefore(parent, node, anchor);
  } else {
    appendChild(parent, node);
  }
}

/**
 * Mounts sibling view nodes into `parent`. `anchor` resolves the host node
 * the whole list must stay in front of (null appends at the end) — this is
 * how regions insert into the middle of a static parent.
 */
export function mountViewNodes(
  nodes: ViewNodeIR[],
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
): Mounted {
  const slots: Mounted[] = [];

  const anchorFor = (index: number): AnchorFn => () => {
    for (let i = index + 1; i < slots.length; i += 1) {
      const nodesAfter = slots[i].hostNodes();
      if (nodesAfter.length > 0) {
        return nodesAfter[0];
      }
    }
    return anchor ? anchor() : null;
  };

  nodes.forEach((node, index) => {
    const nodeEnv =
      env.isRootView && nodes.length === 1 && index === 0
        ? env
        : { ...env, isRootView: false };
    // ENG-22443: mount-time failures carry the failing node's authored span
    // even when no inner expression span was attached.
    slots.push(
      runWithContractErrorLocus(viewNodeLocus(nodeEnv, node), () =>
        mountViewNode(node, parent, anchorFor(index), nodeEnv),
      ),
    );
  });

  return {
    hostNodes(): HostNode[] {
      return slots.flatMap((slot) => slot.hostNodes());
    },
    dispose(): void {
      for (const slot of slots) {
        slot.dispose();
      }
      slots.length = 0;
    },
  };
}

function mountViewNode(
  node: ViewNodeIR,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  switch (node.kind) {
    case 'element':
      return mountElement(node, parent, anchor, env);
    case 'text':
      return mountText(node, parent, anchor, env);
    case 'nothing':
      return mountNothing();
    case 'hole':
      return mountHole(node, parent, anchor);
    case 'when':
      return mountWhen(node, parent, anchor, env);
    case 'match':
      return mountMatch(node, parent, anchor, env);
    case 'match-size':
      return mountMatchSize(node, parent, anchor, env);
    case 'each':
      return mountEach(node, parent, anchor, env);
    case 'resource':
    case 'async':
      return mountResourceRegion(node, parent, anchor, env);
    case 'boundary':
      return mountBoundary(node, parent, anchor, env);
    case 'component':
      return mountComponent(node, parent, anchor, env);
    case 'publish':
      return mountPublish(node, env);
    case 'children':
      return env.childrenSlot ? env.childrenSlot(parent, anchor) : emptyMounted();
    case 'snippet-call': {
      const snippet = env.component.ir.snippets.find((candidate) => candidate.name === node.name);
      if (!snippet) {
        throw new Error(`[contract] unknown snippet "${node.name}"`);
      }
      // Macro-like expansion: arguments close over the call-site scope.
      const snippetScope = env.scope.child();
      snippet.params.forEach((param, index) => {
        const arg = node.args[index];
        snippetScope.define(param, {
          kind: 'getter',
          get: () => (arg ? evalRuntimeExpr(arg, env.scope, VIEW_EVAL) : undefined),
        });
      });
      return mountViewNodes(snippet.body, parent, anchor, { ...env, scope: snippetScope });
    }
  }
}

function emptyMounted(): Mounted {
  return { hostNodes: () => [], dispose: () => {} };
}

// ---------------------------------------------------------------------------
// Elements + text
// ---------------------------------------------------------------------------

function hasProp(node: Extract<ViewNodeIR, { kind: 'element' }>, name: string): boolean {
  return Object.prototype.hasOwnProperty.call(node.props, name);
}

function hasStyleKey(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  names: Set<string>,
): boolean {
  const styleExpr = node.props.style;
  if (!styleExpr) {
    return false;
  }
  if (styleExpr.kind !== 'object') {
    return true;
  }
  return styleExpr.entries.some((entry) => isExprSpread(entry) || names.has(entry.key));
}

function applyRootScrollDefaults(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  style: Record<string, unknown>,
): void {
  if (!hasProp(node, 'width') && !hasStyleKey(node, new Set(['width']))) {
    style.width = '100%';
  }
  if (!hasProp(node, 'minHeight') && !hasStyleKey(node, new Set(['minHeight']))) {
    style.minHeight = 0;
  }
  if (
    !hasProp(node, 'height') &&
    !hasProp(node, 'minHeight') &&
    !hasProp(node, 'maxHeight') &&
    !hasProp(node, 'flex') &&
    !hasProp(node, 'grow') &&
    !hasProp(node, 'basis') &&
    !hasStyleKey(
      node,
      new Set([
        'height',
        'minHeight',
        'maxHeight',
        'flex',
        'flexGrow',
        'grow',
        'flexBasis',
        'basis',
      ]),
    )
  ) {
    style.flex = 1;
  }
}

function mountElement(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const { scope } = env;
  const lowering = TAG_LOWERING[node.tag];
  if (!lowering) {
    throw new Error(`[contract] no host lowering for "${node.tag}"`);
  }
  if ((node.tag === 'list' || node.tag === 'virtualList') && node.props.items) {
    return mountCollectionElement(node, parent, anchor, env, lowering);
  }

  const staticProps: Record<string, unknown> = { ...(lowering.staticProps ?? {}) };
  if (lowering.semanticTag) {
    staticProps.__exactSemanticTag = lowering.semanticTag;
  }
  const staticStyle: Record<string, unknown> = { ...(lowering.staticStyle ?? {}) };
  // Literal authored style attrs live in their own layer so they override
  // `style=` sources (style recipes / style objects) deterministically:
  // lowering defaults < style= output < authored attrs (LLP 0254 §4.4,
  // pinned by contract-style-recipes.test.ts).
  const staticAttrStyle: Record<string, unknown> = {};
  if (env.isRootView && node.tag === 'scroll') {
    applyRootScrollDefaults(node, staticStyle);
  }
  const dynamicProps: Array<{ hostProp: string; expr: Expr; map?: (value: unknown) => unknown }> = [];
  const dynamicStyle: Array<{ styleProp: string; expr: Expr }> = [];
  // LLP 0281 §3.3 — channel-driven sink attrs (transform/opacity). Applied
  // per coalesced channel frame through the host seam, never through the
  // reactive patch effect below.
  const channelStyleSinks: Array<{ styleProp: string; expr: Expr; channel: ContractValueChannel }> = [];
  // Authored attr -> lowered host target, for the S4 hot-patch pipeline.
  const attrTargets: Record<string, { target: 'prop' | 'style'; name: string }> = {};
  let dynamicStyleObject: Expr | null = null;
  let interactionExpr: Expr | null = null;
  let dismissExpr: Expr | null = null;
  // Design Mode D0 (LLP 0158): null in production, no per-attr cost there.
  const provenance = beginElementProvenance(node, env);

  for (const [name, expr] of Object.entries(node.props)) {
    if (name === 'interaction') {
      interactionExpr = expr;
      continue;
    }
    if (name === 'dismiss') {
      dismissExpr = expr;
      staticProps.__exactDismissableLayer = true;
      const actionName = actionNameFromExpr(expr);
      if (actionName) {
        staticProps.__exactDismissAction = actionName;
      }
      attrTargets[name] = { target: 'prop', name: '__exactDismissableLayer' };
      provenance?.record('__exactDismissableLayer', name, expr);
      continue;
    }
    if (name === 'style') {
      if (isLiteral(expr)) {
        applyStyleObject(staticStyle, evalRuntimeExpr(expr, scope, VIEW_EVAL));
        provenance?.recordStyleObject(expr);
      } else if (expr.kind === 'object') {
        dynamicStyleObject = expr;
        provenance?.recordStyleObject(expr);
      } else {
        dynamicStyleObject = expr;
        provenance?.recordStyleSource(expr);
      }
      continue;
    }
    const stylePropName =
      STYLE_PROP_MAP[name] ??
      (CONTRACT_TEXT_BEARING_TAG_SET.has(node.tag) ? TEXT_STYLE_PROP_MAP[name] : undefined);
    if (stylePropName) {
      attrTargets[name] = { target: 'style', name: stylePropName };
      provenance?.record(stylePropName, name, expr);
      if (isLiteral(expr)) {
        applyStyleValue(
          staticAttrStyle,
          stylePropName,
          transformLoweredStyleValue(stylePropName, evalRuntimeExpr(expr, scope, VIEW_EVAL)),
        );
      } else {
        const sinkChannel = CONTRACT_CHANNEL_SINK_ATTRS.has(name)
          ? findChannelReadInExpr(expr, scope)
          : null;
        if (sinkChannel) {
          channelStyleSinks.push({ styleProp: stylePropName, expr, channel: sinkChannel });
        } else {
          dynamicStyle.push({ styleProp: stylePropName, expr });
        }
      }
      continue;
    }
    const mappedOverlay = lowerOverlayProp(name);
    const hostProp = mappedOverlay?.hostProp ?? PROP_RENAMES[name] ?? name;
    const mapProp = mappedOverlay?.map ?? (name === 'headingLevel' ? mapHeadingLevelValue : undefined);
    attrTargets[name] = { target: 'prop', name: hostProp };
    provenance?.record(hostProp, name, expr);
    if (isLiteral(expr)) {
      const rawValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
      staticProps[hostProp] = mapProp ? mapProp(rawValue) : rawValue;
    } else {
      dynamicProps.push({ hostProp, expr, map: mapProp });
    }
  }

  if (node.tag === 'text' && node.props.headingLevel && !node.props.role && !node.props.accessibilityRole) {
    staticProps.accessibilityRole = 'heading';
  }

  // Event handlers wire once. forEach, not for-of: the submit wrapper
  // closure escapes the iteration, and Hermes scopes for-of `const` to the
  // function (the module loader's rewrite skips bodies with `continue`).
  const eventProps: Record<string, unknown> = {};
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    const hostEvent = lowerEventName(event, node.tag);
    if (!hostEvent) {
      console.warn(`[contract] event "${event}" has no host lowering on <${node.tag}>`);
      return;
    }
    if (CONTRACT_POINTER_EVENT_SET.has(event)) {
      const pointerHandler = makePointerEventHandler(
        event,
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      if (pointerHandler) {
        eventProps[hostEvent] = pointerHandler;
      }
      return;
    }
    const invoke = makeHandler(handlerExpr, scope, viewNodeLocus(env, node, `event "${event}"`));
    if (event === 'submit') {
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload: unknown) => {
        if (!payload || keyFromPayload(payload) === 'Enter') {
          invoke(payload);
        }
      });
    } else if (event === 'keydown') {
      // The action receives the key string (`action onKey(key)`), matching
      // how `change` delivers the input value (LLP 0293 ledger row 1).
      warnNativeKeydownAttrOnce(node.tag);
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload: unknown) => {
        invoke(keyFromPayload(payload) ?? payload);
      });
    } else {
      eventProps[hostEvent] = invoke;
    }
  });
  if (node.tag === 'link' && typeof eventProps.onPress !== 'function') {
    const linkPress = makeLinkPressHandler(node.props.href, scope);
    if (linkPress) {
      eventProps.onPress = linkPress;
    }
  }
  if (dismissExpr) {
    const dismiss = makeHandler(dismissExpr, scope, viewNodeLocus(env, node, 'event "dismiss"'));
    eventProps.onKeyDown = chainEventHandler(eventProps.onKeyDown, (payload: unknown) => {
      if (!payload || keyFromPayload(payload) === 'Escape') {
        dismiss(payload);
      }
    });
  }

  // Behavior attachment (the interaction-state primitive, LLP 0157 §5/F2a-i).
  let attachedBehavior: unknown = null;
  if (interactionExpr) {
    const behavior = untrack(() => evalRuntimeExpr(interactionExpr!, scope));
    attachedBehavior = behavior;
    if (isBehaviorInstance(behavior) && behavior.attachProps) {
      Object.entries(behavior.attachProps()).forEach(([propName, handler]) => {
        const existing = eventProps[propName];
        if (typeof existing === 'function' && typeof handler === 'function') {
          eventProps[propName] = (...args: unknown[]) => {
            (handler as (...a: unknown[]) => void)(...args);
            (existing as (...a: unknown[]) => void)(...args);
          };
        } else {
          eventProps[propName] = handler;
        }
      });
    } else if (behavior != null) {
      console.warn('[contract] interaction= expects a behavior instance');
    }
  }

  const hasDynamic =
    dynamicProps.length > 0 || dynamicStyle.length > 0 || dynamicStyleObject !== null;
  const structuralId = env.ids.get(node);
  const hydrationNodeId = applyHydrationElementProps(env, structuralId, staticProps);
  const initialProps: Record<string, unknown> = { ...staticProps, ...eventProps };
  if (!hasDynamic && (Object.keys(staticStyle).length > 0 || Object.keys(staticAttrStyle).length > 0)) {
    initialProps.style = { ...staticStyle, ...staticAttrStyle };
  }

  const element = createInstance(lowering.tag, initialProps);
  recordHydrationElement(env, element, structuralId, hydrationNodeId);
  recordHydrationHandlers(env, node.events, structuralId, hydrationNodeId);
  provenance?.finish(element);
  let lastProps = initialProps;

  if (isContractDevMode()) {
    if (isBehaviorInstance(attachedBehavior)) {
      // State forcing (LLP 0163 E1d): the panel pins hover/pressed/focus
      // through the behavior instance attached to this element.
      registerInteractionTarget(
        element,
        attachedBehavior as { force?: (state: Record<string, boolean>) => void },
      );
    }
    if (structuralId) {
      const unregister = registerLiveNode({
        structuralId,
        sourcePath: env.component.file.sourcePath,
        sourceVersion: env.component.file.sourceVersion,
        keyChain: env.keyChain,
        host: element,
        patch: {
          kind: 'element',
          attrTargets,
          applyStatic(mutation) {
            // Mutate the closed-over static objects so future effect runs
            // rebuild from the patched values (no revert on the next flush),
            // then push through the normal update path. Style patches land in
            // the authored-attr layer so an edit keeps winning over `style=`
            // recipe output (LLP 0254 §4.4).
            if (mutation.props) {
              Object.assign(staticProps, mutation.props);
            }
            if (mutation.style) {
              Object.assign(staticAttrStyle, mutation.style);
            }
            const baseStyle = (lastProps.style ?? {}) as Record<string, unknown>;
            const nextStyle = { ...baseStyle, ...(mutation.style ?? {}) };
            const next: Record<string, unknown> = { ...lastProps, ...(mutation.props ?? {}) };
            if (Object.keys(nextStyle).length > 0) {
              next.style = nextStyle;
            }
            updateInstanceProps(element, lastProps, next);
            lastProps = next;
          },
        },
      });
      getOwner()?.register(unregister);
    }
  }

  insertNode(parent, element, anchor());

  // Registered BEFORE the attr effect and child mounts: a throw while
  // evaluating either must not leak the inserted element into the committed
  // tree — the owner's disposal removes it (keep-last-good, ENG-22443).
  let disposed = false;
  let childMount: Mounted | null = null;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    childMount?.dispose();
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);

  if (hasDynamic) {
    // One patch effect per element: still fine-grained relative to the
    // component (no tree re-render), without per-prop bookkeeping.
    // Merge order: lowering defaults, then `style=` output (recipe/object),
    // then authored attrs — literal and dynamic — so tag attrs win
    // deterministically over recipe output (LLP 0254 §4.4).
    const attrLocus = viewNodeLocus(env, node);
    ownedEffect(() =>
      runWithContractErrorLocus(attrLocus, () => {
        const style: Record<string, unknown> = { ...staticStyle };
        if (dynamicStyleObject) {
          applyStyleObject(style, evalRuntimeExpr(dynamicStyleObject, scope, VIEW_EVAL));
        }
        Object.assign(style, staticAttrStyle);
        for (const entry of dynamicStyle) {
          applyStyleValue(
            style,
            entry.styleProp,
            transformLoweredStyleValue(entry.styleProp, evalRuntimeExpr(entry.expr, scope, VIEW_EVAL)),
          );
        }
        const next: Record<string, unknown> = { ...staticProps, ...eventProps, style };
        for (const entry of dynamicProps) {
          const rawValue = evalRuntimeExpr(entry.expr, scope, VIEW_EVAL);
          next[entry.hostProp] = entry.map ? entry.map(rawValue) : rawValue;
        }
        updateInstanceProps(element, lastProps, next);
        lastProps = next;
      }),
    );
  }

  if (channelStyleSinks.length > 0) {
    wireChannelStyleSinks(
      channelStyleSinks,
      element,
      scope,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        // Fallback keeps the reactive patch effect coherent: recording the
        // value in the authored-attr layer means the next reactive flush
        // re-emits it instead of reverting the sink.
        staticAttrStyle[styleProp] = value;
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        const next: Record<string, unknown> = { ...lastProps, style };
        updateInstanceProps(element, lastProps, next);
        lastProps = next;
      },
    );
  }

  childMount = mountViewNodes(node.children, element, null, {
    ...env,
    isRootView: false,
  });

  return {
    hostNodes: () => (disposed ? [] : [element]),
    dispose,
  };
}

const COLLECTION_CONTROL_PROPS = new Set([
  'items',
  'as',
  'index',
  'key',
  'estimateSize',
  'estimatedItemSize',
  'viewportSize',
  'scrollOffset',
  'overscan',
  'drawDistance',
]);

interface CollectionMountedRow {
  key: unknown;
  wrapper: ElementNode;
  owner: Owner;
  setItem(value: unknown): void;
  setIndex(value: number): void;
  updateFrame(frame: VirtualListItem | null): void;
}

interface VirtualListPreparedCache {
  items: readonly unknown[];
  estimate: number;
  prepared: PreparedListState;
}

function mountCollectionElement(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
  lowering: ContractTagLowering,
): Mounted {
  const { scope } = env;
  const staticProps: Record<string, unknown> = { ...(lowering.staticProps ?? {}) };
  if (lowering.semanticTag) {
    staticProps.__exactSemanticTag = lowering.semanticTag;
  }
  const staticStyle: Record<string, unknown> = { ...(lowering.staticStyle ?? {}) };
  // Same authored-attr layering as mountElement (LLP 0254 §4.4): lowering
  // defaults < `style=` output < authored attrs.
  const staticAttrStyle: Record<string, unknown> = {};
  const dynamicProps: Array<{ hostProp: string; expr: Expr; map?: (value: unknown) => unknown }> = [];
  const dynamicStyle: Array<{ styleProp: string; expr: Expr }> = [];
  // LLP 0281 §3.3 — channel-driven sink attrs (transform/opacity). Applied
  // per coalesced channel frame through the host seam, never through the
  // reactive patch effect below.
  const channelStyleSinks: Array<{ styleProp: string; expr: Expr; channel: ContractValueChannel }> = [];
  let dynamicStyleObject: Expr | null = null;

  for (const [name, expr] of Object.entries(node.props)) {
    if (COLLECTION_CONTROL_PROPS.has(name)) {
      continue;
    }
    if (name === 'style') {
      if (isLiteral(expr)) {
        applyStyleObject(staticStyle, evalRuntimeExpr(expr, scope, VIEW_EVAL));
      } else {
        dynamicStyleObject = expr;
      }
      continue;
    }
    const stylePropName =
      STYLE_PROP_MAP[name] ??
      (CONTRACT_TEXT_BEARING_TAG_SET.has(node.tag) ? TEXT_STYLE_PROP_MAP[name] : undefined);
    if (stylePropName) {
      if (isLiteral(expr)) {
        applyStyleValue(
          staticAttrStyle,
          stylePropName,
          transformLoweredStyleValue(stylePropName, evalRuntimeExpr(expr, scope, VIEW_EVAL)),
        );
      } else {
        const sinkChannel = CONTRACT_CHANNEL_SINK_ATTRS.has(name)
          ? findChannelReadInExpr(expr, scope)
          : null;
        if (sinkChannel) {
          channelStyleSinks.push({ styleProp: stylePropName, expr, channel: sinkChannel });
        } else {
          dynamicStyle.push({ styleProp: stylePropName, expr });
        }
      }
      continue;
    }
    const mappedOverlay = lowerOverlayProp(name);
    const hostProp = mappedOverlay?.hostProp ?? PROP_RENAMES[name] ?? name;
    const mapProp = mappedOverlay?.map ?? (name === 'headingLevel' ? mapHeadingLevelValue : undefined);
    if (isLiteral(expr)) {
      const rawValue = evalRuntimeExpr(expr, scope, VIEW_EVAL);
      staticProps[hostProp] = mapProp ? mapProp(rawValue) : rawValue;
    } else {
      dynamicProps.push({ hostProp, expr, map: mapProp });
    }
  }

  if (node.tag === 'text' && node.props.headingLevel && !node.props.role && !node.props.accessibilityRole) {
    staticProps.accessibilityRole = 'heading';
  }

  const eventProps: Record<string, unknown> = {};
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    const hostEvent = lowerEventName(event, node.tag);
    if (!hostEvent) {
      console.warn(`[contract] event "${event}" has no host lowering on <${node.tag}>`);
      return;
    }
    if (CONTRACT_POINTER_EVENT_SET.has(event)) {
      const pointerHandler = makePointerEventHandler(
        event,
        handlerExpr,
        scope,
        viewNodeLocus(env, node, `event "${event}"`),
      );
      if (pointerHandler) {
        eventProps[hostEvent] = pointerHandler;
      }
      return;
    }
    const invoke = makeHandler(
      handlerExpr,
      scope,
      viewNodeLocus(env, node, `event "${event}"`),
    );
    if (event === 'submit') {
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload: unknown) => {
        if (!payload || keyFromPayload(payload) === 'Enter') {
          invoke(payload);
        }
      });
    } else if (event === 'keydown') {
      warnNativeKeydownAttrOnce(node.tag);
      eventProps[hostEvent] = chainEventHandler(eventProps[hostEvent], (payload: unknown) => {
        invoke(keyFromPayload(payload) ?? payload);
      });
    } else {
      eventProps[hostEvent] = invoke;
    }
  });

  const hasDynamic =
    dynamicProps.length > 0 || dynamicStyle.length > 0 || dynamicStyleObject !== null;
  const structuralId = env.ids.get(node);
  const hydrationNodeId = applyHydrationElementProps(env, structuralId, staticProps);
  const initialProps: Record<string, unknown> = { ...staticProps, ...eventProps };
  if (!hasDynamic && (Object.keys(staticStyle).length > 0 || Object.keys(staticAttrStyle).length > 0)) {
    initialProps.style = { ...staticStyle, ...staticAttrStyle };
  }

  const element = createInstance(lowering.tag, initialProps);
  recordHydrationElement(env, element, structuralId, hydrationNodeId);
  recordHydrationHandlers(env, node.events, structuralId, hydrationNodeId);
  insertNode(parent, element, anchor());
  let lastProps = initialProps;
  const patchElement = (next: Record<string, unknown>): void => {
    updateInstanceProps(element, lastProps, next);
    lastProps = next;
  };

  // Registered BEFORE the attr effect and row mounts: a throw while
  // evaluating either must not leak the inserted element into the committed
  // tree — the owner's disposal removes it (keep-last-good, ENG-22443).
  let disposed = false;
  let content: ElementNode | null = null;
  let rowsMounted: Mounted | null = null;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    rowsMounted?.dispose();
    if (content) {
      removeChild(element, content);
    }
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);

  if (hasDynamic) {
    const attrLocus = viewNodeLocus(env, node);
    ownedEffect(() =>
      runWithContractErrorLocus(attrLocus, () => {
        const style: Record<string, unknown> = { ...staticStyle };
        if (dynamicStyleObject) {
          applyStyleObject(style, evalRuntimeExpr(dynamicStyleObject, scope, VIEW_EVAL));
        }
        Object.assign(style, staticAttrStyle);
        for (const entry of dynamicStyle) {
          applyStyleValue(
            style,
            entry.styleProp,
            transformLoweredStyleValue(entry.styleProp, evalRuntimeExpr(entry.expr, scope, VIEW_EVAL)),
          );
        }
        const next: Record<string, unknown> = { ...lastProps, ...staticProps, ...eventProps, style };
        for (const entry of dynamicProps) {
          const rawValue = evalRuntimeExpr(entry.expr, scope, VIEW_EVAL);
          next[entry.hostProp] = entry.map ? entry.map(rawValue) : rawValue;
        }
        patchElement(next);
      }),
    );
  }

  if (channelStyleSinks.length > 0) {
    wireChannelStyleSinks(
      channelStyleSinks,
      element,
      scope,
      viewNodeLocus(env, node),
      (styleProp, value) => {
        staticAttrStyle[styleProp] = value;
        const style = {
          ...((lastProps.style as Record<string, unknown> | undefined) ?? {}),
          [styleProp]: value,
        };
        patchElement({ ...lastProps, style });
      },
    );
  }

  let collectionParent: HostParent = element;
  let contentLastProps: Record<string, unknown> | null = null;
  if (node.tag === 'virtualList') {
    contentLastProps = { style: { position: 'relative', height: 0 } };
    content = createInstance('View', contentLastProps);
    appendChild(element, content);
    collectionParent = content;
  }

  rowsMounted = mountCollectionRows(node, collectionParent, null, env, {
    patchElement,
    lastElementProps: () => lastProps,
    patchContentStyle(totalSize) {
      if (!content || !contentLastProps) {
        return;
      }
      const next = { ...contentLastProps, style: { position: 'relative', height: totalSize } };
      updateInstanceProps(content, contentLastProps, next);
      contentLastProps = next;
    },
  });

  return {
    hostNodes: () => (disposed ? [] : [element]),
    dispose,
  };
}

function mountCollectionRows(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  parent: HostParent,
  anchor: AnchorFn | null,
  env: MountEnv,
  patches: {
    patchElement(next: Record<string, unknown>): void;
    lastElementProps(): Record<string, unknown>;
    patchContentStyle(totalSize: number): void;
  },
): Mounted {
  const itemName = collectionBindingName(node.props.as, env.scope, 'item');
  const indexName = node.props.index ? collectionBindingName(node.props.index, env.scope, 'index') : null;
  const keyExpr = node.props.key ?? null;
  const virtualized = node.tag === 'virtualList';
  let rows: CollectionMountedRow[] = [];
  let preparedCache: VirtualListPreparedCache | null = null;
  let disposed = false;
  let warnedDuplicateKeys = false;

  const keyFor = (item: unknown, index: number): unknown => {
    if (!keyExpr) {
      return index;
    }
    const keyScope = env.scope.child();
    keyScope.defineValue(itemName, item);
    if (indexName) {
      keyScope.defineValue(indexName, index);
    }
    return evalRuntimeExpr(keyExpr, keyScope, VIEW_EVAL);
  };

  const createRow = (
    item: unknown,
    index: number,
    key: unknown,
    frame: VirtualListItem | null,
  ): CollectionMountedRow => {
    const owner = createOwner();
    const wrapperInitial = collectionRowProps(key, index, frame);
    const wrapper = createInstance('View', wrapperInitial);
    let lastWrapperProps = wrapperInitial;
    insertNode(parent, wrapper, anchor ? anchor() : null);
    // Registered BEFORE mounting children so a mid-mount throw still removes
    // the wrapper when the owner disposes (keep-last-good, ENG-22443).
    owner.register(() => {
      removeChild(parent, wrapper);
    });

    let row: CollectionMountedRow;
    try {
      row = runWithOwner(owner, () => {
        const itemSignal = signal<unknown>(item);
        const indexSignal = signal<number>(index);
        const rowScope = env.scope.child();
        rowScope.define(itemName, { kind: 'getter', get: () => itemSignal.get() });
        if (indexName) {
          rowScope.define(indexName, { kind: 'getter', get: () => indexSignal.get() });
        }
        const mounted = mountViewNodes(node.children, wrapper, null, {
          ...env,
          scope: rowScope,
          isRootView: false,
          keyChain: `${env.keyChain}#${String(key)}`,
          hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
        });
        owner.register(() => {
          mounted.dispose();
        });
        return {
          key,
          wrapper,
          owner,
          setItem(value: unknown) {
            itemSignal.set(value);
          },
          setIndex(value: number) {
            indexSignal.set(value);
          },
          updateFrame(nextFrame: VirtualListItem | null) {
            const next = collectionRowProps(key, indexSignal.get(), nextFrame);
            updateInstanceProps(wrapper, lastWrapperProps, next);
            lastWrapperProps = next;
          },
        };
      });
    } catch (error) {
      owner.dispose();
      throw error;
    }
    return row;
  };

  const collectionLocus = viewNodeLocus(env, node, `${node.tag} items`);
  ownedEffect(() =>
    runWithContractErrorLocus(collectionLocus, () => {
    const rawItems = evalRuntimeExpr(node.props.items, env.scope, VIEW_EVAL);
    const allItems = Array.isArray(rawItems) ? rawItems : [];
    const records = virtualized
      ? computeVirtualRecords(node, env, allItems, keyFor, preparedCache, (next) => {
          preparedCache = next;
        })
      : {
          totalSize: allItems.length,
          items: allItems.map((item, index) => ({
            item,
            index,
            key: keyFor(item, index),
            frame: null,
          })),
          diagnostics: {
            itemCount: allItems.length,
            mountedItemCount: allItems.length,
            visibleStartIndex: allItems.length > 0 ? 0 : -1,
            visibleEndIndex: allItems.length > 0 ? allItems.length - 1 : -1,
            overscanStartIndex: allItems.length > 0 ? 0 : -1,
            overscanEndIndex: allItems.length > 0 ? allItems.length - 1 : -1,
          },
        };

    untrack(() => {
      if (disposed) {
        return;
      }

      patches.patchContentStyle(records.totalSize);
      patches.patchElement({
        ...patches.lastElementProps(),
        virtualized,
        itemCount: records.diagnostics.itemCount,
        mountedItemCount: records.diagnostics.mountedItemCount,
        visibleStartIndex: records.diagnostics.visibleStartIndex,
        visibleEndIndex: records.diagnostics.visibleEndIndex,
        overscanStartIndex: records.diagnostics.overscanStartIndex,
        overscanEndIndex: records.diagnostics.overscanEndIndex,
        totalSize: records.totalSize,
      });

      // Queue per key (ENG-23170): same duplicate-key round-trip as mountEach
      // — a plain Map drops all but the last duplicate, leaking live rows.
      const oldByKey = new Map<unknown, CollectionMountedRow[]>();
      for (const row of rows) {
        const queue = oldByKey.get(row.key);
        if (queue) {
          queue.push(row);
        } else {
          oldByKey.set(row.key, [row]);
        }
      }

      const nextRows: CollectionMountedRow[] = [];
      const createdRows: CollectionMountedRow[] = [];
      const seen = new Set<unknown>();
      let orderChanged = records.items.length !== rows.length;
      try {
        for (const record of records.items) {
          if (seen.has(record.key) && !warnedDuplicateKeys) {
            warnedDuplicateKeys = true;
            console.warn(`[contract] duplicate ${node.tag} key ${String(record.key)}; rows need unique keys`);
          }
          seen.add(record.key);
          const queue = oldByKey.get(record.key);
          const existing = queue?.shift();
          if (existing) {
            if (queue!.length === 0) {
              oldByKey.delete(record.key);
            }
            existing.setItem(record.item);
            existing.setIndex(record.index);
            existing.updateFrame(record.frame);
            orderChanged ||= existing !== rows[nextRows.length];
            nextRows.push(existing);
          } else {
            orderChanged = true;
            const created = createRow(record.item, record.index, record.key, record.frame);
            createdRows.push(created);
            nextRows.push(created);
          }
        }
      } catch (error) {
        // Keep-last-good (ENG-22443): see mountEach — drop only the rows
        // created this pass, keep the committed ones.
        for (const created of createdRows) {
          created.owner.dispose();
        }
        throw error;
      }

      for (const queue of oldByKey.values()) {
        for (const removed of queue) {
          removed.owner.dispose();
        }
      }

      rows = nextRows;
      if (orderChanged) {
        let nextAnchor: HostNode | null = anchor ? anchor() : null;
        for (let i = rows.length - 1; i >= 0; i -= 1) {
          const row = rows[i];
          if (nextAnchor) {
            insertBefore(parent, row.wrapper, nextAnchor);
          } else {
            appendChild(parent, row.wrapper);
          }
          nextAnchor = row.wrapper;
        }
      }
    });
    }),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    for (const row of rows) {
      row.owner.dispose();
    }
    rows = [];
  };

  return { hostNodes: () => rows.map((row) => row.wrapper), dispose };
}

function collectionBindingName(expr: Expr | undefined, scope: Scope, fallback: string): string {
  if (!expr) {
    return fallback;
  }
  const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
  return typeof value === 'string' && value.length > 0 ? value : fallback;
}

function computeVirtualRecords(
  node: Extract<ViewNodeIR, { kind: 'element' }>,
  env: MountEnv,
  allItems: unknown[],
  keyFor: (item: unknown, index: number) => unknown,
  cache: VirtualListPreparedCache | null,
  setCache: (next: VirtualListPreparedCache) => void,
): {
  totalSize: number;
  items: Array<{ item: unknown; index: number; key: unknown; frame: VirtualListItem | null }>;
  diagnostics: {
    itemCount: number;
    mountedItemCount: number;
    visibleStartIndex: number;
    visibleEndIndex: number;
    overscanStartIndex: number;
    overscanEndIndex: number;
  };
} {
  const estimate = numberProp(node.props.estimateSize ?? node.props.estimatedItemSize, env.scope, 64);
  const viewportSize = numberProp(node.props.viewportSize, env.scope, estimate * 8);
  const scrollOffset = numberProp(node.props.scrollOffset, env.scope, 0);
  const drawDistance = numberProp(node.props.overscan ?? node.props.drawDistance, env.scope, estimate * 2);
  let prepared =
    cache?.items === allItems && cache.estimate === estimate ? cache.prepared : null;
  if (!prepared) {
    const keys = allItems.map((item, index) => String(keyFor(item, index)));
    prepared = prepareVirtualList({
      count: allItems.length,
      estimatedItemSize: estimate,
      getKey: (index) => keys[index] ?? String(index),
    });
    setCache({ items: allItems, estimate, prepared });
  }
  const output = computeVirtualItemsFromPrepared(prepared, {
    scrollOffset,
    viewportSize,
    drawDistance,
  });
  return {
    totalSize: output.totalSize,
    items: output.items.map((frame) => ({
      item: allItems[frame.index],
      index: frame.index,
      key: frame.key,
      frame,
    })),
    diagnostics: output.diagnostics,
  };
}

function numberProp(expr: Expr | undefined, scope: Scope, fallback: number): number {
  if (!expr) {
    return fallback;
  }
  const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

function collectionRowProps(key: unknown, index: number, frame: VirtualListItem | null): Record<string, unknown> {
  const props: Record<string, unknown> = {
    rowKey: String(key),
    rowIndex: index,
  };
  if (frame) {
    props.style = {
      position: 'absolute',
      top: frame.start,
      left: 0,
      right: 0,
      height: frame.size,
    };
  }
  return props;
}

function isLiteral(expr: Expr): boolean {
  return (
    expr.kind === 'string' ||
    expr.kind === 'number' ||
    expr.kind === 'boolean' ||
    expr.kind === 'null'
  );
}

function makeHandler(
  handlerExpr: Expr,
  scope: Scope,
  locus?: ContractErrorLocus,
): (...args: unknown[]) => void {
  return (...args: unknown[]) => {
    try {
      if (handlerExpr.kind === 'call') {
        // press=remove(item.id): evaluate the call at event time (args bound
        // from the view scope); the event payload is not forwarded.
        untrack(() => evalRuntimeExpr(handlerExpr, scope));
        return;
      }
      const handler = untrack(() => evalRuntimeExpr(handlerExpr, scope));
      if (typeof handler === 'function') {
        handler(...args);
      }
    } catch (error) {
      // ENG-22443: the event dispatch boundary is where a sync action error
      // leaves the runtime (nothing above will catch it) — report it with
      // its authored locus (deduped), then stay loud.
      if (locus) {
        decorateContractError(error, locus);
      }
      reportContractRuntimeError(error);
      throw error;
    }
  };
}

function mountText(
  node: Extract<ViewNodeIR, { kind: 'text' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const { scope } = env;
  const expr = node.expr;
  const textNode = createTextInstance('');
  const structuralId = env.ids.get(node);
  const hydrationNodeId = structuralId && env.ctx.hydration?.capture
    ? hydrationNodeIdFor(env, structuralId)
    : undefined;
  if (structuralId && hydrationNodeId && env.ctx.hydration?.capture) {
    attachContractHydrationTextId(textNode, hydrationNodeId);
    env.ctx.hydration.capture.recordNode({
      host: textNode,
      nodeId: hydrationNodeId,
      structuralId,
      sourcePath: env.component.file.sourcePath,
      sourceVersion: env.component.file.sourceVersion,
      componentName: env.component.name,
      kind: 'text',
    });
  }
  attachTextProvenance(textNode, expr, scope, env, node.span?.line);
  if (isContractDevMode()) {
    if (structuralId) {
      const unregister = registerLiveNode({
        structuralId,
        sourcePath: env.component.file.sourcePath,
        sourceVersion: env.component.file.sourceVersion,
        keyChain: env.keyChain,
        host: textNode,
        patch: {
          kind: 'text',
          setText(value) {
            updateTextContent(textNode, value);
          },
        },
      });
      getOwner()?.register(unregister);
    }
  }
  insertNode(parent, textNode, anchor());

  // Registered BEFORE the binding evaluates: if the first evaluation throws,
  // the owner's disposal still removes the inserted node instead of leaking
  // an empty text into the committed tree (keep-last-good, ENG-22443).
  let disposed = false;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    removeChild(parent, textNode);
  };
  getOwner()?.register(dispose);

  if (isLiteral(expr)) {
    const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
    updateTextContent(textNode, value == null ? '' : String(value));
  } else {
    const textLocus = viewNodeLocus(env, node, 'text binding');
    ownedEffect(() =>
      runWithContractErrorLocus(textLocus, () => {
        const value = evalRuntimeExpr(expr, scope, VIEW_EVAL);
        updateTextContent(textNode, value == null ? '' : String(value));
      }),
    );
  }

  return { hostNodes: () => (disposed ? [] : [textNode]), dispose };
}

function mountHole(
  node: Extract<ViewNodeIR, { kind: 'hole' }>,
  parent: HostParent,
  anchor: AnchorFn,
): Mounted {
  const element = createInstance('View', {
    accessibilityRole: 'none',
    dataHole: true,
    label: node.label ?? 'Contract hole',
  });
  insertNode(parent, element, anchor());

  let disposed = false;
  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    removeChild(parent, element);
  };
  getOwner()?.register(dispose);
  return { hostNodes: () => (disposed ? [] : [element]), dispose };
}

function mountNothing(): Mounted {
  return { hostNodes: () => [], dispose: () => {} };
}

// ---------------------------------------------------------------------------
// Regions: when / each / resource / boundary
// ---------------------------------------------------------------------------

function mountWhen(
  node: Extract<ViewNodeIR, { kind: 'when' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let current: { mounted: Mounted; owner: Owner } | null = null;
  let lastBranch: 'then' | 'else' | 'none' | 'initial' = 'initial';
  let disposed = false;

  const swap = (branch: 'then' | 'else' | 'none'): void => {
    if (branch === lastBranch || disposed) {
      return;
    }
    const previousBranch = lastBranch;
    lastBranch = branch;
    const nodes = branch === 'then' ? node.then : branch === 'else' ? node.else ?? [] : [];
    if (nodes.length === 0) {
      current?.owner.dispose();
      current = null;
      return;
    }
    // Keep-last-good (ENG-22443): mount the incoming branch BEFORE disposing
    // the current one. If mounting throws, the partial mount is disposed and
    // the committed branch stays on screen — the error surfaces through the
    // overlay/console instead of a blanked region. Both branches coexist
    // only inside this flush (one commit per flush closes the batch).
    const owner = createOwner();
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountViewNodes(nodes, parent, anchor, env));
    } catch (error) {
      owner.dispose();
      lastBranch = previousBranch;
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner };
  };

  const whenLocus = viewNodeLocus(env, node, 'when');
  ownedEffect(() =>
    runWithContractErrorLocus(whenLocus, () => {
      const test = !!evalRuntimeExpr(node.test, env.scope, VIEW_EVAL);
      untrack(() => swap(test ? 'then' : node.else ? 'else' : 'none'));
    }),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => (current ? current.mounted.hostNodes() : []),
    dispose,
  };
}

function contractMatchEquals(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) {
    return true;
  }
  if (
    (typeof a === 'string' || typeof a === 'number' || typeof a === 'boolean') &&
    (typeof b === 'string' || typeof b === 'number' || typeof b === 'boolean')
  ) {
    return String(a) === String(b);
  }
  return false;
}

function mountMatch(
  node: Extract<ViewNodeIR, { kind: 'match' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let current: { mounted: Mounted; owner: Owner } | null = null;
  let lastBranch = '__initial__';
  let disposed = false;

  const swap = (branch: string, nodes: ViewNodeIR[]): void => {
    if (branch === lastBranch || disposed) {
      return;
    }
    const previousBranch = lastBranch;
    lastBranch = branch;
    if (nodes.length === 0) {
      current?.owner.dispose();
      current = null;
      return;
    }
    // Keep-last-good (ENG-22443): mount before disposing; see mountWhen.
    const owner = createOwner();
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountViewNodes(nodes, parent, anchor, env));
    } catch (error) {
      owner.dispose();
      lastBranch = previousBranch;
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner };
  };

  const matchLocus = viewNodeLocus(env, node, 'match');
  ownedEffect(() =>
    runWithContractErrorLocus(matchLocus, () => {
      const subject = evalRuntimeExpr(node.expr, env.scope, VIEW_EVAL);
      const armIndex = node.cases.findIndex((candidate) =>
        contractMatchEquals(subject, evalRuntimeExpr(candidate.test, env.scope, VIEW_EVAL))
      );
      const arm = armIndex >= 0 ? node.cases[armIndex] : undefined;
      const nodes = arm?.body ?? node.else ?? [];
      untrack(() => swap(arm ? `case:${armIndex}` : 'else', nodes));
    }),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => (current ? current.mounted.hostNodes() : []),
    dispose,
  };
}

function mountMatchSize(
  node: Extract<ViewNodeIR, { kind: 'match-size' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let current: { mounted: Mounted; owner: Owner } | null = null;
  let lastBranch = '__initial__';
  let disposed = false;

  const swap = (branch: string, nodes: ViewNodeIR[]): void => {
    if (branch === lastBranch || disposed) {
      return;
    }
    const previousBranch = lastBranch;
    lastBranch = branch;
    if (nodes.length === 0) {
      current?.owner.dispose();
      current = null;
      return;
    }
    // Keep-last-good (ENG-22443): mount before disposing; see mountWhen.
    const owner = createOwner();
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountViewNodes(nodes, parent, anchor, env));
    } catch (error) {
      owner.dispose();
      lastBranch = previousBranch;
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner };
  };

  ownedEffect(() => {
    const sizeClass = readContractSizeClass();
    const arm = node.cases.find((candidate) => candidate.value === sizeClass);
    const nodes = arm?.body ?? node.else ?? [];
    untrack(() => swap(arm ? arm.value : 'else', nodes));
  });

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => (current ? current.mounted.hostNodes() : []),
    dispose,
  };
}

interface EachRow {
  key: unknown;
  setItem: (value: unknown) => void;
  setIndex: (value: number) => void;
  mounted: Mounted;
  owner: Owner;
}

function mountEach(
  node: Extract<ViewNodeIR, { kind: 'each' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let rows: EachRow[] = [];
  let disposed = false;
  let warnedDuplicateKeys = false;

  const createRow = (item: unknown, index: number, key: unknown): EachRow => {
    const owner = createOwner();
    // Each row gets its own anchor: the first host node of the NEXT row at
    // resolution time, else the region anchor. This keeps regions (`when`,
    // nested `each`) in trailing position of a row body anchored inside
    // their own row instead of drifting to the region tail when they remount
    // later. During initial creation the row is not in `rows` yet, so this
    // resolves to the region anchor and the reorder pass below fixes order
    // within the same flush.
    const self: { row: EachRow | null } = { row: null };
    const rowAnchor: AnchorFn = () => {
      const index = self.row ? rows.indexOf(self.row) : -1;
      if (index >= 0) {
        for (let i = index + 1; i < rows.length; i += 1) {
          const nodesAfter = rows[i].mounted.hostNodes();
          if (nodesAfter.length > 0) {
            return nodesAfter[0];
          }
        }
      }
      return anchor();
    };
    let row: EachRow;
    try {
      row = runWithOwner(owner, () => {
        // Item/index are signals so in-place updates flow without remounting.
        const itemSignal = signal<unknown>(item);
        const indexSignal = signal<number>(index);
        const rowScope = env.scope.child();
        rowScope.define(node.item, { kind: 'getter', get: () => itemSignal.get() });
        if (node.index) {
          rowScope.define(node.index, { kind: 'getter', get: () => indexSignal.get() });
        }
        const mounted = mountViewNodes(node.body, parent, rowAnchor, {
          ...env,
          scope: rowScope,
          isRootView: false,
          keyChain: `${env.keyChain}#${String(key)}`,
          hydrationKeyChain: `${env.hydrationKeyChain}#${String(key)}`,
        });
        return {
          key,
          setItem: (value: unknown) => itemSignal.set(value),
          setIndex: (value: number) => indexSignal.set(value),
          mounted,
          owner,
        };
      });
    } catch (error) {
      // Keep-last-good (ENG-22443): a row that dies mid-mount disposes its
      // own partial host nodes before the error unwinds.
      owner.dispose();
      throw error;
    }
    self.row = row;
    return row;
  };

  const eachLocus = viewNodeLocus(env, node, 'each');
  ownedEffect(() =>
    runWithContractErrorLocus(eachLocus, () => {
    const list = evalRuntimeExpr(node.iterable, env.scope, VIEW_EVAL);
    const items = Array.isArray(list) ? list : [];

    untrack(() => {
      if (disposed) {
        return;
      }

      // Queue per key (ENG-23170): duplicate keys are tolerated, so rows
      // sharing a key must all round-trip through the diff — a plain
      // Map<key, row> silently drops every duplicate but the last, leaking
      // undisposed rows with live effects and attached host nodes.
      const oldByKey = new Map<unknown, EachRow[]>();
      const oldKeyOrder: unknown[] = [];
      for (const row of rows) {
        const queue = oldByKey.get(row.key);
        if (queue) {
          queue.push(row);
        } else {
          oldByKey.set(row.key, [row]);
        }
        oldKeyOrder.push(row.key);
      }

      const nextRows: EachRow[] = [];
      const createdRows: EachRow[] = [];
      const seen = new Set<unknown>();
      let createdAny = false;

      try {
        items.forEach((item, index) => {
          const keyScope = env.scope.child();
          keyScope.defineValue(node.item, item);
          if (node.index) {
            keyScope.defineValue(node.index, index);
          }
          const key = evalRuntimeExpr(node.key, keyScope, VIEW_EVAL);
          if (seen.has(key) && !warnedDuplicateKeys) {
            warnedDuplicateKeys = true;
            console.warn(`[contract] duplicate each key ${String(key)}; rows need unique keys`);
          }
          seen.add(key);

          const queue = oldByKey.get(key);
          const existing = queue?.shift();
          if (existing) {
            if (queue!.length === 0) {
              oldByKey.delete(key);
            }
            existing.setItem(item);
            existing.setIndex(index);
            nextRows.push(existing);
          } else {
            createdAny = true;
            const created = createRow(item, index, key);
            createdRows.push(created);
            nextRows.push(created);
          }
        });
      } catch (error) {
        // Keep-last-good (ENG-22443): a row that fails to mount must not
        // take down the region — dispose the rows created this pass (which
        // removes their partial host nodes) and keep the existing rows.
        for (const created of createdRows) {
          created.owner.dispose();
        }
        throw error;
      }

      for (const queue of oldByKey.values()) {
        for (const removed of queue) {
          removed.owner.dispose();
        }
      }

      rows = nextRows;

      // Reorder pass: needed when rows were created (they appended at the
      // region tail) or surviving order changed. Walk back-to-front moving
      // each row in front of its successor; insertBefore moves natively.
      // Rows already in position are O(1) no-ops inside host-ops
      // insertBefore/appendChild (ENG-23198), so a pure append costs O(n)
      // position checks instead of n re-inserts + n subtree prop re-encodes.
      const oldSurviving = oldKeyOrder.filter((key) => seen.has(key));
      const oldSurvivingSet = new Set(oldSurviving);
      const newSurviving = rows.map((row) => row.key).filter((key) => oldSurvivingSet.has(key));
      const orderChanged =
        oldSurviving.length !== newSurviving.length ||
        oldSurviving.some((key, index) => key !== newSurviving[index]);

      if (createdAny || orderChanged) {
        let nextAnchor: HostNode | null = anchor();
        for (let i = rows.length - 1; i >= 0; i -= 1) {
          const nodes = rows[i].mounted.hostNodes();
          for (let n = nodes.length - 1; n >= 0; n -= 1) {
            const hostNode = nodes[n];
            if (nextAnchor) {
              insertBefore(parent, hostNode, nextAnchor);
            } else {
              appendChild(parent, hostNode);
            }
            nextAnchor = hostNode;
          }
        }
      }
    });
    }),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    for (const row of rows) {
      row.owner.dispose();
    }
    rows = [];
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => rows.flatMap((row) => row.mounted.hostNodes()),
    dispose,
  };
}

interface ResourceHandle {
  status: 'pending' | 'ready' | 'error' | 'refreshing';
  pending?: boolean;
  loading?: boolean;
  ready?: boolean;
  error: unknown;
  value: unknown;
  /** LLP 0284 §2.2 connection axis; absent for non-provider-backed bindings. */
  connection?: DataConnection;
  refresh?: () => void;
}

function isResourceHandle(value: unknown): value is ResourceHandle {
  return typeof value === 'object' && value !== null && 'status' in value && 'value' in value && 'error' in value;
}

function isEmptyResourceValue(value: unknown): boolean {
  if (value == null) {
    return true;
  }
  if (typeof value === 'object' || typeof value === 'string') {
    const length = (value as { length?: unknown }).length;
    return typeof length === 'number' && length === 0;
  }
  return false;
}

function mountResourceRegion(
  node: Extract<ViewNodeIR, { kind: 'resource' | 'async' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let current: { mounted: Mounted; owner: Owner; key: string; setPayload?: (value: unknown) => void } | null = null;
  let disposed = false;

  const slotFor = (handle: ResourceHandle) => {
    if (handle.status === 'pending') {
      return node.slots.find((slot) => slot.kind === 'loading') ?? null;
    }
    if (handle.status === 'error') {
      return node.slots.find((slot) => slot.kind === 'error') ?? null;
    }
    if (handle.status === 'ready' || handle.status === 'refreshing') {
      // LLP 0284 §2.2 dispatch order: within status 'ready', connection arms
      // match before data-shape refinements — stale → empty → ready. "The
      // data may be out of date" dominates "the out-of-date data happens to
      // be empty"; without an authored stale arm the region behaves exactly
      // as before.
      if (handle.connection === 'stale' || handle.connection === 'disconnected') {
        const staleSlot = node.slots.find((slot) => slot.kind === 'stale');
        if (staleSlot) {
          return staleSlot;
        }
      }
      const empty = isEmptyResourceValue(handle.value);
      if (empty) {
        return node.slots.find((slot) => slot.kind === 'empty') ?? node.slots.find((slot) => slot.kind === 'ready') ?? null;
      }
      return node.slots.find((slot) => slot.kind === 'ready') ?? null;
    }
    return null;
  };

  const swap = (handle: ResourceHandle): void => {
    const slot = slotFor(handle);
    const key = slot ? `${slot.kind}:${slot.binding ?? ''}` : 'none';
    const payload = slot?.kind === 'error' ? handle.error : handle.value;
    if (disposed) {
      return;
    }
    if (current?.key === key) {
      current.setPayload?.(payload);
      return;
    }
    if (!slot) {
      current?.owner.dispose();
      current = null;
      return;
    }
    // Keep-last-good (ENG-22443): mount before disposing; see mountWhen.
    const owner = createOwner();
    const slotScope = env.scope.child();
    let setPayload: ((value: unknown) => void) | undefined;
    if (slot.binding) {
      const payloadSignal = signal<unknown>(payload);
      setPayload = (value: unknown) => payloadSignal.set(value);
      slotScope.define(slot.binding, { kind: 'getter', get: () => payloadSignal.get() });
    }
    let mounted: Mounted;
    try {
      mounted = runWithOwner(owner, () => mountViewNodes(slot.body, parent, anchor, {
        ...env,
        scope: slotScope,
      }));
    } catch (error) {
      owner.dispose();
      throw error;
    }
    current?.owner.dispose();
    current = { mounted, owner, key, setPayload };
  };

  const regionLocus = viewNodeLocus(env, node, `${node.kind} region "${node.name}"`);
  ownedEffect(() =>
    runWithContractErrorLocus(regionLocus, () => {
      const binding = env.scope.lookup(node.name);
      const value = binding
        ? binding.kind === 'value' || binding.kind === 'local'
          ? binding.value
          : binding.get()
        : undefined;
      if (!isResourceHandle(value)) {
        throw new Error(`[contract] ${node.kind} region "${node.name}" did not resolve to an async resource/query handle`);
      }
      // Track the active branch and the payload for its optional binding.
      void value.status;
      void value.error;
      void value.value;
      void value.connection;
      untrack(() => swap(value));
    }),
  );

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => (current ? current.mounted.hostNodes() : []),
    dispose,
  };
}

function mountBoundary(
  node: Extract<ViewNodeIR, { kind: 'boundary' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  let current: { mounted: Mounted; owner: Owner } | null = null;
  let disposed = false;

  const mountFallback = (thrown: unknown): void => {
    if (disposed) {
      return;
    }
    console.warn('[contract] boundary caught render error; rendering fallback', thrown);
    const owner = createOwner();
    const fallbackScope = env.scope.child();
    if (node.fallback.binding) {
      fallbackScope.defineLocal(node.fallback.binding, thrown);
    }
    const mounted = runWithOwner(owner, () => mountViewNodes(node.fallback.body, parent, anchor, {
      ...env,
      scope: fallbackScope,
    }));
    current = { mounted, owner };
  };

  const owner = createOwner();
  try {
    const mounted = runWithOwner(owner, () => mountViewNodes(node.body, parent, anchor, env));
    current = { mounted, owner };
  } catch (thrown) {
    owner.dispose();
    mountFallback(thrown);
  }

  const dispose = (): void => {
    if (disposed) {
      return;
    }
    disposed = true;
    current?.owner.dispose();
    current = null;
  };
  getOwner()?.register(dispose);

  return {
    hostNodes: () => (current ? current.mounted.hostNodes() : []),
    dispose,
  };
}

// ---------------------------------------------------------------------------
// Components
// ---------------------------------------------------------------------------

function mountComponent(
  node: Extract<ViewNodeIR, { kind: 'component' }>,
  parent: HostParent,
  anchor: AnchorFn,
  env: MountEnv,
): Mounted {
  const resolved = untrack(() => {
    const binding = env.scope.lookup(node.name);
    if (!binding) {
      return undefined;
    }
    return binding.kind === 'value' || binding.kind === 'local' ? binding.value : binding.get();
  });

  if (!isCompiledComponentValue(resolved)) {
    throw new Error(`[contract] "${node.name}" did not resolve to a Contract component`);
  }

  // Props are reactive getters into the caller's scope; events are callback
  // props (functions) under their event names. forEach: the getter closure
  // escapes the iteration (see the Hermes for-of note in instance.ts).
  // Action-typed props (LLP 0280 §2.3) take the event wiring regardless of
  // their name, so a curried application (`confirm=save(item.id)`) is a
  // deferred thunk rather than an eager getter evaluation.
  const actionTypedPropNames = new Set(
    resolved.ir.props
      .filter((prop) => prop.parsedType?.ir.kind === 'action')
      .map((prop) => prop.name),
  );
  const props: Record<string, PropValue> = {};
  Object.entries(node.props).forEach(([name, expr]) => {
    if (actionTypedPropNames.has(name)) {
      props[name] = {
        kind: 'value',
        value: makeHandler(expr, env.scope, viewNodeLocus(env, node, `action prop "${name}"`)),
      };
    } else if (isLiteral(expr)) {
      props[name] = { kind: 'value', value: evalRuntimeExpr(expr, env.scope, VIEW_EVAL) };
    } else {
      const propLocus = viewNodeLocus(env, node, `prop "${name}"`);
      props[name] = {
        kind: 'getter',
        get: () =>
          runWithContractErrorLocus(propLocus, () =>
            evalRuntimeExpr(expr, env.scope, VIEW_EVAL),
          ),
      };
    }
  });
  Object.entries(node.events).forEach(([event, handlerExpr]) => {
    props[event] = {
      kind: 'value',
      value: makeHandler(handlerExpr, env.scope, viewNodeLocus(env, node, `event "${event}"`)),
    };
  });

  const callStructuralId = env.ids.get(node);
  const callHydrationNodeId = callStructuralId && env.ctx.hydration?.capture
    ? hydrationNodeIdFor(env, callStructuralId)
    : undefined;
  const childInstance = instantiateComponent(resolved, props, env.ctx, {
    hydrationNodeId: callHydrationNodeId ?? `${env.hydrationPrefix}${resolved.ir.name}/v`,
    hydrationStructuralId: callStructuralId,
    hydrationKeyChain: env.hydrationKeyChain,
  });

  // Caller children mount wherever the child's view places its `children`
  // slot, with the caller's scope (closure semantics).
  const childrenSlot: ChildrenSlot | null =
    node.children.length > 0
      ? (slotParent, slotAnchor) =>
          mountViewNodes(node.children, slotParent, slotAnchor, {
            ...env,
            isRootView: false,
          })
      : null;

  const mounted = runWithOwner(childInstance.owner, () =>
    mountViewNodes([resolved.ir.view], parent, anchor, {
      scope: childInstance.scope,
      component: resolved,
      ctx: env.ctx,
      childrenSlot,
      isRootView: env.isRootView,
      ids: structuralIdsFor(resolved.ir),
      keyChain: env.keyChain,
      hydrationPrefix: callHydrationNodeId
        ? `${callHydrationNodeId}>`
        : env.hydrationPrefix,
      hydrationKeyChain: '',
    }),
  );

  // Design Mode D0 (LLP 0158): mark the component call boundary on the
  // component's root host node (selection targets this, §7.1).
  if (isContractDevMode()) {
    // On-demand clause witnessing for the exact_contract_witness agent op
    // (LLP 0293 ledger row 8): dev-only, no-op for components without a
    // `contract` block. Inside the dev gate so production list mounts pay
    // no per-instance closure or registry work.
    registerContractClauseWitnessInstance(childInstance, () => mounted.hostNodes());
    const rootHost = mounted.hostNodes()[0];
    if (rootHost) {
      const propOrigins: Record<string, AttrOrigin> = {};
      for (const [name, expr] of Object.entries(node.props)) {
        const origin = classifyExpr(expr, env.scope, name);
        const rawSource = node.propSources?.[name];
        if (origin.kind === 'literal' && typeof rawSource === 'string') {
          origin.rawSource = rawSource;
        }
        propOrigins[name] = origin;
      }
      attachComponentBoundary(rootHost, {
        componentName: node.name,
        callSourcePath: env.component.file.sourcePath,
        callLine: node.span.line,
        definitionSourcePath: resolved.file.sourcePath,
        props: propOrigins,
      });
    }
  }

  return mounted;
}
