// @system @ref LLP 0199 S0-S1 — layout-intent relationships.
//
// Relation expressions preserve designer intent in the IR. The v0 runtime
// resolves only pure Taffy/flex relationships; measured-sibling relationships
// remain stored intent until LLP 0195 S2 provides the feedback channel.

import type { LayoutRelationOp } from '../compiler/ir.js';

const RELATION_MARKER = '__exactContractRelation';

export interface ContractRelationValue {
  readonly [RELATION_MARKER]: true;
  readonly op: LayoutRelationOp;
  readonly args: readonly unknown[];
  readonly fallback?: unknown;
}

export function createContractRelation(
  op: LayoutRelationOp,
  args: readonly unknown[],
  fallback?: unknown,
): ContractRelationValue {
  return Object.freeze({
    [RELATION_MARKER]: true,
    op,
    args: [...args],
    fallback,
  });
}

export function isContractRelationValue(value: unknown): value is ContractRelationValue {
  return (
    value !== null &&
    typeof value === 'object' &&
    (value as Record<string, unknown>)[RELATION_MARKER] === true
  );
}

export function applyStyleObject(
  style: Record<string, unknown>,
  value: unknown,
): void {
  if (value === null || typeof value !== 'object') {
    return;
  }
  Object.entries(value as Record<string, unknown>).forEach(([key, entry]) => {
    applyStyleValue(style, key, entry);
  });
}

export function applyStyleValue(
  style: Record<string, unknown>,
  styleProp: string,
  value: unknown,
): void {
  // Attr-level sugar (e.g. the `grid cols=3` numeric expansion) does NOT
  // live here: this is the generic style plumbing every writer shares,
  // including the `style=` escape hatch. Lowered-attr transforms are
  // declared in the builtin-schema lowering layer
  // (CONTRACT_LOWERED_STYLE_VALUE_TRANSFORMS) and applied by the attr
  // paths before this call (ENG-22563).
  if (!isContractRelationValue(value)) {
    style[styleProp] = value;
    return;
  }

  const patch = resolveRelationStyle(styleProp, value);
  if (patch) {
    Object.assign(style, patch);
    return;
  }
  if (value.fallback !== undefined) {
    style[styleProp] = value.fallback;
  }
}

function resolveRelationStyle(
  styleProp: string,
  relation: ContractRelationValue,
): Record<string, unknown> | null {
  switch (relation.op) {
    case 'fill':
      return {
        flexGrow: 1,
        flexShrink: 1,
        flexBasis: 0,
      };
    case 'ratio': {
      const ratio = resolveRatio(relation.args);
      return ratio === null ? null : { aspectRatio: ratio };
    }
    case 'center':
      return isCenterableStyleProp(styleProp) ? { [styleProp]: 'center' } : null;
    case 'pinToSafeArea':
    case 'matchWidth':
    case 'matchHeight':
    case 'alignTo':
      return null;
  }
}

function resolveRatio(args: readonly unknown[]): number | null {
  if (args.length === 1 && typeof args[0] === 'number' && Number.isFinite(args[0]) && args[0] > 0) {
    return args[0];
  }
  if (
    args.length === 2 &&
    typeof args[0] === 'number' &&
    typeof args[1] === 'number' &&
    Number.isFinite(args[0]) &&
    Number.isFinite(args[1]) &&
    args[0] > 0 &&
    args[1] > 0
  ) {
    return args[0] / args[1];
  }
  return null;
}

function isCenterableStyleProp(styleProp: string): boolean {
  return (
    styleProp === 'alignItems' ||
    styleProp === 'alignSelf' ||
    styleProp === 'justifyContent' ||
    styleProp === 'alignContent' ||
    styleProp === 'textAlign'
  );
}
