// @system @ref LLP 0081 — compiled-component handle: IR + resolved links.
//
// The Vite plugin emits `defineComponent(fileIR, links)` per .contract
// module; `links` maps each `use Name from "spec"` to the imported value
// (another compiled component, a capability, a behavior factory, a store,
// or a plain helper — LLP 0087's import classes).

import type { ComponentIR, ContractFileIR } from '../compiler/ir.js';
import { registerComponentDesignMeta } from './design-meta.js';
import { registerContractModule } from './hot-patch.js';

export interface ComponentLinks {
  [importName: string]: unknown;
}

export interface CompiledComponent {
  readonly kind: 'contract-component';
  readonly name: string;
  readonly ir: ComponentIR;
  readonly file: ContractFileIR;
  readonly links: ComponentLinks;
  /** In-file components (public + private), resolvable from view nodes. */
  readonly fileComponents: ReadonlyMap<string, CompiledComponent>;
}

export function isCompiledComponent(value: unknown): value is CompiledComponent {
  return (
    typeof value === 'object' &&
    value !== null &&
    (value as { kind?: unknown }).kind === 'contract-component'
  );
}

/**
 * Builds compiled-component handles for a file. Returns the public component
 * (first declared); private components are reachable through
 * `fileComponents` and by name via `getFileComponent`.
 */
export function defineComponent(
  file: ContractFileIR,
  links: ComponentLinks = {},
): CompiledComponent {
  // IR-of-record + hot-patch global (LLP 0166 §4.8) — dev only, no-op in prod.
  registerContractModule(file);
  const fileComponents = new Map<string, CompiledComponent>();

  for (const componentIR of file.components) {
    fileComponents.set(componentIR.name, {
      kind: 'contract-component',
      name: componentIR.name,
      ir: componentIR,
      file,
      links,
      fileComponents,
    });
    // Design Mode metadata (LLP 0163 §5.3a) — dev-only, no-op in prod.
    registerComponentDesignMeta(componentIR, file.sourcePath);
  }

  const publicComponent = fileComponents.get(file.components[0].name);
  if (!publicComponent) {
    throw new Error('[contract] defineComponent: file has no components');
  }
  return publicComponent;
}

export function getFileComponent(
  component: CompiledComponent,
  name: string,
): CompiledComponent | undefined {
  return component.fileComponents.get(name);
}
