// @system @ref LLP 0166 §4.8 — policy-driven hot patching.
//
// The Vite plugin's HMR handler used to be unconditional invalidate(); now
// it asks this module first. The pipeline, exactly as specified:
//   1. ACCEPT the new module: the IR-of-record and provenance registrations
//      advance to the new sourceVersion — only the remount is conditionally
//      skipped. (Without this, the second consecutive edit would diff
//      against a stale IR and serve dead spans.)
//   2. Diff old<->new IR keyed by structural id, classifying every change
//      as a slot change or a structural change.
//   3. Patch in place iff every change lands on a slot whose hotPatch
//      policy is not 'reset' and there are no structural changes: locate
//      live nodes via the identity registry, apply through the host-ops
//      update path as one atomic batch per root, refresh provenance.
//   4. Otherwise return false -> invalidate() exactly as today. When in
//      doubt, reset.
//
// Because this rides the ordinary HMR path, a HAND edit in a code editor
// that changes only patchable slots also hot-patches — the substrate
// serves the human loop, not just the panel.

import { transformLoweredStyleValue } from '../compiler/builtin-schema.js';
import { applyStyleValue } from './layout-intent.js';
import type {
  BehaviorTemplateIR,
  ContractFileIR,
  ContractWitness,
  Expr,
} from '../compiler/ir.js';
import { collectSlotSites, type SlotSiteIR } from '../compiler/slots.js';
import { walkStructuralPaths } from '../compiler/identity.js';
import { bumpBehaviorDeriveRevisions } from './behavior-hmr.js';
import { getLiveNodes } from './identity-registry.js';
import { getNodeProvenance, isContractDevMode } from './provenance.js';
import { getContractTokenResolver } from './tokens.js';
import { commitMountedRoots } from './mount.js';

const irOfRecord = new Map<string, ContractFileIR>();
let handleInstalled = false;
let lastRefreshDecision: ContractRefreshDecision | null = null;

export type ContractRefreshMode = 'slot-patch' | 'state-preserving-refresh';
export type ContractRefreshResetReason =
  | 'dev_mode_disabled'
  | 'missing_source_path'
  | 'missing_previous_module'
  | 'same_source_version'
  | 'component_count_changed'
  | 'component_identity_changed'
  | 'state_slots_changed'
  | 'derive_formula_changed'
  | 'structural_incompatible'
  | 'unpatchable_slot'
  | 'unresolvable_value'
  // Behavior template compatibility (LLP 0280 §2.1, extending the
  // llp/contract/0086 named-state model): action/derive BODY edits, state
  // initials, and carried contract edits preserve state; everything below
  // resets — with the slot-level cause named — at EVERY instantiation site
  // (same-file v1 makes the transitive rule hold by construction: one
  // module-level decision covers all sites). v1 reset granularity is the
  // module (the existing invalidate path); the reason code is slot-level.
  | 'behavior_identity_changed'
  | 'behavior_slot_added'
  | 'behavior_slot_removed'
  | 'behavior_slot_type_changed'
  | 'behavior_derive_changed'
  | 'behavior_action_signature_changed'
  | 'behavior_task_changed'
  | 'behavior_expose_changed';

export type ContractRefreshDecision =
  | {
      applied: true;
      mode: ContractRefreshMode;
      preservedStateSlots: string[];
    }
  | {
      applied: false;
      reason: ContractRefreshResetReason;
    };

export interface ContractWitnessModuleRecord {
  sourcePath: string;
  witness?: ContractWitness;
}

export interface ContractWitnessRuntimeHandle {
  listModules(): ContractWitnessModuleRecord[];
  getModule(sourcePath: string): ContractFileIR | undefined;
  getWitness(sourcePath: string): ContractWitness | undefined;
}

/**
 * Records a module's live IR. First registration wins: on HMR the NEW
 * module evaluates (and calls this) BEFORE the accept callback runs the
 * differ, and the old record must survive until the patch advances it.
 */
export function registerContractModule(file: ContractFileIR): void {
  if (!isContractDevMode() || !file.sourcePath) {
    return;
  }
  ensureGlobalHandle();
  if (!irOfRecord.has(file.sourcePath)) {
    irOfRecord.set(file.sourcePath, file);
  }
}

function rejectRefresh(reason: ContractRefreshResetReason): false {
  lastRefreshDecision = { applied: false, reason };
  return false;
}

function acceptRefresh(
  mode: ContractRefreshMode,
  preservedStateSlots: string[] = [],
): true {
  lastRefreshDecision = { applied: true, mode, preservedStateSlots };
  return true;
}

export function getLastContractRefreshDecision(): ContractRefreshDecision | null {
  return lastRefreshDecision;
}

function ensureGlobalHandle(): void {
  if (handleInstalled) {
    return;
  }
  handleInstalled = true;
  (globalThis as Record<string, unknown>).__exactContractHotPatch = applyContractHotPatch;
  (globalThis as Record<string, unknown>).__exactContractWitness = {
    listModules: listContractWitnessModules,
    getModule: getContractModuleRecord,
    getWitness: getContractWitness,
  } satisfies ContractWitnessRuntimeHandle;
}

/** Structure compare: both IRs with every slot value blanked, spans and
    derived text anchors stripped. Identical -> only slot values changed. */
function structurallyIdentical(oldFile: ContractFileIR, newFile: ContractFileIR): boolean {
  return normalizedStructure(oldFile) === normalizedStructure(newFile);
}

function normalizedStructure(file: ContractFileIR): string {
  const clone = JSON.parse(JSON.stringify(file, stripVolatile)) as ContractFileIR;
  clone.components.forEach((component) => {
    collectSlotSites(component).forEach((site) => {
      blankExpr(site.value);
    });
  });
  return JSON.stringify(clone);
}

function stripVolatile(key: string, value: unknown): unknown {
  return key === 'span' ||
    key === 'exposeSpan' ||
    key === 'propSources' ||
    key === 'sourceVersion' ||
    key === 'witness'
    ? undefined
    : value;
}

function blankExpr(expr: Expr): void {
  Object.keys(expr).forEach((key) => {
    delete (expr as unknown as Record<string, unknown>)[key];
  });
  (expr as unknown as Record<string, unknown>).kind = 'null';
}

function valueJson(expr: Expr): string {
  return JSON.stringify(expr, (key, value: unknown) => (key === 'span' ? undefined : value));
}

/** Runtime value of a patchable slot expr; `undefined` means "cannot
    evaluate here — reset instead" (null literals resolve to null). */
function evaluatePatchValue(expr: Expr): unknown {
  switch (expr.kind) {
    case 'string':
    case 'number':
    case 'boolean':
      return expr.value;
    case 'null':
      return null;
    case 'unary':
      if (expr.op === '-' && expr.operand.kind === 'number') {
        return -expr.operand.value;
      }
      return undefined;
    case 'token': {
      const resolver = getContractTokenResolver();
      return resolver ? resolver(expr.path) : undefined;
    }
    default:
      return undefined;
  }
}

interface PendingPatch {
  site: SlotSiteIR;
  newValue: unknown;
  newExpr: Expr;
}

/**
 * The HMR decision (§4.8). Returns true when the live tree was patched in
 * place (the caller skips invalidate); false means reset.
 */
export function applyContractHotPatch(newFile: ContractFileIR): boolean {
  if (!isContractDevMode() || !newFile.sourcePath) {
    return rejectRefresh(!isContractDevMode() ? 'dev_mode_disabled' : 'missing_source_path');
  }
  const oldFile = irOfRecord.get(newFile.sourcePath);
  if (!oldFile || oldFile.sourceVersion === newFile.sourceVersion) {
    return rejectRefresh(oldFile ? 'same_source_version' : 'missing_previous_module');
  }
  if (oldFile.components.length !== newFile.components.length) {
    return rejectRefresh('component_count_changed');
  }
  if (!structurallyIdentical(oldFile, newFile)) {
    return applyStatePreservingRefresh(oldFile, newFile);
  }

  // Same structure -> identical slot-site lists; pair by index and verify
  // by slotId.
  const patches: PendingPatch[] = [];
  for (let c = 0; c < oldFile.components.length; c += 1) {
    const oldSites = collectSlotSites(oldFile.components[c]);
    const newSites = collectSlotSites(newFile.components[c]);
    if (oldSites.length !== newSites.length) {
      return rejectRefresh('structural_incompatible');
    }
    for (let i = 0; i < oldSites.length; i += 1) {
      const oldSite = oldSites[i];
      const newSite = newSites[i];
      if (oldSite.slotId !== newSite.slotId) {
        return rejectRefresh('structural_incompatible');
      }
      if (valueJson(oldSite.value) === valueJson(newSite.value)) {
        continue;
      }
      if (oldSite.hotPatch === 'reset') {
        return rejectRefresh('unpatchable_slot');
      }
      const newValue = evaluatePatchValue(newSite.value);
      if (newValue === undefined && newSite.value.kind !== 'null') {
        return rejectRefresh('unresolvable_value');
      }
      patches.push({ site: oldSite, newValue, newExpr: newSite.value });
    }
  }

  // Resolve every live target BEFORE applying anything (atomicity: a slot
  // we cannot map cleanly turns the whole save into a reset, never a
  // half-patched tree).
  const applications: Array<() => void> = [];
  for (const patch of patches) {
    const { site } = patch;
    const entries = site.nodeId ? getLiveNodes(site.nodeId) : [];
    for (const entry of entries) {
      if (site.slot.kind === 'text') {
        if (entry.patch.kind !== 'text') {
          return rejectRefresh('structural_incompatible');
        }
        const setText = entry.patch.setText;
        const text = patch.newValue == null ? '' : String(patch.newValue);
        applications.push(() => {
          setText(text);
        });
      } else if (site.slot.kind === 'attr') {
        if (entry.patch.kind !== 'element') {
          return rejectRefresh('structural_incompatible');
        }
        const target = entry.patch.attrTargets[site.slot.name];
        if (!target) {
          return rejectRefresh('structural_incompatible');
        }
        const applyStatic = entry.patch.applyStatic;
        let mutation: { style?: Record<string, unknown>; props?: Record<string, unknown> };
        if (target.target === 'style') {
          // Route literal edits through the same lowered-attr transform +
          // style-value normalization the mount path uses (the builtin-schema
          // lowering layer owns transforms like the grid cols numeric
          // expansion — ENG-22563) so a slot patch can never write a raw
          // value the host would reject while a remount would accept.
          const styled: Record<string, unknown> = {};
          applyStyleValue(
            styled,
            target.name,
            transformLoweredStyleValue(target.name, patch.newValue),
          );
          mutation = { style: styled };
        } else {
          mutation = { props: { [target.name]: patch.newValue } };
        }
        applications.push(() => {
          applyStatic(mutation);
        });
      } else {
        return rejectRefresh('unpatchable_slot');
      }
      refreshProvenance(entry.host, patch, newFile);
    }
  }

  applications.forEach((apply) => {
    apply();
  });
  commitMountedRoots();

  // Step 1's other half: advance the IR-of-record IN PLACE — the live tree
  // keeps its object identity (mounted closures hold these exprs), but its
  // values, raw anchors, and version now match the new module exactly.
  advanceIrOfRecord(oldFile, newFile, patches);
  return acceptRefresh('slot-patch', preservedStateSlotsForFile(oldFile));
}

function applyStatePreservingRefresh(oldFile: ContractFileIR, newFile: ContractFileIR): boolean {
  if (oldFile.components.length !== newFile.components.length) {
    return rejectRefresh('component_count_changed');
  }
  const behaviorReason = classifyBehaviorTemplateRefresh(
    oldFile.behaviorTemplates ?? [],
    newFile.behaviorTemplates ?? [],
  );
  if (behaviorReason) {
    return rejectRefresh(behaviorReason);
  }
  for (let index = 0; index < oldFile.components.length; index += 1) {
    const oldComponent = oldFile.components[index];
    const newComponent = newFile.components[index];
    if (oldComponent.name !== newComponent.name) {
      return rejectRefresh('component_identity_changed');
    }
    if (!sameNames(oldComponent.states, newComponent.states)) {
      return rejectRefresh('state_slots_changed');
    }
    if (!sameDeriveFormulas(oldComponent.derives, newComponent.derives)) {
      return rejectRefresh('derive_formula_changed');
    }
  }

  if (refreshCompatibleStructure(oldFile) !== refreshCompatibleStructure(newFile)) {
    return rejectRefresh('structural_incompatible');
  }

  for (let index = 0; index < oldFile.components.length; index += 1) {
    const oldComponent = oldFile.components[index];
    const newComponent = newFile.components[index];

    oldComponent.states.forEach((state, stateIndex) => {
      replaceExpr(state.initial, newComponent.states[stateIndex].initial);
    });
    oldComponent.derives.forEach((derive, deriveIndex) => {
      derive.expr = newComponent.derives[deriveIndex].expr;
    });
    oldComponent.actions.forEach((action, actionIndex) => {
      action.body = newComponent.actions[actionIndex].body;
    });
    oldComponent.contracts = newComponent.contracts;
  }

  const behaviorDerivesChanged = spliceBehaviorTemplates(oldFile, newFile);

  oldFile.sourceVersion = newFile.sourceVersion;
  oldFile.witness = newFile.witness;
  if (behaviorDerivesChanged && oldFile.sourcePath) {
    // Live behavior derives re-evaluate their (spliced) formulas in place —
    // this is what makes a derive-body edit state-PRESERVING for behaviors
    // (LLP 0280 §2.1) where component derives still reset above.
    bumpBehaviorDeriveRevisions(oldFile.sourcePath);
  }
  return acceptRefresh('state-preserving-refresh', preservedStateSlotsForFile(oldFile));
}

/**
 * LLP 0280 §2.1 behavior slot-signature compatibility: definition identity
 * (name + params), state slot names/types, derive names, action signatures,
 * task metadata, and the exposed surface must all match for a
 * state-preserving refresh; only bodies/initials/contracts may differ.
 * Returns the reset reason, or null when compatible.
 */
function classifyBehaviorTemplateRefresh(
  oldTemplates: readonly BehaviorTemplateIR[],
  newTemplates: readonly BehaviorTemplateIR[],
): ContractRefreshResetReason | null {
  if (oldTemplates.length !== newTemplates.length) {
    return 'behavior_identity_changed';
  }
  for (let index = 0; index < oldTemplates.length; index += 1) {
    const oldTemplate = oldTemplates[index];
    const newTemplate = newTemplates[index];
    if (
      oldTemplate.name !== newTemplate.name ||
      oldTemplate.params.join(',') !== newTemplate.params.join(',')
    ) {
      return 'behavior_identity_changed';
    }
    const oldStateNames = new Set(oldTemplate.states.map((state) => state.name));
    const newStateNames = new Set(newTemplate.states.map((state) => state.name));
    if (oldTemplate.states.some((state) => !newStateNames.has(state.name))) {
      // A rename is a removal of the old slot: the value cannot be carried.
      return 'behavior_slot_removed';
    }
    if (newTemplate.states.some((state) => !oldStateNames.has(state.name))) {
      return 'behavior_slot_added';
    }
    const oldTypes = new Map(
      oldTemplate.states.map((state) => [state.name, state.parsedType?.raw ?? state.type ?? '']),
    );
    if (
      newTemplate.states.some(
        (state) => (state.parsedType?.raw ?? state.type ?? '') !== oldTypes.get(state.name),
      )
    ) {
      return 'behavior_slot_type_changed';
    }
    if (
      oldTemplate.derives.length !== newTemplate.derives.length ||
      !oldTemplate.derives.every((derive, i) => derive.name === newTemplate.derives[i].name)
    ) {
      return 'behavior_derive_changed';
    }
    if (
      oldTemplate.actions.length !== newTemplate.actions.length ||
      !oldTemplate.actions.every((action, i) => {
        const twin = newTemplate.actions[i];
        return (
          action.name === twin.name &&
          JSON.stringify(action.params) === JSON.stringify(twin.params) &&
          JSON.stringify(action.writes ?? null) === JSON.stringify(twin.writes ?? null) &&
          JSON.stringify(action.mutates ?? null) === JSON.stringify(twin.mutates ?? null)
        );
      })
    ) {
      return 'behavior_action_signature_changed';
    }
    // Tasks may be armed with captured closures (timers, watchers): ANY task
    // change resets, matching the component-level conservatism.
    if (
      JSON.stringify(oldTemplate.tasks, stripVolatile) !==
      JSON.stringify(newTemplate.tasks, stripVolatile)
    ) {
      return 'behavior_task_changed';
    }
    if (JSON.stringify(oldTemplate.expose) !== JSON.stringify(newTemplate.expose)) {
      return 'behavior_expose_changed';
    }
  }
  return null;
}

/**
 * Splices compatible behavior-template edits into the live IR objects the
 * mounted instances read from (state initials for future instantiations,
 * derive formulas, action bodies, carried contracts). Pairs by name — the
 * classifier guarantees the name sets match. Returns whether any derive
 * formula changed (the caller bumps the recompute revision).
 */
function spliceBehaviorTemplates(oldFile: ContractFileIR, newFile: ContractFileIR): boolean {
  const newTemplates = new Map(
    (newFile.behaviorTemplates ?? []).map((template) => [template.name, template]),
  );
  let derivesChanged = false;
  for (const oldTemplate of oldFile.behaviorTemplates ?? []) {
    const newTemplate = newTemplates.get(oldTemplate.name);
    if (!newTemplate) {
      continue;
    }
    const newStates = new Map(newTemplate.states.map((state) => [state.name, state]));
    oldTemplate.states.forEach((state) => {
      const twin = newStates.get(state.name);
      if (twin) {
        replaceExpr(state.initial, twin.initial);
      }
    });
    const newDerives = new Map(newTemplate.derives.map((derive) => [derive.name, derive]));
    oldTemplate.derives.forEach((derive) => {
      const twin = newDerives.get(derive.name);
      if (twin && JSON.stringify(derive.expr, stripVolatile) !== JSON.stringify(twin.expr, stripVolatile)) {
        derive.expr = twin.expr;
        derivesChanged = true;
      }
    });
    const newActions = new Map(newTemplate.actions.map((action) => [action.name, action]));
    oldTemplate.actions.forEach((action) => {
      const twin = newActions.get(action.name);
      if (twin) {
        action.body = twin.body;
      }
    });
    oldTemplate.contracts = newTemplate.contracts;
  }
  return derivesChanged;
}

function sameDeriveFormulas(
  left: readonly { readonly name: string; readonly expr: Expr }[],
  right: readonly { readonly name: string; readonly expr: Expr }[],
): boolean {
  return left.length === right.length &&
    left.every((item, index) =>
      item.name === right[index].name &&
      JSON.stringify(item.expr, stripVolatile) === JSON.stringify(right[index].expr, stripVolatile),
    );
}

function sameNames(
  left: readonly { readonly name: string }[],
  right: readonly { readonly name: string }[],
): boolean {
  return left.length === right.length && left.every((item, index) => item.name === right[index].name);
}

function preservedStateSlotsForFile(file: ContractFileIR): string[] {
  const templates = new Map(
    (file.behaviorTemplates ?? []).map((template) => [template.name, template]),
  );
  return file.components.flatMap((component) => [
    ...component.states.map((state) => `${component.name}.${state.name}`),
    // Behavior slot identity: componentIdentity × instanceName × slotName
    // (LLP 0280 §2.1).
    ...component.behaviors.flatMap((use) => {
      const template = use.template ? templates.get(use.template) : undefined;
      return template
        ? template.states.map((slot) => `${component.name}.${use.name}.${slot.name}`)
        : [];
    }),
  ]);
}

function refreshCompatibleStructure(file: ContractFileIR): string {
  const clone = JSON.parse(JSON.stringify(file, stripVolatile)) as ContractFileIR;
  clone.components.forEach((component) => {
    component.states.forEach((state) => {
      blankExpr(state.initial);
    });
    component.derives.forEach((derive) => {
      blankExpr(derive.expr);
    });
    component.actions.forEach((action) => {
      action.body = [];
    });
    component.contracts = [];
  });
  // Behavior templates: bodies/initials/contracts are the refresh-compatible
  // parts (LLP 0280 §2.1); names, params, signatures, tasks, and expose stay
  // in the comparison (belt to the classifier's suspenders).
  (clone.behaviorTemplates ?? []).forEach((template) => {
    template.states.forEach((state) => {
      blankExpr(state.initial);
    });
    template.derives.forEach((derive) => {
      blankExpr(derive.expr);
    });
    template.actions.forEach((action) => {
      action.body = [];
    });
    template.contracts = [];
  });
  return JSON.stringify(clone);
}

function replaceExpr(targetExpr: Expr, sourceExpr: Expr): void {
  const target = targetExpr as unknown as Record<string, unknown>;
  Object.keys(target).forEach((key) => {
    delete target[key];
  });
  Object.assign(target, sourceExpr);
}

function refreshProvenance(host: object, patch: PendingPatch, newFile: ContractFileIR): void {
  const provenance = getNodeProvenance(host);
  if (!provenance) {
    return;
  }
  const { site } = patch;
  if (site.slot.kind === 'text' && provenance.text) {
    provenance.text.value = patch.newValue;
    return;
  }
  if (site.slot.kind !== 'attr') {
    return;
  }
  // Provenance attrs key by the LOWERED prop; find via the new node's raw
  // anchors so the panel's next edit carries a fresh guard.
  const rawSource = newRawSourceFor(newFile, site);
  Object.keys(provenance.attrs).forEach((lowered) => {
    const origin = provenance.attrs[lowered];
    if (origin.sourceAttr === (site.slot as { name: string }).name) {
      origin.value = patch.newValue;
      if (rawSource !== undefined) {
        origin.rawSource = rawSource;
      }
    }
  });
}

function newRawSourceFor(newFile: ContractFileIR, site: SlotSiteIR): string | undefined {
  if (!site.nodeId || site.slot.kind !== 'attr') {
    return undefined;
  }
  const slash = site.nodeId.indexOf('/');
  const componentName = site.nodeId.slice(0, slash);
  const path = site.nodeId.slice(slash + 1);
  const component = newFile.components.find((candidate) => candidate.name === componentName);
  if (!component) {
    return undefined;
  }
  let raw: string | undefined;
  const attrName = site.slot.name;
  walkStructuralPaths(component, (node, nodePath) => {
    if (nodePath === path && (node.kind === 'element' || node.kind === 'component')) {
      raw = node.propSources?.[attrName];
    }
  });
  return raw;
}

function advanceIrOfRecord(
  oldFile: ContractFileIR,
  newFile: ContractFileIR,
  patches: PendingPatch[],
): void {
  patches.forEach((patch) => {
    const target = patch.site.value as unknown as Record<string, unknown>;
    Object.keys(target).forEach((key) => {
      delete target[key];
    });
    Object.assign(target, patch.newExpr);
  });
  // propSources carry the exact raw anchors; copy them across pairwise
  // (identical structure guarantees matching paths).
  for (let c = 0; c < oldFile.components.length; c += 1) {
    const newNodes = new Map<string, { propSources?: Record<string, string> }>();
    walkStructuralPaths(newFile.components[c], (node, path) => {
      if (node.kind === 'element' || node.kind === 'component') {
        newNodes.set(path, node);
      }
    });
    walkStructuralPaths(oldFile.components[c], (node, path) => {
      if (node.kind === 'element' || node.kind === 'component') {
        const twin = newNodes.get(path);
        if (twin) {
          node.propSources = twin.propSources;
        }
      }
    });
  }
  oldFile.sourceVersion = newFile.sourceVersion;
}

/**
 * Replaces the IR-of-record for a module wholesale (ENG-22501). The
 * hot-update remount path builds the live tree from the NEW module's IR
 * objects, so after a successful remount the record must adopt exactly that
 * file — otherwise the next edit would diff (and slot-patch) against a stale
 * base that no longer matches the mounted structure.
 */
export function adoptContractModuleRecord(file: ContractFileIR): void {
  if (!isContractDevMode() || !file.sourcePath) {
    return;
  }
  ensureGlobalHandle();
  irOfRecord.set(file.sourcePath, file);
}

/** Test hook: the live IR-of-record for a module (undefined if unknown). */
export function getContractModuleRecord(sourcePath: string): ContractFileIR | undefined {
  return irOfRecord.get(sourcePath);
}

export function getContractWitness(sourcePath: string): ContractWitness | undefined {
  return irOfRecord.get(sourcePath)?.witness;
}

export function listContractModuleRecords(): ContractFileIR[] {
  return Array.from(irOfRecord.values());
}

export function listContractWitnessModules(): ContractWitnessModuleRecord[] {
  return listContractModuleRecords()
    .filter((file): file is ContractFileIR & { sourcePath: string } =>
      typeof file.sourcePath === 'string' && file.sourcePath.length > 0,
    )
    .map((file) => ({
      sourcePath: file.sourcePath,
      witness: file.witness,
    }));
}

export function _resetContractModuleRegistryForTests(): void {
  irOfRecord.clear();
  lastRefreshDecision = null;
  handleInstalled = false;
  delete (globalThis as Record<string, unknown>).__exactContractHotPatch;
  delete (globalThis as Record<string, unknown>).__exactContractWitness;
}
