// @system @ref LLP 0185 S0-S3 — runtime execution-mode switch.

import type { Expr } from '../compiler/ir.js';
import { evalCompiledExpr } from './compiled-expr.js';
import { decorateContractError } from './error-locus.js';
import { evalExpr, Scope, type EvalOptions } from './interpreter.js';

export type ContractExecutionMode = 'interpreted' | 'compiled';

// ENG-23816: the override is a refcounted latch, not a save/restore slot.
// The mode is read synchronously by every expression evaluation, including
// reactive flushes scheduled on timers while an async override body is still
// in flight, so it cannot be restored per-caller without async-context
// tracking — and AsyncLocalStorage does not exist on Hermes. Contract:
// overlapping calls with the SAME mode share the latch (refcount); an
// overlapping call with a DIFFERENT mode throws instead of silently
// clobbering the active caller. The latch clears when the last holder exits,
// so a late `finally` can never reset the mode out from under another call.
let activeOverride: { mode: ContractExecutionMode; depth: number } | null = null;

export function contractExecutionMode(): ContractExecutionMode {
  if (activeOverride) {
    return activeOverride.mode;
  }
  const globalMode = (globalThis as { __EXACT_CONTRACT_EXECUTION?: unknown })
    .__EXACT_CONTRACT_EXECUTION;
  if (globalMode === 'compiled') {
    return 'compiled';
  }
  const processEnv = (globalThis as { process?: { env?: Record<string, string | undefined> } })
    .process?.env;
  return processEnv?.CONTRACT_EXECUTION === 'compiled' ? 'compiled' : 'interpreted';
}

export function evalRuntimeExpr(expr: Expr, scope: Scope, options?: EvalOptions): unknown {
  try {
    return contractExecutionMode() === 'compiled'
      ? evalCompiledExpr(expr, scope, options)
      : evalExpr(expr, scope, options);
  } catch (error) {
    // ENG-22443: every runtime expression entry carries the top-level
    // expression's authored span out with the error (fill-only-missing —
    // an inner statement/expression decoration is more precise and wins).
    // Span-level honesty: this is the WHOLE binding expression's span, not
    // the failing subexpression's. Costs nothing until a throw.
    decorateContractError(error, { span: expr.span });
    throw error;
  }
}

export function withContractExecutionMode<T>(mode: ContractExecutionMode, fn: () => T): T {
  if (activeOverride && activeOverride.mode !== mode) {
    throw new Error(
      `withContractExecutionMode("${mode}") while a "${activeOverride.mode}" override is ` +
        'still active: the execution mode is process-global, so overlapping overrides with ' +
        'different modes would silently corrupt each other (ENG-23816). Await the active ' +
        'override before switching modes.',
    );
  }
  if (activeOverride) {
    activeOverride.depth += 1;
  } else {
    activeOverride = { mode, depth: 1 };
  }
  const latch = activeOverride;
  const release = (): void => {
    // Only release the latch this call acquired — if
    // _resetContractExecutionModeForTests() cleared it (and possibly a new
    // override was installed since), a stale release must not touch it.
    if (activeOverride !== latch) {
      return;
    }
    latch.depth -= 1;
    if (latch.depth <= 0) {
      activeOverride = null;
    }
  };
  try {
    const result = fn();
    if (result && typeof (result as unknown as Promise<unknown>).finally === 'function') {
      return (result as unknown as Promise<unknown>).finally(release) as T;
    }
    release();
    return result;
  } catch (error) {
    release();
    throw error;
  }
}

export function _resetContractExecutionModeForTests(): void {
  activeOverride = null;
}
