import type {
  FacetComponentInfo,
  FloatingPositionData,
  ThemeSnapshotData,
} from './types.js';

interface ExperienceRegistryState {
  theme: ThemeSnapshotData | null;
  themeOverride: Record<string, unknown> | null;
  facetComponents: Map<string, FacetComponentInfo>;
  floatingPositions: Map<string, FloatingPositionData>;
  themeOverrideListeners: Set<() => void>;
  // Optional because the global state object may have been created by an
  // older copy of this module in another bundle (dev HMR, multi-bundle
  // hosts); accessors lazily initialize it (ENG-23202).
  themeSnapshotListeners?: Set<() => void>;
  // Optional for the same older-copy reason. Bumped whenever a floating
  // position's geometry actually changes — the renderer's frame-index cache
  // keys on it (ENG-23251).
  floatingPositionsVersion?: number;
  // LLP 0321 B1 (ENG-23534): bumped on ANY observable floating-position
  // change, including the non-geometry fields (`state`, `scrolling`, ...)
  // that deliberately do not bump `floatingPositionsVersion`. The incremental
  // serialization cache keys on this — `whyNotInteractable` reads those
  // fields, so a settled reposition that only flips `scrolling` must still
  // invalidate the affected node.
  floatingPositionsMutationCount?: number;
  // LLP 0321 B1 (ENG-23534): bumped when the facet-component registry
  // changes; serialized nodes embed registry entries by reference.
  facetComponentsVersion?: number;
}

declare global {
  var __exactExperienceRegistryState: ExperienceRegistryState | undefined;
}

function getRegistryState(): ExperienceRegistryState {
  if (globalThis.__exactExperienceRegistryState) {
    return globalThis.__exactExperienceRegistryState;
  }

  const state: ExperienceRegistryState = {
    theme: null,
    themeOverride: null,
    facetComponents: new Map(),
    floatingPositions: new Map(),
    themeOverrideListeners: new Set(),
    themeSnapshotListeners: new Set(),
  };
  globalThis.__exactExperienceRegistryState = state;
  return state;
}

function getThemeSnapshotListeners(): Set<() => void> {
  return (registry.themeSnapshotListeners ??= new Set());
}

const registry = getRegistryState();

export function setThemeSnapshot(snapshot: ThemeSnapshotData): void {
  registry.theme = { ...snapshot, tokens: { ...snapshot.tokens } };
  for (const listener of getThemeSnapshotListeners()) {
    listener();
  }
}

/**
 * Notifies after every theme snapshot publish (scheme flips AND token edits).
 * Renderer-side consumers gate on the field they care about — host-ops uses
 * this to re-resolve theme-aware image sources when `scheme` changes
 * (ENG-23202); resolveImageSourceForNative bakes the scheme into canonical
 * props at normalize time, so without a push-based refresh a dark-mode flip
 * keeps the light asset until an unrelated prop change re-encodes the node.
 */
export function subscribeThemeSnapshot(listener: () => void): () => void {
  const listeners = getThemeSnapshotListeners();
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

export function getThemeSnapshot(): ThemeSnapshotData | null {
  return registry.theme
    ? { ...registry.theme, tokens: { ...registry.theme.tokens } }
    : null;
}

export function setThemeOverride(override: Record<string, unknown> | null): void {
  registry.themeOverride = override ? { ...override } : null;
  for (const listener of registry.themeOverrideListeners) {
    listener();
  }
}

export function getThemeOverride(): Record<string, unknown> | null {
  return registry.themeOverride ? { ...registry.themeOverride } : null;
}

export function subscribeThemeOverride(listener: () => void): () => void {
  registry.themeOverrideListeners.add(listener);
  return () => {
    registry.themeOverrideListeners.delete(listener);
  };
}

export function registerFacetComponents(components: FacetComponentInfo[]): void {
  for (const component of components) {
    registry.facetComponents.set(component.name, {
      ...component,
      props: component.props?.map((entry) => ({ ...entry })),
      variants: component.variants?.map((entry) => ({
        ...entry,
        values: entry.values.slice(),
      })),
      dependencies: component.dependencies?.slice(),
      annotations: component.annotations ? { ...component.annotations } : undefined,
    });
  }
  if (components.length > 0) {
    registry.facetComponentsVersion = (registry.facetComponentsVersion ?? 0) + 1;
  }
}

export function getFacetComponentsVersion(): number {
  return registry.facetComponentsVersion ?? 0;
}

export function getFacetComponents(): FacetComponentInfo[] {
  return Array.from(registry.facetComponents.values()).sort((left, right) =>
    left.name.localeCompare(right.name),
  );
}

export function upsertFloatingPosition(position: FloatingPositionData): void {
  // Bump only on geometry-affecting changes so repeated identical upserts
  // (per-frame repositioning that settled) don't defeat frame-index caching.
  const current = registry.floatingPositions.get(position.id);
  if (
    !current ||
    current.viewId !== position.viewId ||
    current.positioned !== position.positioned ||
    current.x !== position.x ||
    current.y !== position.y ||
    current.width !== position.width ||
    current.height !== position.height
  ) {
    registry.floatingPositionsVersion =
      (registry.floatingPositionsVersion ?? 0) + 1;
  }
  // LLP 0321 B1 (ENG-23534): the mutation count also covers non-geometry
  // fields the serialization cache observes (`state`, `scrolling`, clipping,
  // middleware data). Skip the bump only when the stored record is
  // observably identical, so settled per-frame upserts stay cheap for the
  // cache too.
  if (!current || !floatingPositionsObservablyEqual(current, position)) {
    registry.floatingPositionsMutationCount =
      (registry.floatingPositionsMutationCount ?? 0) + 1;
  }
  registry.floatingPositions.set(position.id, { ...position });
}

function floatingPositionsObservablyEqual(
  left: FloatingPositionData,
  right: FloatingPositionData,
): boolean {
  if (left === right) {
    return true;
  }
  const leftRecord = left as unknown as Record<string, unknown>;
  const rightRecord = right as unknown as Record<string, unknown>;
  const keys = new Set([...Object.keys(leftRecord), ...Object.keys(rightRecord)]);
  for (const key of keys) {
    const leftValue = leftRecord[key];
    const rightValue = rightRecord[key];
    if (leftValue === rightValue) {
      continue;
    }
    // Nested payloads (`middlewareData`, arrays) compare structurally; both
    // sides are plain JSON-shaped records by construction.
    if (JSON.stringify(leftValue) !== JSON.stringify(rightValue)) {
      return false;
    }
  }
  return true;
}

export function removeFloatingPosition(id: string): void {
  if (registry.floatingPositions.delete(id)) {
    registry.floatingPositionsVersion =
      (registry.floatingPositionsVersion ?? 0) + 1;
    registry.floatingPositionsMutationCount =
      (registry.floatingPositionsMutationCount ?? 0) + 1;
  }
}

export function getFloatingPositionsVersion(): number {
  return registry.floatingPositionsVersion ?? 0;
}

export function getFloatingPositionsMutationCount(): number {
  return registry.floatingPositionsMutationCount ?? 0;
}

export function getFloatingPositions(): FloatingPositionData[] {
  return Array.from(registry.floatingPositions.values()).sort(
    (left, right) => left.updatedAt - right.updatedAt,
  );
}

export function findFloatingPositionByViewId(viewId: number): FloatingPositionData | null {
  for (const position of registry.floatingPositions.values()) {
    if (position.viewId === viewId) {
      return { ...position };
    }
  }
  return null;
}

export function _resetExperienceRegistryForTests(): void {
  registry.theme = null;
  registry.themeOverride = null;
  registry.facetComponents.clear();
  registry.floatingPositions.clear();
  registry.themeOverrideListeners.clear();
  registry.themeSnapshotListeners?.clear();
  registry.floatingPositionsVersion = (registry.floatingPositionsVersion ?? 0) + 1;
  registry.floatingPositionsMutationCount =
    (registry.floatingPositionsMutationCount ?? 0) + 1;
  registry.facetComponentsVersion = (registry.facetComponentsVersion ?? 0) + 1;
}
