// @system @ref LLP 0166 §4.6 (S2) — the canonical whole-file formatter.
//
// This module EXTENDS the S0b value printer (print.ts) — literal escaping
// has exactly one home there; a sibling printer is the named failure mode
// (LLP 0166 §8). The laws, verified over the repo corpus in
// __tests__/format.test.ts:
//
//  1. Round-trip: parse(format(source)) is IR-identical to parse(source)
//     modulo spans and propSources.
//  2. Idempotence: format(format(source)) === format(source).
//  3. Comment survival: comment-only lines re-emit at the indentation of the
//     next code line (previous code line at EOF); trailing `//` comments
//     re-attach as ` // ...` after their formatted line. A trailing comment
//     whose logical line prints as part of another formatted line (a bare
//     `else` collapsed into an `else when` chain, an empty block header)
//     degrades to a comment-only line — text always survives.
//  4. Canonical blank lines: runs of blank lines collapse to ONE blank line;
//     exactly one blank line is forced before each top-level `component`
//     declaration (or its attached comment block); no leading blank lines;
//     the file ends with exactly one trailing newline.
//  5. EOL: whole-file output is LF-normalized. (The minimal-splice edit path
//     in edit.ts preserves EOL byte-for-byte; that is not this path.)
//
// Canonical choices, deliberate for v0:
//  - Authored block order is PRESERVED via node spans — no canonical
//    reordering of component blocks (a v0 choice; a canonical block order is
//    a B-4 freeze question, not a formatter default).
//  - On a node line, props print before events, each in insertion order —
//    authored prop/event interleaving is not recoverable from the IR's
//    split records, so props-then-events IS the canonical attr order.
//  - Primary-arg sugar is canonical (`text "Hi" size=13`, `button "Save"
//    press=go`); `else when` / `else if` chains are canonical; component
//    calls print in call form (`Name(a=1, b=2)`).
//  - Selector attrs print label before testId; control attrs print in
//    as / bind / min / max / step / options / label / group order.

import { parseContractSource } from './parser.js';
import { stripComment } from './lexer.js';
import { printLiteral, printValue } from './print.js';
import { isExprSpread } from './ir.js';
import type {
  ActionIR,
  AssignTarget,
  BehaviorTemplateIR,
  ComponentIR,
  ContractClauseIR,
  ContractFileIR,
  ContractSelectorIR,
  DesignControlIR,
  ElementNodeIR,
  Expr,
  SnippetIR,
  Stmt,
  TaskIR,
  ViewNodeIR,
} from './ir.js';

// ---------------------------------------------------------------------------
// Expressions
// ---------------------------------------------------------------------------

// Mirrors BINARY_PRECEDENCE in expr.ts (parsing is left-associative within a
// level; ternary binds loosest and only parses at precedence 0).
const BINARY_PRECEDENCE: Record<string, number> = {
  '??': 1,
  '||': 2,
  '&&': 3,
  '==': 4,
  '!=': 4,
  '<': 5,
  '<=': 5,
  '>': 5,
  '>=': 5,
  '+': 6,
  '-': 6,
  '*': 7,
  '/': 7,
  '%': 7,
};

/** Expr kinds that re-parse correctly as a bare member/index/call base.
    Numbers are excluded (`5.x` lexes the dot into the number); token refs
    are excluded (`$a.b.x` would re-lex the member access into the path). */
const POSTFIX_SAFE_BASES = new Set<Expr['kind']>([
  'ident',
  'member',
  'index',
  'call',
  'relation',
  'string',
  'template',
  'array',
  'object',
  'boolean',
  'null',
]);

const BARE_OBJECT_KEY = /^[A-Za-z_$][A-Za-z0-9_$]*$/;

/**
 * Prints any Expr as Contract source text, inserting parentheses only where
 * required to preserve structure. Law (verified by fixture):
 * parseExpressionSource(printExpression(e)) is Expr-identical modulo spans
 * for every parser-producible expression.
 */
export function printExpression(expr: Expr): string {
  switch (expr.kind) {
    case 'string':
    case 'boolean':
    case 'null':
    case 'token':
      return printValue(expr);
    case 'number':
      return printNumberSource(expr.value);
    case 'ident':
      return expr.name;
    case 'member':
      return `${printPostfixBase(expr.object)}${expr.optional ? '?.' : '.'}${expr.property}`;
    case 'index':
      return `${printPostfixBase(expr.object)}[${printExpression(expr.index)}]`;
    case 'call':
      return `${printPostfixBase(expr.callee)}(${expr.args.map(printExpression).join(', ')})`;
    case 'relation':
      return `${expr.op}(${expr.args.map(printExpression).join(', ')})`;
    case 'unary': {
      const operand = expr.operand;
      const grouped =
        operand.kind === 'unary' ||
        operand.kind === 'binary' ||
        operand.kind === 'ternary' ||
        operand.kind === 'arrow';
      return `${expr.op}${grouped ? `(${printExpression(operand)})` : printExpression(operand)}`;
    }
    case 'binary': {
      const precedence = BINARY_PRECEDENCE[expr.op];
      const left = printBinaryOperand(expr.left, precedence, false);
      const right = printBinaryOperand(expr.right, precedence, true);
      return `${left} ${expr.op} ${right}`;
    }
    case 'ternary': {
      // A ternary in test position would re-associate (`a ? b : c ? d : e`
      // parses the second ternary into the alternate); consequent/alternate
      // nest correctly unparenthesized.
      const test =
        expr.test.kind === 'ternary' || expr.test.kind === 'arrow'
          ? `(${printExpression(expr.test)})`
          : printExpression(expr.test);
      return `${test} ? ${printExpression(expr.consequent)} : ${printExpression(expr.alternate)}`;
    }
    case 'template':
      return printTemplate(expr);
    case 'array':
      return `[${expr.items
        .map((item) => (isExprSpread(item) ? `...${printExpression(item.value)}` : printExpression(item)))
        .join(', ')}]`;
    case 'object': {
      if (expr.entries.length === 0) {
        return '{}';
      }
      const entries = expr.entries.map((entry) =>
        isExprSpread(entry)
          ? `...${printExpression(entry.value)}`
          : `${printObjectKey(entry.key)}: ${printExpression(entry.value)}`,
      );
      return `{ ${entries.join(', ')} }`;
    }
    case 'arrow': {
      const params =
        expr.params.length === 1 ? expr.params[0] : `(${expr.params.join(', ')})`;
      return `${params} => ${printExpression(expr.body)}`;
    }
  }
}

function printPostfixBase(expr: Expr): string {
  const printed = printExpression(expr);
  return POSTFIX_SAFE_BASES.has(expr.kind) ? printed : `(${printed})`;
}

function printBinaryOperand(expr: Expr, parentPrecedence: number, isRight: boolean): string {
  const printed = printExpression(expr);
  if (expr.kind === 'ternary' || expr.kind === 'arrow') {
    return `(${printed})`;
  }
  if (expr.kind === 'binary') {
    const precedence = BINARY_PRECEDENCE[expr.op];
    if (precedence < parentPrecedence || (isRight && precedence === parentPrecedence)) {
      return `(${printed})`;
    }
  }
  return printed;
}

function printObjectKey(key: string): string {
  return BARE_OBJECT_KEY.test(key) ? key : printLiteral(key);
}

/** The lexer has no exponent form; expand values whose default rendering
    is exponential so the printed literal re-lexes to the same value. */
function printNumberSource(value: number): string {
  const direct = printValue({ kind: 'number', value });
  if (!/[eE]/.test(direct)) {
    return direct;
  }
  if (Number.isInteger(value)) {
    return BigInt(value).toString();
  }
  const match = /e-(\d+)$/.exec(direct);
  if (!match) {
    throw new TypeError(`cannot print number ${value} as Contract source`);
  }
  return value
    .toFixed(Math.min(100, Number(match[1]) + 17))
    .replace(/0+$/, '')
    .replace(/\.$/, '');
}

function printTemplate(expr: Expr & { kind: 'template' }): string {
  let out = '`';
  expr.parts.forEach((part) => {
    if (part.kind === 'text') {
      out += encodeTemplateText(part.text);
    } else {
      out += '${' + printExpression(part.expr) + '}';
    }
  });
  return out + '`';
}

function encodeTemplateText(text: string): string {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const ch = text[i];
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === '`') {
      out += '\\`';
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === '$' && text[i + 1] === '{') {
      out += '\\$';
    } else {
      out += ch;
    }
  }
  return out;
}

// ---------------------------------------------------------------------------
// Whole-file formatting
// ---------------------------------------------------------------------------

interface OutLine {
  indent: number;
  text: string;
  /** Source line this formatted line derives from (trivia interleaving). */
  sourceLine: number;
  /** True when this line IS the printed form of its source line — trailing
      comments re-attach here. False for derived lines (block headers,
      `else`/`view` lines) that borrow a neighbor's line for ordering. */
  owns: boolean;
  componentHeader: boolean;
}

export function formatContractSource(source: string, sourcePath?: string): string {
  const normalized = source.replace(/\r\n/g, '\n');
  const file = parseContractSource(normalized, sourcePath);
  const out: OutLine[] = [];
  emitFile(file, out);
  return renderWithTrivia(out, normalized);
}

export function printViewNodeSource(node: ViewNodeIR, indent = 0): string {
  return printViewNodesSource([node], indent);
}

export function printViewNodesSource(nodes: readonly ViewNodeIR[], indent = 0): string {
  const out: OutLine[] = [];
  nodes.forEach((node) => emitViewNode(node, indent, out));
  return out.map((line) => `${'  '.repeat(line.indent)}${line.text}`).join('\n');
}

function push(
  out: OutLine[],
  indent: number,
  text: string,
  sourceLine: number,
  owns: boolean,
  componentHeader = false,
): void {
  out.push({ indent, text, sourceLine, owns, componentHeader });
}

function emitFile(file: ContractFileIR, out: OutLine[]): void {
  // Top-level declarations in authored order (uses, behaviors, and
  // components by span).
  const decls: Array<{ line: number; emit: () => void }> = [];
  file.uses.forEach((use) => {
    decls.push({
      line: use.span.line,
      emit: () =>
        push(out, 0, `use ${use.name} from ${printLiteral(use.spec)}`, use.span.line, true),
    });
  });
  (file.behaviorTemplates ?? []).forEach((template) => {
    decls.push({ line: template.span.line, emit: () => emitBehaviorTemplate(template, out) });
  });
  file.components.forEach((component) => {
    decls.push({ line: component.span.line, emit: () => emitComponent(component, out) });
  });
  decls.sort((a, b) => a.line - b.line);
  decls.forEach((decl) => decl.emit());
}

type BlockGroup = 'props' | 'params' | 'design' | 'contract';

function emitComponent(component: ComponentIR, out: OutLine[]): void {
  push(out, 0, `component ${component.name}`, component.span.line, true, true);

  // Authored block order preserved via spans (v0 choice — see module header).
  const items: Array<{ line: number; group?: BlockGroup; emit: () => void }> = [];

  component.props.forEach((prop) => {
    const type = prop.parsedType?.raw ?? prop.type;
    const text =
      prop.name +
      (type !== undefined ? `: ${type}` : '') +
      (prop.defaultValue !== undefined ? ` = ${printExpression(prop.defaultValue)}` : '');
    items.push({
      line: prop.span.line,
      group: 'props',
      emit: () => push(out, 2, text, prop.span.line, true),
    });
  });
  (component.params ?? []).forEach((param) => {
    const text =
      `${param.name} = ${printExpression(param.defaultValue)}` +
      (param.kind !== undefined ? ` kind=${param.kind}` : '');
    items.push({
      line: param.span.line,
      group: 'params',
      emit: () => push(out, 2, text, param.span.line, true),
    });
  });
  (component.controls ?? []).forEach((control) => {
    items.push({
      line: control.span.line,
      group: 'design',
      emit: () => push(out, 2, controlText(control), control.span.line, true),
    });
  });
  component.states.forEach((state) => {
    const type = state.parsedType?.raw ?? state.type;
    const text =
      `state ${state.name}` +
      (type !== undefined ? `: ${type}` : '') +
      ` = ${printExpression(state.initial)}`;
    items.push({ line: state.span.line, emit: () => push(out, 1, text, state.span.line, true) });
  });
  component.derives.forEach((derive) => {
    const text =
      `derive ${derive.name}` +
      (derive.type !== undefined ? `: ${derive.type}` : '') +
      ` = ${printExpression(derive.expr)}`;
    items.push({ line: derive.span.line, emit: () => push(out, 1, text, derive.span.line, true) });
  });
  component.resources.forEach((resource) => {
    const text = `resource ${resource.name} = ${printExpression(resource.expr)}`;
    items.push({
      line: resource.span.line,
      emit: () => push(out, 1, text, resource.span.line, true),
    });
  });
  component.queries.forEach((query) => {
    const text = `query ${query.name} = ${printExpression(query.expr)}${query.once ? ' once' : ''}`;
    items.push({
      line: query.span.line,
      emit: () => push(out, 1, text, query.span.line, true),
    });
  });
  (component.ephemerals ?? []).forEach((ephemeral) => {
    const text = `ephemeral ${ephemeral.name} = ${printExpression(ephemeral.expr)}`;
    items.push({
      line: ephemeral.span.line,
      emit: () => push(out, 1, text, ephemeral.span.line, true),
    });
  });
  component.mutations.forEach((mutation) => {
    const text = `mutation ${mutation.name} = ${printExpression(mutation.expr)}`;
    items.push({
      line: mutation.span.line,
      emit: () => push(out, 1, text, mutation.span.line, true),
    });
  });
  component.behaviors.forEach((behavior) => {
    const text = `use ${behavior.name} = ${printExpression(behavior.expr)}`;
    items.push({
      line: behavior.span.line,
      emit: () => push(out, 1, text, behavior.span.line, true),
    });
  });
  component.actions.forEach((action) => {
    items.push({ line: action.span.line, emit: () => emitAction(action, out) });
  });
  component.tasks.forEach((task) => {
    items.push({ line: task.span.line, emit: () => emitTask(task, out) });
  });
  component.snippets.forEach((snippet) => {
    items.push({ line: snippet.span.line, emit: () => emitSnippet(snippet, out) });
  });
  component.contracts.forEach((clause) => {
    items.push({
      line: clause.span.line,
      group: 'contract',
      emit: () => push(out, 2, clauseText(clause), clause.span.line, true),
    });
  });
  items.push({
    line: component.view.span.line,
    emit: () => {
      push(out, 1, 'view', component.view.span.line, false);
      emitViewNode(component.view, 2, out);
    },
  });

  items.sort((a, b) => a.line - b.line);
  let openGroup: BlockGroup | undefined;
  items.forEach((item) => {
    if (item.group !== undefined && item.group !== openGroup) {
      push(out, 1, item.group, item.line, false);
    }
    openGroup = item.group;
    item.emit();
  });
}

/**
 * LLP 0280 §2.1 — behavior template emission. Same shape as a component
 * body (authored order via spans, contract clauses grouped) with the
 * template's `expose` line in its authored position.
 */
function emitBehaviorTemplate(template: BehaviorTemplateIR, out: OutLine[]): void {
  const params = template.params.length > 0 ? `(${template.params.join(', ')})` : '';
  push(out, 0, `behavior ${template.name}${params}`, template.span.line, true, true);

  const items: Array<{ line: number; group?: BlockGroup; emit: () => void }> = [];
  template.states.forEach((state) => {
    const type = state.parsedType?.raw ?? state.type;
    const text =
      `state ${state.name}` +
      (type !== undefined ? `: ${type}` : '') +
      ` = ${printExpression(state.initial)}`;
    items.push({ line: state.span.line, emit: () => push(out, 1, text, state.span.line, true) });
  });
  template.derives.forEach((derive) => {
    const text =
      `derive ${derive.name}` +
      (derive.type !== undefined ? `: ${derive.type}` : '') +
      ` = ${printExpression(derive.expr)}`;
    items.push({ line: derive.span.line, emit: () => push(out, 1, text, derive.span.line, true) });
  });
  template.actions.forEach((action) => {
    items.push({ line: action.span.line, emit: () => emitAction(action, out) });
  });
  template.tasks.forEach((task) => {
    items.push({ line: task.span.line, emit: () => emitTask(task, out) });
  });
  template.contracts.forEach((clause) => {
    items.push({
      line: clause.span.line,
      group: 'contract',
      emit: () => push(out, 2, clauseText(clause), clause.span.line, true),
    });
  });
  const exposeLine = template.exposeSpan?.line ?? Number.MAX_SAFE_INTEGER;
  items.push({
    line: exposeLine,
    emit: () =>
      push(
        out,
        1,
        `expose ${template.expose.join(', ')}`,
        template.exposeSpan?.line ?? template.span.line,
        true,
      ),
  });

  items.sort((a, b) => a.line - b.line);
  let openGroup: BlockGroup | undefined;
  items.forEach((item) => {
    if (item.group !== undefined && item.group !== openGroup) {
      push(out, 1, item.group, item.line, false);
    }
    openGroup = item.group;
    item.emit();
  });
}

function controlText(control: DesignControlIR): string {
  const binding = control.binding;
  const name = binding.kind === 'facet' ? binding.param : binding.name;
  let text = `control ${binding.kind} ${name}`;
  if (control.controlKind !== undefined) {
    text += ` as ${control.controlKind}`;
  }
  if (binding.kind === 'token') {
    text += ` bind=$${binding.path}`;
  }
  const constraints = control.constraints;
  if (constraints.min !== undefined) {
    text += ` min=${printNumberSource(constraints.min)}`;
  }
  if (constraints.max !== undefined) {
    text += ` max=${printNumberSource(constraints.max)}`;
  }
  if (constraints.step !== undefined) {
    text += ` step=${printNumberSource(constraints.step)}`;
  }
  if (constraints.options !== undefined) {
    text += ` options=[${constraints.options.map(printLiteral).join(', ')}]`;
  }
  if (control.label !== undefined) {
    text += ` label=${printLiteral(control.label)}`;
  }
  if (control.group !== undefined) {
    text += ` group=${printLiteral(control.group)}`;
  }
  return text;
}

function emitAction(action: ActionIR, out: OutLine[]): void {
  let text = `action ${action.name}`;
  if (action.params.length > 0) {
    text += `(${action.params.join(', ')})`;
  }
  if (action.writes !== undefined) {
    text += ` writes ${action.writes.join(', ')}`;
  }
  if (action.mutates !== undefined) {
    text += ` mutates ${action.mutates.join(', ')}`;
  }
  push(out, 1, text, action.span.line, true);
  emitStatements(action.body, 2, out);
}

function emitTask(task: TaskIR, out: OutLine[]): void {
  const trigger =
    task.trigger.kind === 'when' ? `when [${task.trigger.deps.join(', ')}]` : task.trigger.kind;
  const mutates = task.mutates !== undefined ? ` mutates ${task.mutates.join(', ')}` : '';
  push(out, 1, `task ${task.name} ${trigger}${mutates}`, task.span.line, true);
  emitStatements(task.body, 2, out);
}

function emitSnippet(snippet: SnippetIR, out: OutLine[]): void {
  const params = snippet.params.length > 0 ? `(${snippet.params.join(', ')})` : '';
  push(out, 1, `snippet ${snippet.name}${params}`, snippet.span.line, true);
  snippet.body.forEach((child) => emitViewNode(child, 2, out));
}

// ---------------------------------------------------------------------------
// Statements
// ---------------------------------------------------------------------------

function emitStatements(statements: Stmt[], indent: number, out: OutLine[]): void {
  statements.forEach((stmt) => emitStmt(stmt, indent, out));
}

function emitStmt(stmt: Stmt, indent: number, out: OutLine[]): void {
  switch (stmt.kind) {
    case 'let':
      push(out, indent, `let ${stmt.name} = ${printExpression(stmt.value)}`, stmt.span.line, true);
      return;
    case 'assign':
      push(
        out,
        indent,
        `${printAssignTarget(stmt.target)} = ${printExpression(stmt.value)}`,
        stmt.span.line,
        true,
      );
      return;
    case 'expr':
      push(
        out,
        indent,
        `${stmt.await === true ? 'await ' : ''}${printExpression(stmt.expr)}`,
        stmt.span.line,
        true,
      );
      return;
    case 'return':
      push(
        out,
        indent,
        stmt.value !== undefined ? `return ${printExpression(stmt.value)}` : 'return',
        stmt.span.line,
        true,
      );
      return;
    case 'await-assign': {
      const value = `await ${printExpression(stmt.value)}`;
      if (stmt.target === null) {
        push(out, indent, value, stmt.span.line, true);
      } else if (stmt.isLet && stmt.target.kind === 'name') {
        push(out, indent, `let ${stmt.target.name} = ${value}`, stmt.span.line, true);
      } else {
        push(out, indent, `${printAssignTarget(stmt.target)} = ${value}`, stmt.span.line, true);
      }
      return;
    }
    case 'for':
      push(
        out,
        indent,
        `for ${stmt.item} in ${printExpression(stmt.iterable)}`,
        stmt.span.line,
        true,
      );
      emitStatements(stmt.body, indent + 1, out);
      return;
    case 'if':
      emitIf(stmt, indent, 'if', out);
      return;
  }
}

function emitIf(stmt: Stmt & { kind: 'if' }, indent: number, head: 'if' | 'else if', out: OutLine[]): void {
  if (stmt.inline === true && head === 'if' && stmt.else === undefined && stmt.then.length === 1) {
    const statement = inlineStatementText(stmt.then[0]);
    if (statement !== null) {
      push(out, indent, `if ${printExpression(stmt.test)} then ${statement}`, stmt.span.line, true);
      return;
    }
  }
  push(out, indent, `${head} ${printExpression(stmt.test)}`, stmt.span.line, true);
  emitStatements(stmt.then, indent + 1, out);
  if (stmt.else === undefined) {
    return;
  }
  if (stmt.else.length === 1 && stmt.else[0].kind === 'if') {
    emitIf(stmt.else[0], indent, 'else if', out);
    return;
  }
  push(out, indent, 'else', stmt.else[0]?.span.line ?? stmt.span.line, false);
  emitStatements(stmt.else, indent + 1, out);
}

function inlineStatementText(stmt: Stmt): string | null {
  switch (stmt.kind) {
    case 'let':
      return `let ${stmt.name} = ${printExpression(stmt.value)}`;
    case 'assign':
      return `${printAssignTarget(stmt.target)} = ${printExpression(stmt.value)}`;
    case 'expr':
      return `${stmt.await === true ? 'await ' : ''}${printExpression(stmt.expr)}`;
    case 'return':
      return stmt.value !== undefined ? `return ${printExpression(stmt.value)}` : 'return';
    case 'await-assign': {
      const value = `await ${printExpression(stmt.value)}`;
      if (stmt.target === null) {
        return value;
      }
      if (stmt.isLet && stmt.target.kind === 'name') {
        return `let ${stmt.target.name} = ${value}`;
      }
      return `${printAssignTarget(stmt.target)} = ${value}`;
    }
    case 'for':
    case 'if':
      return null;
  }
}

function printAssignTarget(target: AssignTarget): string {
  switch (target.kind) {
    case 'name':
      return target.name;
    case 'member':
      return `${printPostfixBase(target.object)}.${target.property}`;
    case 'index':
      return `${printPostfixBase(target.object)}[${printExpression(target.index)}]`;
  }
}

// ---------------------------------------------------------------------------
// Contract clauses
// ---------------------------------------------------------------------------

function clauseText(clause: ContractClauseIR): string {
  switch (clause.kind) {
    case 'has':
      return `has ${selectorText(clause.selector)}`;
    case 'missing':
      return `missing ${selectorText(clause.selector)}`;
    case 'count':
      return `count ${selectorText(clause.selector)} = ${printExpression(clause.expected)}`;
    case 'state':
      return `state ${selectorText(clause.selector)} is ${clause.state}`;
    case 'press': {
      const navigationOutcomes = clause.navigate
        ? navigationOutcomeText(clause.alternates, clause.expectedRedirects)
        : '';
      const action = clause.navigate
        ? ` -> navigate ${printExpression(clause.navigate)}${navigationOutcomes}`
        : clause.action
          ? ` -> ${clause.action}`
          : '';
      const outcome =
        clause.expects && clause.expects.length > 0
          ? ` then ${clauseText(clause.expects[0]!)}`
          : '';
      return `press ${selectorText(clause.selector)}${action}${outcome}`;
    }
    case 'navigate':
      return `navigate ${printExpression(clause.target)}${navigationOutcomeText(
        clause.alternates,
        clause.expectedRedirects,
      )}`;
    case 'exits':
      return `exits ${clause.only ? 'only ' : ''}${clause.targets.map(printExpression).join(', ')}`;
    case 'change': {
      const outcome =
        clause.expects && clause.expects.length > 0
          ? ` then ${clauseText(clause.expects[0]!)}`
          : '';
      return `${clause.kind} ${selectorText(clause.selector)} -> ${clause.action}${outcome}`;
    }
    case 'when':
      return `when ${printExpression(clause.test)} then ${clauseText(clause.clause)}`;
    case 'invariant':
      return `invariant ${clauseText(clause.clause)}`;
    case 'action-writes':
      return `action ${clause.action} writes ${clause.writes.join(', ')}`;
    case 'derive-depends':
      return `derive ${clause.derive} depends only on ${clause.deps.join(', ')}`;
  }
}

function navigationOutcomeText(alternates: Expr[] | undefined, expectedRedirects: Expr[] | undefined): string {
  return [
    alternates && alternates.length > 0 ? ` | ${alternates.map(printExpression).join(' | ')}` : '',
    expectedRedirects && expectedRedirects.length > 0
      ? ` then ${expectedRedirects.map(printExpression).join(' | ')}`
      : '',
  ].join('');
}

function selectorText(selector: ContractSelectorIR): string {
  let text = selector.kind;
  if (selector.value !== undefined) {
    text += ` ${printLiteral(selector.value)}`;
  }
  if (selector.label !== undefined) {
    text += ` label=${printLiteral(selector.label)}`;
  }
  if (selector.testId !== undefined) {
    text += ` testId=${printLiteral(selector.testId)}`;
  }
  if (selector.role !== undefined) {
    text += ` role=${printLiteral(selector.role)}`;
  }
  return text;
}

// ---------------------------------------------------------------------------
// View
// ---------------------------------------------------------------------------

function emitViewNode(node: ViewNodeIR, indent: number, out: OutLine[]): void {
  switch (node.kind) {
    case 'element':
      emitElement(node, indent, out);
      return;
    case 'component': {
      const attrs = nodeAttrs(node)
        .map(([name, value]) => `${name}=${printExpression(value)}`)
        .join(', ');
      push(out, indent, `${node.name}(${attrs})`, node.span.line, true);
      node.children.forEach((child) => emitViewNode(child, indent + 1, out));
      return;
    }
    case 'when':
      emitWhen(node, indent, 'when', out);
      return;
    case 'match':
      push(out, indent, `match ${printExpression(node.expr)}`, node.span.line, true);
      node.cases.forEach((arm) => {
        push(out, indent + 1, `case ${printExpression(arm.test)}`, arm.span.line, true);
        arm.body.forEach((child) => emitViewNode(child, indent + 2, out));
      });
      if (node.else !== undefined) {
        push(out, indent + 1, 'else', node.else[0]?.span.line ?? node.span.line, false);
        node.else.forEach((child) => emitViewNode(child, indent + 2, out));
      }
      return;
    case 'match-size':
      push(out, indent, 'match size', node.span.line, true);
      node.cases.forEach((arm) => {
        push(out, indent + 1, `case ${printLiteral(arm.value)}`, arm.span.line, true);
        arm.body.forEach((child) => emitViewNode(child, indent + 2, out));
      });
      if (node.else !== undefined) {
        push(out, indent + 1, 'else', node.else[0]?.span.line ?? node.span.line, false);
        node.else.forEach((child) => emitViewNode(child, indent + 2, out));
      }
      return;
    case 'nothing':
      push(out, indent, 'nothing', node.span.line, true);
      return;
    case 'hole':
      push(out, indent, node.label === undefined ? 'hole' : `hole ${printLiteral(node.label)}`, node.span.line, true);
      return;
    case 'each': {
      const binding = node.index !== undefined ? `${node.item}, ${node.index}` : node.item;
      push(
        out,
        indent,
        `each ${binding} in ${printExpression(node.iterable)} key=${printExpression(node.key)}`,
        node.span.line,
        true,
      );
      node.body.forEach((child) => emitViewNode(child, indent + 1, out));
      return;
    }
    case 'resource':
    case 'async':
      push(out, indent, `${node.kind} ${node.name}`, node.span.line, true);
      node.slots.forEach((slot) => {
        const binding = slot.binding ? ` ${slot.binding}` : '';
        push(out, indent + 1, `${slot.kind}${binding}`, slot.span.line, true);
        slot.body.forEach((child) => emitViewNode(child, indent + 2, out));
      });
      return;
    case 'boundary':
      push(out, indent, 'boundary', node.span.line, true);
      push(
        out,
        indent + 1,
        `fallback${node.fallback.binding ? ` ${node.fallback.binding}` : ''}`,
        node.fallback.span.line,
        true,
      );
      node.fallback.body.forEach((child) => emitViewNode(child, indent + 2, out));
      node.body.forEach((child) => emitViewNode(child, indent + 1, out));
      return;
    case 'text':
      push(out, indent, `text ${printExpression(node.expr)}`, node.span.line, true);
      return;
    case 'children':
      push(out, indent, 'children', node.span.line, true);
      return;
    case 'snippet-call':
      push(
        out,
        indent,
        `${node.name}(${node.args.map(printExpression).join(', ')})`,
        node.span.line,
        true,
      );
      return;
    case 'publish': {
      // LLP 0281 §3.1 (ENG-22525): rated publish effect line.
      let text = `publish ${printExpression(node.channel)} -> ${node.descriptor}`;
      if (node.rateExpr !== undefined) {
        text += ` rate=${printExpression(node.rateExpr)}`;
      }
      if (node.heartbeatExpr !== undefined) {
        text += ` heartbeat=${printExpression(node.heartbeatExpr)}`;
      }
      if (node.payload !== undefined) {
        text += ` payload=${printExpression(node.payload)}`;
      }
      push(out, indent, text, node.span.line, true);
      return;
    }
  }
}

function emitWhen(
  node: ViewNodeIR & { kind: 'when' },
  indent: number,
  head: 'when' | 'else when',
  out: OutLine[],
): void {
  push(out, indent, `${head} ${printExpression(node.test)}`, node.span.line, true);
  node.then.forEach((child) => emitViewNode(child, indent + 1, out));
  if (node.else === undefined) {
    return;
  }
  if (node.else.length === 1 && node.else[0].kind === 'when') {
    emitWhen(node.else[0], indent, 'else when', out);
    return;
  }
  push(out, indent, 'else', node.else[0]?.span.line ?? node.span.line, false);
  node.else.forEach((child) => emitViewNode(child, indent + 1, out));
}

function emitElement(node: ElementNodeIR, indent: number, out: OutLine[]): void {
  const sugar = sugarPrimary(node);
  const parts = [node.tag];
  if (sugar !== null) {
    parts.push(printExpression(sugar.expr));
  }
  nodeAttrs(node).forEach(([name, value]) => {
    parts.push(`${name}=${printExpression(value)}`);
  });
  push(out, indent, parts.join(' '), node.span.line, true);
  (sugar !== null ? sugar.rest : node.children).forEach((child) =>
    emitViewNode(child, indent + 1, out),
  );
}

/** Canonical attr order: props first, then events, each in insertion order
    (authored interleaving is not recoverable from the split records). */
function nodeAttrs(node: { props: Record<string, Expr>; events: Record<string, Expr> }): Array<
  [string, Expr]
> {
  return [...Object.entries(node.props), ...Object.entries(node.events)];
}

/**
 * Primary-arg sugar, the canonical form. `text "Hi" size=13` parses to a
 * bare text child; `button "Save" press=go` parses to a leading propless
 * text-element wrapper. A `text` element whose ONLY child is a wrapper
 * stays explicit: `text <expr>` with no indented children re-parses to the
 * bare-child shape, which would change the IR.
 */
function sugarPrimary(node: ElementNodeIR): { expr: Expr; rest: ViewNodeIR[] } | null {
  const first = node.children[0];
  if (first === undefined) {
    return null;
  }
  if (node.tag === 'text' && node.children.length === 1 && first.kind === 'text') {
    return { expr: first.expr, rest: [] };
  }
  if (
    first.kind !== 'element' ||
    first.tag !== 'text' ||
    Object.keys(first.props).length > 0 ||
    Object.keys(first.events).length > 0 ||
    first.children.length !== 1 ||
    first.children[0].kind !== 'text'
  ) {
    return null;
  }
  if (node.tag === 'text' && node.children.length === 1) {
    return null;
  }
  return { expr: first.children[0].expr, rest: node.children.slice(1) };
}

// ---------------------------------------------------------------------------
// Trivia: comments and blank lines (LLP 0166 §4.6 laws 3–4)
// ---------------------------------------------------------------------------

interface RenderedLine {
  kind: 'code' | 'comment' | 'blank';
  text: string;
  componentHeader: boolean;
}

function renderWithTrivia(lines: OutLine[], source: string): string {
  const blanks = new Set<number>();
  const commentOnly = new Map<number, string>();
  const trailing = new Map<number, string>();
  source.split('\n').forEach((raw, index) => {
    const lineNo = index + 1;
    const code = stripComment(raw);
    if (code.trim().length === 0) {
      if (raw.trim().length === 0) {
        blanks.add(lineNo);
      } else {
        commentOnly.set(lineNo, raw.trim());
      }
    } else if (code.length < raw.length) {
      trailing.set(lineNo, raw.slice(code.length).trimEnd());
    }
  });

  // Trailing comments on lines no formatted line owns (collapsed `else`
  // lines, empty block headers) degrade to comment-only lines.
  const owned = new Set<number>();
  lines.forEach((line) => {
    if (line.owns) {
      owned.add(line.sourceLine);
    }
  });
  [...trailing.keys()].forEach((lineNo) => {
    if (!owned.has(lineNo)) {
      commentOnly.set(lineNo, trailing.get(lineNo)!);
      trailing.delete(lineNo);
    }
  });

  const commentLines = [...commentOnly.keys()].sort((a, b) => a - b);
  let commentIndex = 0;
  const rendered: RenderedLine[] = [];
  let lastSource = 0;
  let lastIndent = 0;
  const consumedTrailing = new Set<number>();

  const hasBlankBetween = (a: number, b: number): boolean => {
    for (let l = a + 1; l < b; l += 1) {
      if (blanks.has(l)) {
        return true;
      }
    }
    return false;
  };
  const pushRendered = (kind: 'code' | 'comment', text: string, sourceLine: number, componentHeader = false): void => {
    if (lastSource > 0 && sourceLine > lastSource && hasBlankBetween(lastSource, sourceLine)) {
      rendered.push({ kind: 'blank', text: '', componentHeader: false });
    }
    rendered.push({ kind, text, componentHeader });
    if (sourceLine > lastSource) {
      lastSource = sourceLine;
    }
  };

  lines.forEach((line) => {
    while (commentIndex < commentLines.length && commentLines[commentIndex] < line.sourceLine) {
      const commentLine = commentLines[commentIndex];
      pushRendered('comment', '  '.repeat(line.indent) + commentOnly.get(commentLine)!, commentLine);
      commentIndex += 1;
    }
    let text = '  '.repeat(line.indent) + line.text;
    if (line.owns && !consumedTrailing.has(line.sourceLine) && trailing.has(line.sourceLine)) {
      text += ` ${trailing.get(line.sourceLine)!}`;
      consumedTrailing.add(line.sourceLine);
    }
    pushRendered('code', text, line.sourceLine, line.componentHeader);
    lastIndent = line.indent;
  });
  while (commentIndex < commentLines.length) {
    const commentLine = commentLines[commentIndex];
    pushRendered('comment', '  '.repeat(lastIndent) + commentOnly.get(commentLine)!, commentLine);
    commentIndex += 1;
  }

  // Exactly one blank line before each component declaration (or before the
  // comment block glued to it), except at file start.
  const spaced: RenderedLine[] = [];
  rendered.forEach((entry) => {
    if (entry.kind === 'code' && entry.componentHeader) {
      let blockStart = spaced.length;
      while (blockStart > 0 && spaced[blockStart - 1].kind === 'comment') {
        blockStart -= 1;
      }
      if (blockStart > 0 && spaced[blockStart - 1].kind !== 'blank') {
        spaced.splice(blockStart, 0, { kind: 'blank', text: '', componentHeader: false });
      }
    }
    spaced.push(entry);
  });

  // Collapse blank runs, strip leading/trailing blanks, single final newline.
  const finalLines: string[] = [];
  spaced.forEach((entry) => {
    if (entry.kind === 'blank') {
      if (finalLines.length > 0 && finalLines[finalLines.length - 1] !== '') {
        finalLines.push('');
      }
      return;
    }
    finalLines.push(entry.text);
  });
  while (finalLines.length > 0 && finalLines[finalLines.length - 1] === '') {
    finalLines.pop();
  }
  return finalLines.join('\n') + '\n';
}
