// @tactical @ref LLP 0297 A3 — W3 deprecation-window instrumentation (ENG-22782)
/**
 * Text-input preflight deprecation counters.
 *
 * The native hosts still dispatch each keystroke synchronously into app JS
 * (`preflightTextInputTransaction`, classification `native-preflight`) and
 * accept it only when app state echoes the proposed text back. LLP 0297 A3
 * retires that capability: after the runtime-thread flip a change handler is
 * an async observer. During the W3 deprecation window every preflight
 * dispatch is recorded here so preflight-dependent fields are discoverable —
 * via `GET /agent/diagnostics` (kind `deprecatedTextInputPreflight`) and a
 * once-per-field dev warning for controlled inputs (the cohort whose
 * semantics actually change).
 *
 * Zero imports on purpose: host-ops is in every native startup graph
 * (startup-budget ratchet, LLP 0128 / LLP 0159 W3-B).
 */

const __DEV__ = process.env.NODE_ENV !== 'production';

export interface TextInputPreflightRecord {
  /** Kernel view id of the input node. */
  viewId: number;
  /** Agent-facing handle when the field declares one. */
  testId?: string;
  nativeId?: string;
  /** Change-event handler id the preflight dispatches into. */
  handlerId: number;
  /**
   * Whether the field looked controlled (`value` prop set) on the most
   * recent dispatch — the controlled round trip is what A3 removes.
   */
  controlled: boolean;
  /** Total sync preflight dispatches observed for this field. */
  dispatchCount: number;
  firstSeenAt: number;
  lastSeenAt: number;
}

const records = new Map<number, TextInputPreflightRecord>();
const warnedViewIds = new Set<number>();

export function recordTextInputPreflightDispatch(entry: {
  viewId: number;
  testId?: string;
  nativeId?: string;
  handlerId: number;
  controlled: boolean;
}): void {
  const now = Date.now();
  const existing = records.get(entry.viewId);
  if (existing) {
    existing.dispatchCount += 1;
    existing.lastSeenAt = now;
    existing.handlerId = entry.handlerId;
    existing.controlled = entry.controlled;
    if (entry.testId !== undefined) {
      existing.testId = entry.testId;
    }
    if (entry.nativeId !== undefined) {
      existing.nativeId = entry.nativeId;
    }
  } else {
    records.set(entry.viewId, {
      ...entry,
      dispatchCount: 1,
      firstSeenAt: now,
      lastSeenAt: now,
    });
  }

  if (__DEV__ && entry.controlled && !warnedViewIds.has(entry.viewId)) {
    warnedViewIds.add(entry.viewId);
    const field =
      entry.testId ?? entry.nativeId ?? `viewId ${String(entry.viewId)}`;
    console.warn(
      `[Exact] TextInput ${field} uses the synchronous keystroke preflight ` +
        `(controlled-input round trip, handler ${String(entry.handlerId)}). ` +
        `LLP 0297 retires this capability: keystrokes become native-owned with ` +
        `async reconciliation. Migrate per docs/text-input-migration.md ` +
        `(editable prop, filter worklets, or async revert).`,
    );
  }
}

export function getTextInputPreflightRecords(): TextInputPreflightRecord[] {
  return Array.from(records.values()).sort((a, b) => a.viewId - b.viewId);
}

/** Test/HMR hook; production records are cumulative per session. */
export function resetTextInputPreflightRecords(): void {
  records.clear();
  warnedViewIds.clear();
}
