// @system @ref LLP 0231 — Runtime Contract dataflow inspector.
import {
  CONTRACT_POINTER_EDGE_EVENTS,
  CONTRACT_POINTER_EVENT_SET,
} from '../compiler/builtin-schema.js';
import type { ActionIR } from '../compiler/ir.js';
import {
  isValueChannelSet,
  type ChannelHostEnvelope,
  type ContractValueChannelSet,
} from './capabilities.js';
import {
  getContractClauseVerdictsForInstance,
  noteContractActionInvocation,
  registerContractMonitorInstance,
} from './contract-monitor.js';
import type { ComponentInstance } from './instance.js';
import {
  getDataReceiptLog,
  resetDataReceiptsForTests,
  setCurrentActionInvocationId,
  setCurrentDataRootId,
} from './receipts.js';
import {
  reactiveChurn,
  reactiveCurrentWave,
  snapshotReactiveGraph,
  untrack,
} from './signals.js';

export interface ContractDataflowSnapshotOptions {
  component?: string;
  instanceId?: string;
  include?: readonly string[];
  sinceActionSeq?: number;
  sinceWave?: number;
  includeValues?: 'none' | 'summary' | 'full';
}

export interface ActualWriteRecord {
  name: string;
  changed: boolean;
}

export interface ActionLogRecord {
  seq: number;
  /**
   * Stable invocation id (`<instanceId>#a<seq>`) — the join key
   * `MutationReceipt.actionInvocationId` carries (LLP 0284 §2.6).
   */
  invocationId: string;
  wave: number;
  atMs: number;
  action: string;
  args: unknown[];
  declaredWrites: string[];
  declaredMutates: string[];
  actualWrites: ActualWriteRecord[];
  writeContractOk: boolean;
  status: 'ok' | 'error';
  error?: string;
}

interface InstanceRecord {
  instanceId: string;
  instance: ComponentInstance;
  mountedAtMs: number;
  highWaterActionSeq: number;
  actionLog: ActionLogRecord[];
}

interface ActiveAction {
  record: InstanceRecord;
  log: ActionLogRecord;
}

const MAX_ACTION_LOG = 200;
let mountEpoch = 1;
let instanceCounter = 1;
let activeAction: ActiveAction | null = null;
// ENG-22560: anchored on globalThis so the agent-relay bundle's copy of this
// module (vite dep-optimization can duplicate @exact/contract between the
// app graph and the relay graph in the dev browser) reads the same records
// the app graph's copy writes — same split-registry fix as the contract
// monitor's `__exactContractMonitorState`. The scalar counters above stay
// module-local: only the app graph's copy registers instances and records
// actions, and their outputs are baked into the records at write time.
function contractDataflowRecords(): Map<ComponentInstance, InstanceRecord> {
  const scope = globalThis as {
    __exactContractDataflowRecords?: Map<ComponentInstance, InstanceRecord>;
  };
  scope.__exactContractDataflowRecords ??= new Map();
  return scope.__exactContractDataflowRecords;
}
const records = contractDataflowRecords();

function summarizeValue(value: unknown, includeValues: 'none' | 'summary' | 'full'): Record<string, unknown> {
  if (includeValues === 'none') {
    return { available: true };
  }
  if (includeValues === 'full') {
    if (typeof value === 'string') return { value };
    if (value === null || typeof value === 'number' || typeof value === 'boolean') {
      return { value };
    }
  }
  if (typeof value === 'string') {
    return {
      valueKind: 'string',
      redacted: true,
      utf16Length: value.length,
      graphemeCount: Array.from(value).length,
    };
  }
  if (Array.isArray(value)) return { valueKind: 'array', length: value.length };
  if (value === null) return { valueKind: 'null', value: null };
  if (typeof value === 'number' || typeof value === 'boolean') {
    return { valueKind: typeof value, value };
  }
  if (typeof value === 'object') {
    return {
      valueKind: 'object',
      keys: Object.keys(value as Record<string, unknown>).slice(0, 8),
    };
  }
  return { valueKind: typeof value };
}

function writeContractOk(declaredWrites: readonly string[], actualWrites: readonly ActualWriteRecord[]): boolean {
  const declared = new Set(declaredWrites);
  const actual = new Set(actualWrites.map((write) => write.name));
  if (declared.size !== actual.size) return false;
  for (const name of declared) {
    if (!actual.has(name)) return false;
  }
  return true;
}

function pushActionLog(record: InstanceRecord, log: ActionLogRecord): void {
  record.highWaterActionSeq = Math.max(record.highWaterActionSeq, log.seq);
  record.actionLog.push(log);
  while (record.actionLog.length > MAX_ACTION_LOG) {
    record.actionLog.shift();
  }
  // Live action-writes clause verdicts (LLP 0278 §2 item 3, dev-gated).
  noteContractActionInvocation(record.instance, record.instanceId, log);
}

/**
 * Set the ambient receipt rootId (LLP 0284 §2.6) to the current mount epoch.
 * Called at the START of component instantiation — binding wiring subscribes
 * (and providers emit `established` receipts) before the instance registers
 * below, so the session key must be primed first.
 */
export function primeContractDataflowSession(): void {
  setCurrentDataRootId(`mount_${mountEpoch}`);
}

export function registerContractDataflowInstance(instance: ComponentInstance): void {
  if (records.has(instance)) return;
  // The mount epoch is the receipt rootId (LLP 0284 §2.6): every instanceId
  // below is prefixed with it, so receipts join the action log and the mount
  // session by construction.
  primeContractDataflowSession();
  const record: InstanceRecord = {
    instance,
    instanceId: `mount_${mountEpoch}/ci_${instanceCounter++}`,
    mountedAtMs: Date.now(),
    highWaterActionSeq: 0,
    actionLog: [],
  };
  records.set(instance, record);
  registerContractMonitorInstance(instance, record.instanceId);
  instance.owner.register(() => {
    records.delete(instance);
    if (records.size === 0) {
      mountEpoch += 1;
      instanceCounter = 1;
    }
  });
}

export function recordContractStateWrite(
  instance: ComponentInstance,
  name: string,
  before: unknown,
  after: unknown,
): void {
  if (!activeAction || activeAction.record.instance !== instance) return;
  const existing = activeAction.log.actualWrites.find((write) => write.name === name);
  const changed = !Object.is(before, after);
  if (existing) {
    existing.changed = existing.changed || changed;
    return;
  }
  activeAction.log.actualWrites.push({ name, changed });
}

export function runContractActionWithLog<T>(
  instance: ComponentInstance,
  action: ActionIR,
  args: unknown[],
  fn: () => T,
): T {
  const record = records.get(instance);
  if (!record) return fn();
  // Reserve the seq at ENTRY (not completion): a nested same-instance action
  // must get a distinct seq — and therefore a distinct invocationId, the
  // §2.6 receipt join key — even though it completes (and logs) first.
  const seq = record.highWaterActionSeq + 1;
  record.highWaterActionSeq = seq;
  const invocationId = `${record.instanceId}#a${seq}`;
  const log: ActionLogRecord = {
    seq,
    invocationId,
    // ENG-23197: read the plain wave counter — reactiveChurn() snapshots the
    // whole reactive graph and this wrapper runs on EVERY action invocation,
    // production included.
    wave: reactiveCurrentWave(),
    atMs: Date.now(),
    action: action.name,
    args: args.map((arg) => summarizeValue(arg, 'summary')),
    declaredWrites: [...(action.writes ?? [])],
    declaredMutates: [...(action.mutates ?? [])],
    actualWrites: [],
    writeContractOk: false,
    status: 'ok',
  };
  const previous = activeAction;
  activeAction = { record, log };
  // Ambient §2.6 join key: provider `mutate` calls run synchronously inside
  // the action body and capture this id onto their mutation receipts.
  setCurrentActionInvocationId(invocationId);
  const finish = (status: 'ok' | 'error', error?: unknown): void => {
    if (status === 'error') {
      log.status = 'error';
      log.error = error instanceof Error ? error.message : String(error);
    }
    log.writeContractOk = writeContractOk(log.declaredWrites, log.actualWrites);
    pushActionLog(record, log);
  };
  const restore = (): void => {
    activeAction = previous;
    setCurrentActionInvocationId(previous ? previous.log.invocationId : null);
  };
  let restoreOnReturn = true;
  try {
    const result = fn();
    if (
      result &&
      typeof (result as unknown as PromiseLike<unknown>).then === 'function'
    ) {
      restoreOnReturn = false;
      return (result as unknown as PromiseLike<unknown>).then(
        (value) => {
          finish('ok');
          restore();
          return value;
        },
        (error) => {
          finish('error', error);
          restore();
          throw error;
        },
      ) as T;
    }
    finish('ok');
    return result;
  } catch (error) {
    finish('error', error);
    throw error;
  } finally {
    if (restoreOnReturn) {
      restore();
    }
  }
}

export function getContractDataflowSnapshot(
  options: ContractDataflowSnapshotOptions = {},
): Record<string, unknown> {
  const includeValues = options.includeValues ?? 'summary';
  const include = new Set(
    options.include ?? [
      'state',
      'derives',
      'bindings',
      'actionLog',
      'clauseVerdicts',
      'receipts',
      'channels',
      'reactive',
    ],
  );
  const allRecords = [...records.values()];
  const candidates = allRecords.filter((record) => {
    if (options.instanceId && record.instanceId !== options.instanceId) return false;
    if (options.component && record.instance.def.ir.name !== options.component) return false;
    return true;
  });
  const record = candidates[0] ?? null;
  if (!record) {
    return {
      instances: allRecords.map((candidate) => ({
        instanceId: candidate.instanceId,
        component: candidate.instance.def.ir.name,
        irRef: `${candidate.instance.def.file.sourcePath ?? 'contract'}#${candidate.instance.def.ir.name}`,
        mountedAtMs: candidate.mountedAtMs,
      })),
      degraded: true,
      degradedReason: 'No mounted Contract component instance matched the query.',
    };
  }

  const { instance } = record;
  const data: Record<string, unknown> = {
    component: instance.def.ir.name,
    instanceId: record.instanceId,
    irRef: `${instance.def.file.sourcePath ?? 'contract'}#${instance.def.ir.name}`,
    highWaterActionSeq: record.highWaterActionSeq,
    degraded: false,
  };

  if (include.has('state')) {
    data.state = instance.def.ir.states.map((state) => {
      const binding = instance.scope.lookup(state.name);
      return {
        name: state.name,
        ...summarizeValue(
          binding && (binding.kind === 'state' || binding.kind === 'getter')
            ? untrack(() => binding.get())
            : undefined,
          includeValues,
        ),
      };
    });
  }

  if (include.has('derives')) {
    data.derives = instance.def.ir.derives.map((derive) => {
      const binding = instance.scope.lookup(derive.name);
      return {
        name: derive.name,
        ...summarizeValue(
          binding && (binding.kind === 'state' || binding.kind === 'getter')
            ? untrack(() => binding.get())
            : undefined,
          includeValues,
        ),
      };
    });
  }

  if (include.has('bindings')) {
    data.bindings = instance.def.ir.actions.map((action) => ({
      handler: action.name,
      resolves: Boolean(instance.scope.lookup(action.name)),
      declaredWrites: [...(action.writes ?? [])],
      declaredMutates: [...(action.mutates ?? [])],
    }));
  }

  if (include.has('actionLog')) {
    data.actionLog = record.actionLog.filter((entry) =>
      options.sinceActionSeq === undefined ? true : entry.seq > options.sinceActionSeq!,
    );
  }

  if (include.has('clauseVerdicts')) {
    // Live contract clause verdicts (LLP 0278 §2 item 3) — queryable through
    // the same agent surface as the action log.
    data.clauseVerdicts = getContractClauseVerdictsForInstance(instance);
  }

  if (include.has('receipts')) {
    // Provider data receipts (LLP 0284 §2.6 / §5 item 5) — global to the
    // runtime, not per-instance: `receipt.rootId` joins the mount session
    // (the `mount_N` prefix of instanceId) and
    // `receipt.actionInvocationId` joins `actionLog[].invocationId`.
    data.receipts = getDataReceiptLog({ limit: 50 });
  }

  if (include.has('channels')) {
    // LLP 0281 §3.5 — value channels are live-observable, never
    // replay-asserted: the current sample, write/coalesce counters, and
    // the publish descriptor facts (declared rate, budget, counters) are
    // readable here; transient value HISTORIES stay excluded from traces
    // and replay by design.
    data.channels = instance.def.ir.behaviors
      .map((behavior) => {
        const binding = instance.scope.lookup(behavior.name);
        const value =
          binding && (binding.kind === 'value' || binding.kind === 'local')
            ? binding.value
            : undefined;
        return isValueChannelSet(value) ? value.__inspect() : null;
      })
      .filter((entry): entry is Record<string, unknown> => entry !== null);
  }

  if (include.has('reactive') || include.has('reactiveGraph')) {
    const churn = reactiveChurn({ sinceWave: options.sinceWave });
    data.reactive = {
      wave: churn.wave,
      churnSinceWave: churn,
      ...(include.has('reactiveGraph') ? { graph: snapshotReactiveGraph() } : {}),
    };
  }

  return data;
}

// ---------------------------------------------------------------------------
// Synthetic pointer injection (LLP 0281 §3.5 / LLP 0275 F1 — ENG-22529)
// ---------------------------------------------------------------------------
//
// The write half of the pointer-channel agent surface. The read half rides
// `getContractDataflowSnapshot`'s `channels` section (live sample + counters);
// this drives `pointerdown/move/up/cancel` sequences INTO those channels
// through the same intake real host input uses — `ValueChannel.writeFromHost`
// with the same `{ sample, element, phase }` envelope the dom-mirror builds
// (LLP 0281 §3.4: edge phases apply immediately, continuous phases coalesce
// per frame). Channel writes are therefore indistinguishable from real input:
// the intake guard, coalescing, capture, and publisher all run unchanged.

/** One step of a synthetic pointer sequence (element-local coordinates). */
export interface ContractPointerInjectStep {
  /** Pointer phase — a Contract pointer event name (`pointerdown`, ...). */
  phase: string;
  x: number;
  y: number;
  pointerId?: number;
  pointerType?: string;
  buttons?: number;
  pressure?: number;
}

export interface ContractPointerInjectOptions {
  /** Component name filter (matches the dataflow snapshot's `component`). */
  component?: string;
  /** Instance id filter (matches the dataflow snapshot's `instanceId`). */
  instanceId?: string;
  /**
   * Channel binding name (`use <name> = pointerChannel(...)`). Optional when
   * the target instance declares exactly one pointer channel.
   */
  channel?: string;
  /**
   * Element box override for publish normalization (`sample.x /
   * element.width`). Omitted, the channel keeps the box its last real
   * envelope measured — so injection never clobbers a measured box with 0×0.
   */
  element?: { width: number; height: number };
  steps: readonly ContractPointerInjectStep[];
}

export interface ContractPointerInjectStepResult {
  phase: string;
  /** True when the phase was delivered non-coalesced (edge semantics, §3.4). */
  immediate: boolean;
  /** True when the channel intake accepted the sample. */
  accepted: boolean;
  reason?: string;
}

export interface ContractPointerInjectResult {
  component?: string;
  instanceId?: string;
  channel?: string;
  channelId?: string;
  requested: number;
  delivered: number;
  rejected: number;
  steps: ContractPointerInjectStepResult[];
  /** The channel's `__inspect()` facts after delivery (live sample/counters). */
  channelState?: Record<string, unknown>;
  degraded: boolean;
  degradedReason?: string;
  /** Candidate channel binding names when the target is ambiguous. */
  availableChannels?: string[];
}

/** Resolve every value-channel set bound on an instance, keyed by binding name. */
function instanceChannelSets(
  instance: ComponentInstance,
): Array<{ name: string; set: ContractValueChannelSet }> {
  const result: Array<{ name: string; set: ContractValueChannelSet }> = [];
  for (const behavior of instance.def.ir.behaviors) {
    const binding = instance.scope.lookup(behavior.name);
    const value =
      binding && (binding.kind === 'value' || binding.kind === 'local')
        ? binding.value
        : undefined;
    if (isValueChannelSet(value)) {
      result.push({ name: behavior.name, set: value });
    }
  }
  return result;
}

/**
 * Inject a synthetic pointer sequence into a Contract pointer channel
 * (LLP 0281 §3.5 / LLP 0275 F1). Runs entirely through the channel's public
 * host intake, so it exercises the real coalescing/edge/capture/publish path
 * — no back door. Returns per-step delivery facts plus the channel's live
 * inspection snapshot for the read-back assertion.
 */
export function injectContractPointerSequence(
  options: ContractPointerInjectOptions,
): ContractPointerInjectResult {
  const steps = Array.isArray(options.steps) ? options.steps : [];
  const requested = steps.length;
  const allRecords = [...records.values()];
  const candidates = allRecords.filter((record) => {
    if (options.instanceId && record.instanceId !== options.instanceId) return false;
    if (options.component && record.instance.def.ir.name !== options.component) return false;
    return true;
  });
  const record = candidates[0] ?? null;
  if (!record) {
    return {
      requested,
      delivered: 0,
      rejected: 0,
      steps: [],
      degraded: true,
      degradedReason: 'No mounted Contract component instance matched the query.',
    };
  }

  const { instance } = record;
  const channelSets = instanceChannelSets(instance);
  if (channelSets.length === 0) {
    return {
      component: instance.def.ir.name,
      instanceId: record.instanceId,
      requested,
      delivered: 0,
      rejected: 0,
      steps: [],
      degraded: true,
      degradedReason: `Component "${instance.def.ir.name}" declares no pointer channel to inject into.`,
    };
  }

  let selected: { name: string; set: ContractValueChannelSet } | undefined;
  if (options.channel) {
    selected = channelSets.find((entry) => entry.name === options.channel);
    if (!selected) {
      return {
        component: instance.def.ir.name,
        instanceId: record.instanceId,
        requested,
        delivered: 0,
        rejected: 0,
        steps: [],
        degraded: true,
        degradedReason: `No pointer channel named "${options.channel}" on component "${instance.def.ir.name}".`,
        availableChannels: channelSets.map((entry) => entry.name),
      };
    }
  } else if (channelSets.length === 1) {
    selected = channelSets[0];
  } else {
    return {
      component: instance.def.ir.name,
      instanceId: record.instanceId,
      requested,
      delivered: 0,
      rejected: 0,
      steps: [],
      degraded: true,
      degradedReason:
        'Multiple pointer channels are bound; specify `channel` to disambiguate.',
      availableChannels: channelSets.map((entry) => entry.name),
    };
  }

  const channel = selected.set.self;
  const stepResults: ContractPointerInjectStepResult[] = [];
  let delivered = 0;
  let rejected = 0;

  for (const step of steps) {
    const phase = typeof step.phase === 'string' ? step.phase : 'pointermove';
    const immediate = CONTRACT_POINTER_EDGE_EVENTS.has(phase);
    if (!CONTRACT_POINTER_EVENT_SET.has(phase)) {
      rejected += 1;
      stepResults.push({
        phase,
        immediate: false,
        accepted: false,
        reason: `unknown pointer phase (expected one of ${[...CONTRACT_POINTER_EVENT_SET].join(', ')})`,
      });
      continue;
    }
    if (
      typeof step.x !== 'number' ||
      !Number.isFinite(step.x) ||
      typeof step.y !== 'number' ||
      !Number.isFinite(step.y)
    ) {
      rejected += 1;
      stepResults.push({
        phase,
        immediate,
        accepted: false,
        reason: 'step requires finite numeric x and y (element-local coordinates)',
      });
      continue;
    }
    const envelope: ChannelHostEnvelope = {
      sample: {
        x: step.x,
        y: step.y,
        pointerId: typeof step.pointerId === 'number' ? step.pointerId : -1,
        pointerType: typeof step.pointerType === 'string' ? step.pointerType : 'synthetic',
        buttons: typeof step.buttons === 'number' ? step.buttons : 0,
        pressure: typeof step.pressure === 'number' ? step.pressure : 0,
      },
      phase,
      ...(options.element ? { element: options.element } : {}),
    };
    const writesBefore = channel.writes;
    channel.writeFromHost(envelope, { immediate });
    const accepted = channel.writes > writesBefore;
    if (accepted) {
      delivered += 1;
    } else {
      rejected += 1;
    }
    stepResults.push({
      phase,
      immediate,
      accepted,
      ...(accepted ? {} : { reason: 'channel intake rejected the sample' }),
    });
  }

  return {
    component: instance.def.ir.name,
    instanceId: record.instanceId,
    channel: selected.name,
    channelId: channel.id,
    requested,
    delivered,
    rejected,
    steps: stepResults,
    channelState: selected.set.__inspect(),
    degraded: false,
  };
}

export function resetContractDataflowInspectorForTests(): void {
  records.clear();
  activeAction = null;
  mountEpoch = 1;
  instanceCounter = 1;
  resetDataReceiptsForTests();
}
