// @system @ref LLP 0234 Slice A/B — Contract built-in element schema authority.

export interface ContractTagLowering {
  tag: string;
  semanticTag?: string;
  staticProps?: Record<string, unknown>;
  staticStyle?: Record<string, unknown>;
}

export type ContractBuiltinAttrKind =
  | 'style'
  | 'text-style'
  | 'prop'
  | 'event'
  | 'special'
  | 'collection'
  | 'overlay';

export interface ContractBuiltinAttrInfo {
  name: string;
  kind: ContractBuiltinAttrKind;
  hostProp?: string;
  appliesTo: readonly string[] | 'all' | 'text-bearing';
  doc: string;
}

