/**
 * Value transforms for lowered style attrs (ENG-22563 / LLP 0293 ledger
 * row 5), keyed by the style prop the attr lowers to. Applied ONLY where a
 * builtin attr lowers to its style prop (the view runtime's attr paths and
 * hot-patch attr slot edits) — never in the generic style plumbing, so
 * `style=` escape-hatch writers keep full CSS control and the host-agnostic
 * style path carries no web-CSS sugar. This is the single seam to swap when
 * the native kernel wants a structured track list instead of a CSS string
 * (Taffy grid).
 */
export const CONTRACT_LOWERED_STYLE_VALUE_TRANSFORMS: Record<
  string,
  (value: unknown) => unknown
> = {
  // `grid cols=3` sugar: a bare column count expands to the equal-track
  // template; strings pass through for full CSS control.
  gridTemplateColumns: (value) =>
    typeof value === 'number' && Number.isFinite(value)
      ? `repeat(${Math.max(1, Math.trunc(value))}, minmax(0, 1fr))`
      : value,
};

/** Applies the lowered-attr value transform for `styleProp`, if one exists. */
export function transformLoweredStyleValue(styleProp: string, value: unknown): unknown {
  const transform = CONTRACT_LOWERED_STYLE_VALUE_TRANSFORMS[styleProp];
  return transform ? transform(value) : value;
}

