// LLP 0281 §3.3 — the channel sink allowlist lives in the presentation-sink
// authority (`./presentation-sinks.ts`, the OQ3 home), NOT in this general
// style map: this file answers "which attrs exist"; that file answers
// "which attrs a per-frame, non-transactional lane may drive".

function mapAttrEntries(
  values: Record<string, string>,
  kind: ContractBuiltinAttrKind,
  appliesTo: ContractBuiltinAttrInfo['appliesTo'],
  docPrefix: string,
): ContractBuiltinAttrInfo[] {
  return Object.entries(values).map(([name, hostProp]) => ({
    name,
    kind,
    hostProp,
    appliesTo,
    doc: `${docPrefix}; lowers to \`${hostProp}\`.`,
  }));
}

function directPropEntries(
  names: readonly string[],
  appliesTo: ContractBuiltinAttrInfo['appliesTo'],
  doc: string,
  kind: ContractBuiltinAttrKind = 'prop',
): ContractBuiltinAttrInfo[] {
  return names.map((name) => ({
    name,
    kind,
    hostProp: name,
    appliesTo,
    doc,
  }));
}

