export const CONTRACT_SCHEMA_ATTRS = Array.from(
  new Set(CONTRACT_BUILTIN_ATTRS.filter((attr) => attr.kind !== 'event').map((attr) => attr.name)),
).sort();

export function builtinAttrInfo(tag: string, attrName: string): ContractBuiltinAttrInfo | undefined {
  return CONTRACT_BUILTIN_ATTRS.find(
    (attr) => attr.name === attrName && attrAppliesToTag(attr, tag),
  );
}

export function allowedBuiltinAttrs(tag: string): string[] {
  return Array.from(
    new Set(
      CONTRACT_BUILTIN_ATTRS.filter((attr) => attr.kind !== 'event' && attrAppliesToTag(attr, tag)).map(
        (attr) => attr.name,
      ),
    ),
  ).sort();
}

export function builtinAttrHoverMarkdown(tag: string, attrName: string): string | null {
  const attr = builtinAttrInfo(tag, attrName);
  if (!attr) return null;
  const target = attr.hostProp && attr.hostProp !== attr.name ? `\n\nLowers to \`${attr.hostProp}\`.` : '';
  return `**${attr.kind} attr** \`${attr.name}\` on \`${tag}\`\n\n${attr.doc}${target}`;
}

export function nearestBuiltinAttr(tag: string, attrName: string): string | undefined {
  const allowed = allowedBuiltinAttrs(tag).filter((candidate) => candidate !== attrName);
  const hostPropMatch = CONTRACT_BUILTIN_ATTRS.find(
    (candidate) =>
      candidate.hostProp === attrName &&
      candidate.name !== attrName &&
      attrAppliesToTag(candidate, tag),
  );
  if (hostPropMatch) {
    return hostPropMatch.name;
  }
  return nearestName(attrName, allowed);
}

/**
 * Generic did-you-mean lookup: the closest candidate to `name` — an exact
 * case-insensitive match first, then the smallest Levenshtein distance ≤ 3.
 * Shared by attr typo suggestions and shape member typo suggestions
 * (ENG-22500).
 */
export function nearestName(name: string, candidates: Iterable<string>): string | undefined {
  const lower = name.toLowerCase();
  let best: { value: string; distance: number } | undefined;
  for (const candidate of candidates) {
    if (candidate === name) {
      continue;
    }
    const candidateLower = candidate.toLowerCase();
    if (candidateLower === lower) {
      return candidate;
    }
    const distance = levenshtein(lower, candidateLower);
    if (distance <= 3 && (!best || distance < best.distance)) {
      best = { value: candidate, distance };
    }
  }
  return best?.value;
}

function attrAppliesToTag(attr: ContractBuiltinAttrInfo, tag: string): boolean {
  if (attr.appliesTo === 'all') return true;
  if (attr.appliesTo === 'text-bearing') return CONTRACT_TEXT_BEARING_TAG_SET.has(tag);
  return attr.appliesTo.includes(tag);
}

function levenshtein(left: string, right: string): number {
  const rows = Array.from({ length: left.length + 1 }, (_, index) => index);
  for (let r = 1; r <= right.length; r += 1) {
    let prev = rows[0]!;
    rows[0] = r;
    for (let c = 1; c <= left.length; c += 1) {
      const current = rows[c]!;
      rows[c] =
        left[c - 1] === right[r - 1]
          ? prev
          : Math.min(prev + 1, rows[c]! + 1, rows[c - 1]! + 1);
      prev = current;
    }
  }
  return rows[left.length]!;
}
