// @system @ref LLP 0183 S0 — JSON-serializable Contract import descriptors.

// Import descriptor normalization from the compiler-dependency-free leaf:
// this module ships in client bundles (`@exact/contract/channels`, app-side
// `.contract-meta.ts` sidecars), and importing `./compiler/import-boundaries.js`
// here would drag `purity-inference.ts` — and with it the entire `typescript`
// package — into the browser graph (ENG-22537: dev-green, ship-broken).
import {
  normalizeContractImportDescriptor,
  type ContractImportDescriptorInput,
  type ContractImportDescriptorMap,
} from './compiler/descriptor-normalize.js';
import type {
  ContractImportDescriptor,
  PureImportDescriptor,
  QueryImportDescriptor,
  ShapeImportDescriptor,
  StoreImportDescriptor,
  StyleRecipeImportDescriptor,
} from './compiler/ir.js';

type DescriptorDraft<T extends ContractImportDescriptor> =
  Omit<T, 'kind' | 'confidence' | 'provenance'>;

export function defineContractExports<T extends ContractImportDescriptorMap>(exports: T): T {
  for (const [name, descriptor] of Object.entries(exports)) {
    normalizeContractImportDescriptor(descriptor, { confidence: 'declared' });
    if (!name) {
      throw new Error('Contract export descriptors must be keyed by symbol name');
    }
  }
  return exports;
}

export function defineContractModule(
  moduleSpecifier: string,
  exports: ContractImportDescriptorMap,
): { module: string; exports: ContractImportDescriptorMap } {
  if (!moduleSpecifier) {
    throw new Error('defineContractModule requires a module specifier');
  }
  defineContractExports(exports);
  return { module: moduleSpecifier, exports };
}

export function component(): ContractImportDescriptorInput {
  return { kind: 'component' };
}

export function pure(descriptor: DescriptorDraft<PureImportDescriptor>): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'pure' };
}

export function shape(descriptor: DescriptorDraft<ShapeImportDescriptor>): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'shape' };
}

export function styleRecipe(
  descriptor: DescriptorDraft<StyleRecipeImportDescriptor>,
): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'styleRecipe' };
}

export function store(descriptor: DescriptorDraft<StoreImportDescriptor> = {}): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'store' };
}

export function capability(
  descriptor: {
    params?: Record<string, unknown>;
    effects: string[];
    /** LLP 0281 stage 0: marks a value-channel capability (e.g. 'pointer'). */
    channel?: string;
  },
): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'capability' };
}

export function query(descriptor: DescriptorDraft<QueryImportDescriptor>): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'query' };
}

export function mutation(
  descriptor: {
    params?: Record<string, unknown>;
    effects: string[];
    invalidates?: string[];
    /**
     * LLP 0281 stage 0: provider publish budget facts on mutation-shaped
     * ephemeral publish descriptors (transitional — prefer the `publish`
     * descriptor kind; the analyzer checks a `publish` line's declared
     * `rate` against `sustainedHz` on either shape).
     */
    publishBudget?: { sustainedHz?: number; burst?: number; maxValueBytes?: number };
  },
): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'mutation' };
}

/**
 * LLP 0281 §3.1 (ENG-22525) — a generated `*.publish.ts` ephemeral publish
 * descriptor: the target of the rated `publish <channel> -> <descriptor>
 * rate=N` view line. `budget` carries the provider facts (Snapback LLP 0034
 * §4 emits them) the declared rate is checked against at compile time.
 */
export function publish(
  descriptor: {
    params?: Record<string, unknown>;
    effects: string[];
    budget?: { sustainedHz?: number; burst?: number; maxValueBytes?: number };
  },
): ContractImportDescriptorInput {
  return { ...descriptor, kind: 'publish' };
}

export function opaque(): ContractImportDescriptorInput {
  return { kind: 'opaque' };
}

export type {
  ContractImportDescriptor,
  ContractImportDescriptorInput,
  ContractImportDescriptorMap,
  PureImportDescriptor,
  QueryImportDescriptor,
  ShapeImportDescriptor,
  StoreImportDescriptor,
  StyleRecipeImportDescriptor,
};
