// @system @ref LLP 0080 — Contract v0 lexer.
//
// The v0 notation is line-oriented and indentation-structured (2 spaces per
// level, tabs invalid). The lexer produces logical lines, each with an
// indent depth and a flat token stream; the parser owns block structure.

import type { Diagnostic, Span } from './ir.js';

/**
 * Absolute token position (LLP 0166 S0a). `start`/`end` are 0-based offsets
 * into the string passed to `lex()`, in UTF-16 code units; `end` is
 * exclusive. On the main compile path that string is the whole file, so the
 * offsets are absolute file offsets.
 */
export interface TokenPos {
  start: number;
  end: number;
}

export type Token =
  | ({ kind: 'ident'; value: string } & TokenPos)
  // `raw` on string/number tokens is the exact source slice (LLP 0158 D2:
  // anchors minimal-range instance edits without column-tracking the IR).
  | ({ kind: 'string'; value: string; raw?: string } & TokenPos)
  | ({ kind: 'template'; raw: string } & TokenPos)
  | ({ kind: 'number'; value: number; raw?: string } & TokenPos)
  | ({ kind: 'punct'; value: string } & TokenPos)
  | ({ kind: 'arrow' } & TokenPos); // ->

export interface LogicalLine {
  indent: number;
  line: number;
  /** Offset of this line's first character (column 1) in the lexed source. */
  lineStart: number;
  tokens: Token[];
}

export class ContractLexError extends Error {
  readonly diagnostic: Diagnostic;

  constructor(diagnostic: Diagnostic) {
    super(`${diagnostic.span ? `${diagnostic.span.line}:${diagnostic.span.col}` : `line ${diagnostic.line}`}: ${diagnostic.message}`);
    this.name = 'ContractLexError';
    this.diagnostic = diagnostic;
  }
}

const PUNCT_THREE = ['===', '!=='];
const PUNCT_TWO = ['=>', '==', '!=', '<=', '>=', '&&', '||', '??', '?.'];
// Single `|` exists for literal-union type annotations (LLP 0166 §4.5);
// `||` matches first, so expression lexing is unaffected.
const PUNCT_ONE = '()[]{}=,:.<>+-*/%!?|'.split('');

export function lex(source: string): LogicalLine[] {
  const lines: LogicalLine[] = [];
  const rawLines = source.split('\n');
  let lineStart = 0;

  for (let i = 0; i < rawLines.length; i += 1) {
    const raw = rawLines[i];
    const lineNumber = i + 1;
    const thisLineStart = lineStart;
    lineStart += raw.length + 1; // +1 for the '\n' (absent on the last line; harmless)
    const tabIndex = raw.indexOf('\t');
    if (tabIndex !== -1) {
      throw lexError(
        lineNumber,
        'tabs are invalid; indent with 2 spaces per level',
        spanAt(lineNumber, thisLineStart, thisLineStart + tabIndex, 1),
      );
    }

    // Strip comments (`//` outside strings) and skip blank lines.
    const withoutComment = stripComment(raw);
    if (withoutComment.trim().length === 0) {
      continue;
    }

    const indentSpaces = withoutComment.length - withoutComment.trimStart().length;
    if (indentSpaces % 2 !== 0) {
      throw lexError(
        lineNumber,
        `indentation must be a multiple of 2 spaces (got ${indentSpaces})`,
        spanAt(lineNumber, thisLineStart, thisLineStart, Math.max(indentSpaces, 1)),
      );
    }

    // Token offsets are relative to the trimmed text; rebase them to the
    // lexed source via lineStart + indent (stripComment only truncates the
    // tail, and CRLF '\r' chars fall in the trimmed tail, so the math holds
    // for both LF and CRLF sources).
    const tokens = lexLine(
      withoutComment.trim(),
      lineNumber,
      thisLineStart + indentSpaces,
      thisLineStart,
    );
    lines.push({ indent: indentSpaces / 2, line: lineNumber, lineStart: thisLineStart, tokens });
  }

  return lines;
}

/**
 * Truncates a physical line at its `//` comment (string-aware). Exported for
 * the formatter's trivia scan (LLP 0166 §4.6) so comment detection has one
 * authority; the lexer itself discards what this strips.
 */
export function stripComment(raw: string): string {
  let inString: string | null = null;
  for (let i = 0; i < raw.length; i += 1) {
    const ch = raw[i];
    if (inString) {
      if (ch === '\\') {
        i += 1;
      } else if (ch === inString) {
        inString = null;
      }
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      inString = ch;
      continue;
    }
    if (ch === '/' && raw[i + 1] === '/') {
      return raw.slice(0, i);
    }
  }
  return raw;
}

function lexLine(text: string, line: number, base = 0, lineStart = base): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < text.length) {
    const ch = text[i];

    if (ch === ' ') {
      i += 1;
      continue;
    }

    // Strings
    if (ch === '"' || ch === "'") {
      const { value, end } = readString(text, i, ch, line, base, lineStart);
      tokens.push({ kind: 'string', value, raw: text.slice(i, end), start: base + i, end: base + end });
      i = end;
      continue;
    }

    // Template strings (kept raw; the expression parser re-parses parts).
    // The token span covers backtick to backtick inclusive; `raw` is the
    // inner content (starts at start + 1 in the lexed source).
    if (ch === '`') {
      const end = findTemplateEnd(text, i, line, base, lineStart);
      tokens.push({ kind: 'template', raw: text.slice(i + 1, end), start: base + i, end: base + end + 1 });
      i = end + 1;
      continue;
    }

    // Numbers
    if (/[0-9]/.test(ch) || (ch === '.' && /[0-9]/.test(text[i + 1] ?? ''))) {
      let j = i;
      while (j < text.length && /[0-9_.]/.test(text[j])) {
        j += 1;
      }
      const rawNumber = text.slice(i, j).replace(/_/g, '');
      const value = Number(rawNumber);
      if (Number.isNaN(value)) {
        throw lexError(
          line,
          `invalid number literal "${text.slice(i, j)}"`,
          spanAt(line, lineStart, base + i, j - i),
        );
      }
      tokens.push({ kind: 'number', value, raw: text.slice(i, j), start: base + i, end: base + j });
      i = j;
      continue;
    }

    // Identifiers / keywords. Hyphens are always operators (so `a-b` is
    // subtraction); v0 prop names are camelCase, not kebab-case.
    if (/[A-Za-z_$]/.test(ch)) {
      let j = i;
      while (j < text.length && /[A-Za-z0-9_$]/.test(text[j])) {
        j += 1;
      }
      tokens.push({ kind: 'ident', value: text.slice(i, j), start: base + i, end: base + j });
      i = j;
      continue;
    }

    // Arrow `->` (contract clauses)
    if (ch === '-' && text[i + 1] === '>') {
      tokens.push({ kind: 'arrow', start: base + i, end: base + i + 2 });
      i += 2;
      continue;
    }

    // Spread `...` (array/object literal spread — LLP 0277 §4.2). Checked
    // before single-char puncts so it never lexes as three member dots.
    if (ch === '.' && text[i + 1] === '.' && text[i + 2] === '.') {
      tokens.push({ kind: 'punct', value: '...', start: base + i, end: base + i + 3 });
      i += 3;
      continue;
    }

    const three = text.slice(i, i + 3);
    if (PUNCT_THREE.includes(three)) {
      tokens.push({ kind: 'punct', value: three === '===' ? '==' : '!=', start: base + i, end: base + i + 3 });
      i += 3;
      continue;
    }

    const two = text.slice(i, i + 2);
    if (PUNCT_TWO.includes(two)) {
      tokens.push({ kind: 'punct', value: two, start: base + i, end: base + i + 2 });
      i += 2;
      continue;
    }

    if (PUNCT_ONE.includes(ch)) {
      tokens.push({ kind: 'punct', value: ch, start: base + i, end: base + i + 1 });
      i += 1;
      continue;
    }

    throw lexError(
      line,
      `unexpected character "${ch}"`,
      spanAt(line, lineStart, base + i, 1),
    );
  }

  return tokens;
}

function readString(
  text: string,
  start: number,
  quote: string,
  line: number,
  base: number,
  lineStart: number,
): { value: string; end: number } {
  let value = '';
  let i = start + 1;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '\\') {
      const next = text[i + 1];
      const escapes: Record<string, string> = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', "'": "'", '`': '`' };
      value += escapes[next] ?? next;
      i += 2;
      continue;
    }
    if (ch === quote) {
      return { value, end: i + 1 };
    }
    value += ch;
    i += 1;
  }
  throw lexError(
    line,
    'unterminated string literal',
    spanAt(line, lineStart, base + start, Math.max(text.length - start, 1)),
  );
}

function findTemplateEnd(
  text: string,
  start: number,
  line: number,
  base: number,
  lineStart: number,
): number {
  let i = start + 1;
  let depth = 0;
  let inString: string | null = null;
  while (i < text.length) {
    const ch = text[i];
    if (ch === '\\') {
      i += 2;
      continue;
    }
    // Braces and backticks inside string literals within ${...} are content,
    // not structure.
    if (inString) {
      if (ch === inString) {
        inString = null;
      }
      i += 1;
      continue;
    }
    if (depth > 0 && (ch === '"' || ch === "'")) {
      inString = ch;
      i += 1;
      continue;
    }
    if (ch === '$' && text[i + 1] === '{') {
      depth += 1;
      i += 2;
      continue;
    }
    if (ch === '{' && depth > 0) {
      depth += 1;
      i += 1;
      continue;
    }
    if (ch === '}' && depth > 0) {
      depth -= 1;
      i += 1;
      continue;
    }
    if (ch === '`' && depth === 0) {
      return i;
    }
    i += 1;
  }
  throw lexError(
    line,
    'unterminated template literal',
    spanAt(line, lineStart, base + start, Math.max(text.length - start, 1)),
  );
}

function spanAt(line: number, lineStart: number, offset: number, len: number): Span {
  return {
    line,
    col: offset - lineStart + 1,
    offset,
    len,
  };
}

function lexError(line: number, message: string, span?: Span): ContractLexError {
  return new ContractLexError({
    severity: 'error',
    message,
    line,
    code: 'lex_error',
    span,
  });
}
