// @system @ref LLP 0264 S3 — typed headless host-ops inspection helpers.

import type { ElementNode, RootNode, TextNode } from '@exact/renderer/host-ops';

import type { MountHandle } from './mount.js';

type InspectNode = ElementNode | TextNode;

export interface ContractInspectTree {
  readonly root: RootNode;
  all(): ContractInspectElement[];
  byTestId(testId: string): ContractInspectElement;
  byLabel(label: string): ContractInspectElement;
  byText(text: string): ContractInspectElement;
  maybeByTestId(testId: string): ContractInspectElement | null;
}

export class ContractInspectElement {
  constructor(readonly node: ElementNode) {}

  get props(): Record<string, unknown> {
    return this.node.originalProps;
  }

  get testId(): string | undefined {
    const props = this.props;
    return typeof props.testId === 'string'
      ? props.testId
      : typeof props.testID === 'string'
        ? props.testID
        : undefined;
  }

  text(): string {
    const out: string[] = [];
    const visit = (node: InspectNode): void => {
      if (isTextNode(node)) {
        out.push(node.text);
        return;
      }
      node.children.forEach(visit);
    };
    visit(this.node);
    return out.join('');
  }

  asButton(): ContractInspectButton {
    return new ContractInspectButton(this.node);
  }

  asInput(): ContractInspectInput {
    return new ContractInspectInput(this.node);
  }
}

export class ContractInspectButton extends ContractInspectElement {
  press(payload?: unknown): void {
    const handler = this.props.onPress;
    if (typeof handler !== 'function') {
      throw new Error(`[contract] inspected node ${describeNode(this.node)} has no press handler`);
    }
    handler(payload);
  }
}

export class ContractInspectInput extends ContractInspectElement {
  change(value: string): void {
    const handler = this.props.onChangeText ?? this.props.onValueChange ?? this.props.onChange;
    if (typeof handler !== 'function') {
      throw new Error(`[contract] inspected node ${describeNode(this.node)} has no change handler`);
    }
    handler(value);
  }

  submit(payload?: unknown): void {
    const handler = this.props.onSubmitEditing ?? this.props.onSubmit;
    if (typeof handler !== 'function') {
      throw new Error(`[contract] inspected node ${describeNode(this.node)} has no submit handler`);
    }
    handler(payload);
  }
}

export function contractInspect(handle: MountHandle | RootNode): ContractInspectTree {
  const root = 'container' in handle ? handle.container : handle;
  const elements = (): ContractInspectElement[] => {
    const out: ContractInspectElement[] = [];
    const visit = (node: InspectNode): void => {
      if (isTextNode(node)) {
        return;
      }
      out.push(new ContractInspectElement(node));
      node.children.forEach(visit);
    };
    root.children.forEach(visit);
    return out;
  };

  const find = (
    description: string,
    predicate: (node: ContractInspectElement) => boolean,
  ): ContractInspectElement => {
    const found = elements().find(predicate);
    if (!found) {
      throw new Error(`[contract] inspect could not find ${description}`);
    }
    return found;
  };

  return {
    root,
    all: elements,
    byTestId(testId: string): ContractInspectElement {
      return find(`testId=${JSON.stringify(testId)}`, (element) => element.testId === testId);
    },
    maybeByTestId(testId: string): ContractInspectElement | null {
      return elements().find((element) => element.testId === testId) ?? null;
    },
    byLabel(label: string): ContractInspectElement {
      return find(`label=${JSON.stringify(label)}`, (element) => {
        const props = element.props;
        return props.label === label ||
          props.accessibilityLabel === label ||
          props['aria-label'] === label;
      });
    },
    byText(text: string): ContractInspectElement {
      return find(`text=${JSON.stringify(text)}`, (element) => element.text() === text);
    },
  };
}

function isTextNode(node: InspectNode): node is TextNode {
  return 'text' in node && typeof node.text === 'string';
}

function describeNode(node: ElementNode): string {
  const props = node.originalProps;
  const testId = typeof props.testId === 'string'
    ? props.testId
    : typeof props.testID === 'string'
      ? props.testID
      : undefined;
  return testId ? `testId=${JSON.stringify(testId)}` : `${node.originalTag}#${node.id}`;
}
